  chapters = {
    ["ages-past"] = { "Vergangene Zeitalter", "Die Geschichte der Welt, von den Titanen bis zum letzten Krieg, wie die alten Bücher in ihren Bibliotheken sie erzählen." },
    ["alterac"] = { "Alteracgebirge", "Ein gefallenes Königreich im Schnee, Dalaran am See und ein Tal, um das zwei Völker streiten." },
    ["arathi"] = { "Arathihochland", "Die Wiege der Königreiche der Menschen, verfallen und noch immer umkämpft." },
    ["ashenvale"] = { "Ashenvale", "Der uralte Wald der Nachtelfen, und die Äxte der Orcs an seinem Rand." },
    ["azshara"] = { "Azshara", "Das Land der Königin, am Ufer des Meeres, das sie verschlang." },
    ["badlands"] = { "Ödland", "Eine rote Öde aus Schluchten, und darunter das Gewölbe der Titanen, Uldaman." },
    ["barrens"] = { "Brachland", "Die große trockene Savanne im Herzen Kalimdors, und alle, die darum kämpfen." },
    ["blackrock-mountain"] = { "Der Blackrock", "Der Berg des Feuerlords, und der Krieg in seinem Inneren." },
    ["blasted-lands"] = { "Verwüstete Lande", "Die rote Öde um das Dunkle Portal." },
    ["burning-steppes"] = { "Brennende Steppe", "Die Aschenebene südlich des Berges, wo einst das Rotkammgebirge lag." },
    ["callings"] = { "Die Berufungen", "Die Wege der Waffen, des Glaubens und der Magie, die ein Reisender gehen kann, und woher jeder von ihnen kommt." },
    ["darkshore"] = { "Dunkelküste", "Eine lange, neblige Küste voller Ruinen der Nachtelfen, jenseits des Wassers gegenüber dem Weltenbaum." },
    ["deadwind-pass"] = { "Gebirgspass der Totenwinde", "Das tote Tal des letzten Wächters." },
    ["desolace"] = { "Desolace", "Ein graues, totes Land der Zentauren, Knochen und Dämonen." },
    ["dun-morogh"] = { "Dun Morogh und Ironforge", "Die verschneiten Täler um Ironforge, die Wiege des Bronzebeardklans." },
    ["durotar"] = { "Durotar und Orgrimmar", "Das rote Land, das Thrall seinem Volk gab, und die Stadt, die nach dem Kriegshäuptling benannt ist, der sie befreite." },
    ["duskwood"] = { "Dämmerwald", "Ein Wald, in dem die Nacht nie ganz endet und die Toten nicht begraben bleiben." },
    ["dustwallow"] = { "Marschen von Dustwallow", "Lady Proudmoores Inselstadt, ein Sumpf voller Drachen und ein Gasthaus, das niederbrannte." },
    ["eastern-plaguelands"] = { "Östliche Pestländer", "Das alte Eastweald, Stratholme und die Nekropole am Himmel." },
    ["elwynn"] = { "Wald von Elwynn und Stormwind", "Das Herz des Königreichs der Menschen: sein Wald, seine Höfe und die weiße Stadt, aus der Asche wiederaufgebaut." },
    ["felwood"] = { "Teufelswald", "Der vergiftete Wald, in dem der Schädel von Gul'dan gefunden wurde." },
    ["feralas"] = { "Feralas", "Riesige Bäume, Oger und die Ruinen der Hochgeborenen." },
    ["hillsbrad"] = { "Vorgebirge von Hillsbrad", "Grüne Hügel, auf denen Lebende und Verlassene um jeden Hof kämpfen." },
    ["hinterlands"] = { "Hinterland", "Wilde Hügel der Wildhammerzwerge, und die Tempel der Trolle, mit denen sie sie teilen." },
    ["loch-modan"] = { "Loch Modan", "Das Seenland östlich von Ironforge, von einem Damm gehalten und von Königen aus Stein bewacht." },
    ["moonglade"] = { "Moonglade", "Das heilige Tal der Druiden." },
    ["mulgore"] = { "Mulgore und Thunder Bluff", "Die grünen Ebenen der Tauren, und die Stadt auf den Tafelbergen." },
    ["peoples"] = { "Völker und Mächte", "Die Völker, Orden und Fraktionen, denen ein Reisender in vielen Ländern begegnet, an einem Ort versammelt." },
    ["redridge"] = { "Rotkammgebirge", "Rote Hügel, ein stiller See und eine Stadt, die von Norden her belagert wird." },
    ["searing-gorge"] = { "Sengende Schlucht", "Die verbrannte Nordseite des Berges, und die große Grube der Dunkeleisenzwerge." },
    ["shen-dralas"] = { "Shen'dralas", "Das verfluchte Land um das Tal der Knochen, wo die Zentauren die Toten gefunden haben." },
    ["silithus"] = { "Silithus", "Die Wüste der Insekten, der Skarabäuswall und das, was dahinter schläft." },
    ["silverpine"] = { "Silberwald", "Graue Kiefern zwischen den Verlassenen und dem verschlossenen Tor von Gilneas." },
    ["stonetalon"] = { "Steinkrallengebirge", "Hohe Gipfel und alte Wälder, die unter den Sägen der Goblins brennen." },
    ["stranglethorn"] = { "Schlingendorntal", "Der Dschungel des alten Trollreichs, wo Piraten, Jäger und Goblins ihr Glück machen." },
    ["swamp-of-sorrows"] = { "Sümpfe des Elends", "Ein ertrunkenes Land aus Nebel und Morast, und ein Tempel, der für seine Sünden versank." },
    ["tanaris"] = { "Tanaris", "Die große Wüste des Südens, und die Tore der Wächter." },
    ["teldrassil"] = { "Teldrassil und Darnassus", "Der neue Weltenbaum der Nachtelfen, und die Stadt in seiner Krone." },
    ["thousand-needles"] = { "Tausend Nadeln", "Eine Schlucht aus Steinnadeln, und eine Salzebene, auf der Goblins und Gnome Rennen fahren." },
    ["tirisfal"] = { "Tirisfal und Undercity", "Das Kernland des gefallenen Lordaeron, und die Verlassenen, die unter seiner zerstörten Hauptstadt herrschen." },
    ["ungoro-crater"] = { "Un'Goro-Krater", "Eine verlorene Welt in einem Krater, und die rätselhaften Kristalle." },
    ["western-plaguelands"] = { "Westliche Pestländer", "Das tote Herz Lordaerons, wo die Seuche begann." },
    ["westfall"] = { "Westfall", "Die Kornkammer Stormwinds, zu Staub und Banditen verkommen." },
    ["wetlands"] = { "Sumpfland", "Die Marschen zwischen Khaz Modan und Arathi, wo die Straßen der Zwerge in alte Kriege münden." },
    ["winterspring"] = { "Winterspring", "Schnee, Goblins und der Fluch der Hochgeborenen." },
    ["zephras-isle"] = { "Die Insel Zephras", "Die fliegende Insel der Himmelsgeborenen, im Himmelswall." },
  },
  -- the game's own texts, by their English titles: each text's pages, and
  -- the start of its English first page (to tell apart those sharing a title)
  books = {
    ["A Bloodstained Envelope"] = { { ids = { "i22930" }, first = "myemilyafewshortdaysagow", pages = { "Liebste Emily,\n\nVor einigen Tagen haben wir auf Befehl des Königs unsere Lager an diesem vom Licht verlassenen Ort abgebrochen, um in die Heimat zurückzukehren. Trotz der hier herrschenden Trostlosigkeit, quoll mein Herz vor Freude fast über, denn ich wusste, dass ich am Ende dieser mörderischen Reise endlich in deinen Armen Trost finden würde.\n\nHeute trafen wir an der Küste ein, nur um festzustellen, dass von unseren Schiffen nur noch brennendes Treibgut übrig war. Der Weg nach Hause ist uns damit versperrt und uns bleibt nur noch die Möglichkeit, in das Innere dieses teuflischen Ödlandes zu marschieren.\n\nIch bin bis an das Ende der Welt gereist, um dich zu beschützen, liebste Emily... und jetzt... ich wünschte, ich wäre bei dir in Lordaeron geblieben.\n\nIn jedem wachen Moment denke ich an dich. Die Gedanken an dich wärmen mich in diesem eisigen Land, Liebste, und niemand kann dich mir wegnehmen.\n\nMaxwell" } } },
    ["A Bloodstained Journal Page"] = { { ids = { "i939" }, first = "downwardspiralofdespairf", pages = { ". . .Abwärtsspirale der Verzweiflung. Erst verspottet sie mich, und nun ist sie verlobt. Die undankbare Scharlatanin hat Liebe nur vorgetäuscht, während sie mich die ganze Zeit verletzen wollte. Eine schwarze Leere lauert nun in mir, und sie wächst mit jedem wachen Augenblick. Das Blut, das ich vergießen werde, verblasst neben den Tränen, die ich vergossen habe. . ." } } },
    ["A Careworn Note"] = { { ids = { "i22945" }, first = "dearestameliatonightihav", pages = { "Liebste Amelia,\n\nich habe diese Nacht Dinge gesehen, die mich bis an mein Lebensende verfolgen werden.\n\nStratholme steht in Flammen... und wir sind dafür verantwortlich.\n\nUnser Prinz hat uns in der Nacht in die Straßen der Stadt geführt. Er befahl uns in die Häuser der Stadtbewohner einzubrechen und... sie in ihrem Schlaf zu töten. Lord Arthas hat behauptet, sie seien verseucht und müssten getötet werden, bevor sie uns selbst töten würden.\n\nEs war ein Gemetzel. Hunderte starben schweigend unter den Schwertern, die sie einst beschützen sollten. Ich hielt es nicht mehr aus und floh.\n\nIch mag zwar ein Deserteur sein, aber diese Gräueltaten ließen mir keine andere Wahl. In jedem dieser Häuser sah ich dich oder unsere Kinder unter den toten Opfern. Sollte ich jetzt deswegen als Verräter gelten, dann soll es so sein.\n\nIch hoffe, dass ich bald wieder bei dir sein werde, aber die Straßen sind gefährlich. Umarme unsere Kinder für mich.\n\nJames" } } },
    ["A Clue to Sander's Treasure"] = { { ids = { "i1358" }, first = "goodworkmateynowyeneedto", pages = { "Gut gemacht, Kumpel! Jetzt müsst Ihr Euch imma nach Ost'n halten. Östlich von der Straße die Steilhänge hoch. Schaut Euch nach so 'nem ollen verfallenen Kamin nahe bei der Straße um. Dort findet Ihr'n altes Fass mit Eurem nächsten Hinweis drin." } } },
    ["A Crumpled Missive"] = { { ids = { "i22944" }, first = "helianaivargusyetlivedes", pages = { "Heliana,\n\nich, Vargus, bin immer noch am Leben, auch wenn Ihr Euch das Gegenteil wünscht. Ich hasse es in dieser lächerlichen Rüstung durch die Lande zu ziehen.\n\nUnsere letzten Anweisungen haben uns wegen Getreide oder ähnlichem Unsinn Richtung Andorhal geführt. Was kümmern mich schon die Märkte in Andorhal? Ich hasse es in der Armee zu sein.\n\nSeid versichert, werte Tante, dass ich zurückkehre, um mein Erbe einzufordern, selbst wenn ich tödlichst verwundet sein sollte, wird mich meine endlose Verachtung für Euch am Leben erhalten.\n\nVargus" } } },
    ["A Dusty Unsent Letter"] = { { ids = { "i889" }, first = "tothehonorableheadmaster", pages = { "An den ehrenwerten Direktor Crillian\n\nIch schreibe Euch, meinem ehemaligen Meister, um Euch wissen zu lassen, wie es Eurem früheren Lehrling ergangen ist. Ich habe Euren Rat befolgt und Wissen und Weisheit durch Reisen außerhalb unserer geliebten Heimat Stormwind vergrößert. Meine Reise hat mich an viele Orte geführt, doch ich beschloss, meine Zelte hier in der schönen Stadt Moonbrook aufzuschlagen. Die umliegenden Felder von Westfall sehen so kurz vor der Erntezeit wunderschön aus.", "Schon wenige Tage nach meinem Besuch avancierte ich zum Lehrer der Kinder von den umliegenden Gehöften. Es lief sogar so gut, dass der Bürgermeister mir die Leitung einer Schule übertragen hat, und nun ist der Bau einer ganz neuen Schule im Gange! Vom Silberwald nach Stormwind und nun Moonbrook - wer hätte geglaubt, dass ich je so viel von Azeroth zu sehen bekommen würde!\n\nBeste Grüße\n\nStalvan Mistmantle" } } },
    ["A Faded Journal Page"] = { { ids = { "i921" }, first = "moststrangeanduncontroll", pages = { "...merkwürdiges und überwältigendes Gefühl. Niemals zuvor habe ich so gefühlt wie heute. Ich half Giles bei seiner Geschichtsstunde, während sich Tilloa im Garten um die Blumen kümmerte. Nach einigen Minuten kam sie herein und drückte mir sanft eine scharlachrote Begonie in die Hand. Das Lächeln, das dabei um ihre Lippen spielte, ließ mein Herz in meiner Brust erbeben..." } } },
    ["A Letter to Grelin Whitebeard"] = { { ids = { "i2188" }, first = "grelinmytimeisshortandma", pages = { "Grelin,\n\nmeine Zeit ist knapp bemessen und ich hoffe, Eure Erforschung der Trolle macht sie nicht noch knapper. Ich gestatte Euch daher, nach Gutdünken mit den Trollen zu verfahren. Solltet Ihr eine zufrieden stellende Lösung finden, umso besser.\n\nMagni Bronzebeard" } } },
    ["A Mysterious Message"] = { { ids = { "i1381" }, first = "blacknailstheseaawaitsus", pages = { "Schwarznagel -\n\nDas Meer ruft. Wir brauchen von Euch Nachschub aus dem Norden. Schickt uns alles, was Ihr entbehren könnt: jeden Spaten, jeden Wassereimer. Wir brauchen Metall. Wir warten noch auf eine längst überfällige Lieferung von BB. Ich zähle auf Euch, Schwarznagel. Schickt die Sachen diesmal direkt zur \"Scheune\". Wir haben keine Zeit zu verlieren.\n\n- Van Cleef\"" } } },
    ["A Ragged Page"] = { { ids = { "i22946" }, first = "samlaaswefollowourlordar", pages = { "Samla,\n\nJe weiter wir Lord Arthas nach Norden folgen, umso schwerer wird mein Herz. Während er einst im Licht erstrahlte, so kann ich heute einen Schatten spüren, der auf dem Geist des jungen Paladins lastet. Sein Eifer wird von dunklen Gedanken umhüllt, etwas Alptraumhaftem in seiner Seele, das ich nicht auszumachen vermag...\n\nWir werden bald in den eisigen Weiten Halt machen. Auch wenn viele der Männer krank von der Kälte und den Kämpfen gegen verseuchte Bestien werden, macht uns Arthas glauben, dass das, was er in dem Eis sucht, eine Wende in der Schlacht herbeiführen wird. Seine Worte spenden mir jedoch keine Zuversicht... das makabere Lächeln, dass seine Lippen umspielt, hat mich weit mehr als irgendein Eissturm erschaudern lassen.\n\nBete für uns, Samla... und bete für die Welt,\n\nTorgal" } } },
    ["A Short Note"] = { { ids = { "i9329" }, first = "curgleihavebeeneagerlyaw", pages = { "Curgle,\n\nich warte schon voller Ungeduld auf Eure neueste Erfindung. Ich kann es kaum erwarten, sie zu benutzen, um damit meine Studien zu dokumentieren.\n\nBitte vertraut sie meinem Boten an.\n\nMit herzlichen Grüßen,\n\nDaryn Lightwind" } } },
    ["A Smudged Document"] = { { ids = { "i22948" }, first = "dearpamelatomorrowwemake", pages = { "Liebste Pamela,\n\nmorgen werden wir uns in Andorhal stellen und ich befürchte, dass dies hier mein letzter Brief an dich sein wird, mein Herz. Die Untoten lassen sich einfach nicht entkräften, im Gegensatz zu uns Menschen, fürchte ich. Wir können ihnen nicht standhalten. Dennoch, sorge dich bitte nicht - auch wenn wir dahinscheiden müssen, so verliert unsere Hoffnung doch nicht an Stärke. Das Licht wird siegen!\n\nWisse außerdem, meine Liebe, dass, während diese dunklen Schrecken unsere verbliebene Gegenwehr stürmen und über uns herfallen, meine letzten Gedanken nicht dem Tod gelten werden. Ich werde mir vorstellen, in deinen Armen zu liegen und somit meinen Frieden finden.\n\nChristoph" } } },
    ["A Torn Journal Page"] = { { ids = { "i916" }, first = "gilestheboyseemsabitramb", pages = { "... Giles, der Junge, scheint ziemlich wild zu sein und stellt eine echte Herausforderung für einen Lehrer dar. Tilloa hingegen, die ältere Tochter, scheint mir außerordentlich klug. Auch ihre atemberaubende Schönheit ist mir indes nicht verborgen geblieben. Sie steht nun an der Schwelle zur Weiblichkeit. Es steht zu vermuten, dass der Lord im kommenden Jahr ihre Heirat arrangiert hat. Aber ich schweife ab. Diese Woche werde ich die Familie zu ihrem Sommersitz in der Nähe des Holzfällerlagers des Osttals in Elwynn, nahe des Rotkammgebirges, begleiten. Dort kann ich hoffentlich mehr schreiben." } } },
    ["A Torn Letter"] = { { ids = { "i22932" }, first = "reubeniwritethisletterkn", pages = { "Reuben,\n\nIch schreibe dir diesen Brief in dem Wissen, dass du ihn vermutlich nie erhalten wirst. Die Untoten stehen vor den Toren Hearthglens und werfen ununterbrochen ihre Truppen gegen uns. Wir haben den Auftrag erhalten, die Bevölkerung zu schützen, bis Verstärkung eintrifft.\n\nWährend des letzten Angriffs habe ich mir ein Bein gebrochen, und jetzt liege ich hier herum, das Schwert an meiner Seite, falls einige Angreifer den Verteidigungsring durchbrechen. Es gibt keinen ruhigen Moment, nur das Geschrei der Kämpfenden und Sterbenden. Die Luft ist von Furcht erfüllt.\n\nPrinz Arthas ist bei uns, er kämpft gemeinsam mit unseren Truppen an der Front. Wäre er nicht gewesen, wir wären alle längst tot. Die Liebe für sein Volk und sein Land sind ansteckend.\n\nDie Kämpfe werden stärker, gebrochenes Bein hin oder her, ich kann hier nicht länger nur herumsitzen. Jede Klinge wird gebraucht. Ich hoffe, dass dich diese Worte in besseren Zeiten erreichen werden.\n\nDein Freund,\nLeagrem" } } },
    ["A Treatise on Military Ranks"] = { { ids = { "o179706", "i18664" }, first = "atreatiseonmilitaryranks", pages = { "ABHANDLUNG MILITÄRISCHER RÄNGE\n\nEs folgen\n\ndie militärischen Ränge\n\nder Allianz,\n\ngefolgt von\n\ninformationen die\n\nden Völkern\n\nder Horde bekannt sind. Alle\n\nAngaben sind in zwei\n\nAbschnitte unterteilt, Offiziere und Soldaten. Dabei werden ihre Ränge jeweils in absteigender Reihenfolge aufgelistet, vom höchsten bis zum niedrigsten Rang. Lang lebe die Allianz!", "OFFIZIERSRÄNGE DER ALLIANZ\n\nTeil 1\n\nGroßmarschall\n\nFeldmarschall\n\nMarschall\n\nRittmeister\n\nFeldkommandant", "OFFIZIERSRÄNGE DER ALLIANZ\n\nTeil 2\n\nRitter der Allianz\n\nKürassier\n\nHauptmann\n\nLeutnant", "SOLDATENRÄNGE DER ALLIANZ\n\nFähnrich\n\nFeldwebel\n\nLandsknecht\n\nFußknecht\n\nGefreiter", "OFFIZIERSRÄNGE DER HORDE\n\nTeil 1\n\nOberster Kriegsfürst\n\nKriegsfürst\n\nKriegsherr\n\nSturmreiter\n\nFeldherr", "OFFIZIERSRÄNGE DER HORDE\n\nTeil 2\n\nKlinge der Horde\n\nZornbringer\n\nBlutgardist\n\nSteingardist", "SOLDATENRÄNGE DER HORDE\n\nRottenmeister\n\nSchlachtrufer\n\nWaffenträger\n\nGrunzer\n\nSpäher" } } },
    ["Acolyte's Note"] = { { ids = { "i205184" }, first = "gakin", pages = { "<Der Text auf der Seite ist beinahe vollständig von Blut überdeckt, aber Ihr erkennt einen Namen.>\n\nGakin" } }, { ids = { "i208224" }, first = "carendin", pages = { "<Der Text auf der Seite ist beinahe vollständig von Blut überdeckt, aber Ihr erkennt einen Namen.>\n\nCarendin" } } },
    ["Admiral Barean Westwind"] = { { ids = { "o175772" }, first = "admiralbareanwestwindgra", pages = { "Admiral Barean Westwind\nGroßadmiral der Scharlachroten Flotte\nBürger von Kul'Tiras\nVor der gefrorenen Küste von Northrend verschollen" } } },
    ["Admiral Proudmoore's Orders"] = { { ids = { "i4883" }, first = "officialordersforthekult", pages = { "Offizielle Befehle für die Flotte von Kul Tiras\n\nIch, Admiral Proudmoore, führe die erste Landung an der Küste von Kalimdor an.\n\nLieutenant Benedict führt in meiner Abwesenheit das Kommando. Sämtliche militärischen Angelegenheiten hier vor Ort in Kul Tiras werden von ihm geregelt. Sollte ich binnen der nächsten zwölf Monate nichts aus Burg Tiragarde hören lassen, führt Leutnant Benedict die zweite Welle zur Eroberung der Stellung an.", "In der Zwischenzeit schicke ich Lieutenant Alverold auf eine Erkundungsmission rund um den Kontinent Kalimdor. Nach Abschluss der Mission sollen sich seine Truppen wieder den unseren bei Burg Tiragarde anschließen.\n\nEs ist allerdings davon auszugehen, dass Lieutenant Alverolds Mission einige Zeit dauern wird. Das neue Land macht einen ebenso weiten wie gefährlichen Eindruck. Sollte Benedict oder mir etwas zustoßen, werden Alverolds Truppen die Burg zurückerobern.\n\nWir werden Welle auf Welle schicken, bis die Festung unser ist!\n\n- Admiral Proudmoore" } } },
    ["Advisor Emerson's Instructions"] = { { ids = { "i285356" }, first = "greetingsasaguestoftheal", pages = { "Seid gegrüßt.\n\nAls Gast der Allianz dürft Ihr Euch innerhalb der Lande der Allianz frei bewegen.\n\nDieses Dokument soll Euch als Wegweiser dienen, um die anderen Mitgliedsstädte unseres Bündnisses zu erreichen.", "Euer erster Halt sollte Ironforge sein, das Ihr mithilfe des Wunderwerks der Technik namens Tiefenbahn erreichen könnt.\n\nDen Zugang zur Bahn findet Ihr im Zwergendistrikt hier in Stormwind, südwestlich der Festung. Die Bahn wird Euch sicher ins Herz von Ironforge bringen.\n\nNach Eurer Ankunft könnt Ihr die Stadt erkunden und Hochtüftler Mekkatorque und König Magni Bronzebeard in Tüftlerstadt beziehungsweise in der Großen Schmiede aufsuchen. Stellt Euch als $gAgent:Agentin; der Himmelsgeborenen vor, dann werdet Ihr ihre Gastfreundschaft erfahren.", "The city of Darnassus can be found across the sea, off the coast of northern Kalimdor. The city itself rests at the top of the great tree, Teldrassil.\n\nThe safest route for you currently is via the harbor on the west side of Stormwind. Take the ship departing from the southernmost dock to the port of Auberdine.\n\nUpon arriving, proceed to the north side of the Auberdine docks and take the ship there to Ru'theran Village. This village contains a magical transporter that will take you into the city itself.\n\nExplore Darnassus and seek out Tyrande Whisperwind, the High Priestess of Elune.", "After you've become acquainted with the other leaders of the alliance, Lord Fordragon has requested that you report back to him here in the keep.\n\nI wish you good fortune in your journeys, Skyborne." } } },
    ["Advisor Nazgrel's Instructions"] = { { ids = { "i285357" }, first = "elfasaguestofthehordethe", pages = { "Elf!\n\nAls Gast der Horde hat der Kriegshäuptling Euch das Recht erteilt, Euch frei im Gebiet der Horde zu bewegen.\n\nNutzt diesen Wegweiser, um Euch in unseren Landen zurechtzufinden.", "Direkt in dieser Kammer findet Ihr Vol'jin vom Stamm der Darkspear-Trolle.\n\nDie Darkspear-Trolle sind treue Freunde der Orcs. Unser Bund wurde in der Hitze des Gefechts während unserer Flucht aus den Menschenlanden auf dem Kontinent im Osten mit Blut besiegelt.\n\nWenn Ihr ihm Respekt zollt, so wird er das erwidern. Wenn Ihr ihm keinen Respekt erweist, dann... tja, probiert es lieber nicht.", "Danach würde ich Euch raten, zurück nach Mulgore zu reisen und Cairne Bloodhoof in Thunder Bluff aufzusuchen.\n\nCairne ist der Häuptling des Bloodhoofstammes der Tauren und es ist seiner Gnade zu verdanken, dass Eure Leute und der Irdene Ring sich in Mulgore niederlassen dürfen.\n\nIhr kennt den Weg nach Thunder Bluff wahrscheinlich schon. Besucht den Flugmeister im Zentrum von Orgrimmar und reitet mit einem Flügeldrachen nach Thunder Bluff. Cairne findet Ihr dann auf dem zentralen Plateau, östlich des großen Totems, das in der Stadt als Wyvernhorst dient.", "Unsere Verbündeten, die Verlassenern, haben sich im Land namens Tirisfal auf dem östlichen Kontinent niedergelassen. Tief unter den Ruinen einer Stadt, die einst Lordaeron hieß, werdet Ihr Undercity finden.\n\nUm Tirisfal zu erreichen, müsst Ihr die Stadt durch das große südliche Tor verlassen und dann Richtung Osten zum Zeppelinturm gehen.\n\nSteigt in den Zeppelin, der an der Südseite des Turms vertäut ist. Nachdem Ihr das Große Meer überquert habt, kommt Ihr in Brill an. Geht von dort nach Norden bis zu den Ruinen von Lordaeron.\n\nSucht den Aufzug und fahrt mit ihm nach unten in die Tiefen von Undercity. Die Dunkle Fürstin findet Ihr dann im Königsviertel.\n\nAber seid gewarnt: Die Hauptstadt der Verlassenen kann auf manche... beunruhigend wirken." } } },
    ["Aegwynn and the Dragon Hunt"] = { { ids = { "o175738" }, first = "asthepoliticsandrivalrie", pages = { "Während politische Beziehungen und Rivalitäten unter den sieben Menschennationen wuchsen und schwanden, ließ die Reihe der Wächter in ihren Anstrengungen zum Schutz gegen das Chaos niemals nach. Im Lauf der Jahre gab es viele dieser Wächter, doch nur einer erhielt jeweils die Macht von Tirisfal. Eine der letzten Wächterinnen jener Zeit tat sich als besonders mächtige Kriegerin gegen die Schatten hervor.", "Aegwynn, ein ehrgeiziges Menschenmädchen, errang die Approbation des Ordens und erhielt den Mantel der Wächterschaft. Aegwynn hetzte Dämonen, wo immer sie ihnen begegnete, und löschte sie aus, stellte aber oft die Autorität des von Männern dominierten Rates von Tirisfal in Frage.", "Sie glaubte, dass die alten Elfen und älteren Menschen, die den Rat bildeten, zu sehr in ihren Denkweisen erstarrt und nicht weitsichtig genug wären, den Konflikt mit dem Chaos endgültig zu beenden. Sie war der endlosen Diskussionen und Debatten überdrüssig und wollte ihren Herren und Mitstreiter mit jeder Faser ihres Körpers von ihrer eigenen Tüchtigkeit überzeugen, daher schätzte sie in entscheidenden Situationen Tapferkeit manchmal höher ein als Weisheit.", "Je besser sie die kosmische Macht von Tirisfal meisterte, desto deutlicher wurde sich Aegwynn einer Anzahl mächtiger Dämonen bewusst, die den eisigen Kontinent Northrend heimsuchten. Aegwynn zog in den fernen Norden und verfolgte die Dämonen bis in die Berge. Dort fand sie heraus, dass die Dämonen einen der letzten noch existierenden Drachenschwärme jagten und den alten Kreaturen die ihnen innewohnende Magie aussaugten.", "Die mächtigen Großdrachen, die vor den expansionistischen Gesellschaften der Sterblichen geflohen waren, übertrafen die dunkle Magie der Legion nicht an Stärke. Aegwynn griff die Dämonen an und machte ihnen mit Hilfe der edlen Großdrachen den Garaus. Doch als der letzte Dämon von der Welt verbannt wurde, brach im Norden ein gewaltiger Sturm aus.", "Eine riesenhafte finstere Fratze erschien am Himmel über Northrend. Sargeras, der Dämonenkönig und Lord der Brennenden Legion, erschien vor Aegwynn und loderte vor höllischer Energie. Er ließ die junge Wächterin wissen, dass die Zeit von Tirisfal zur Neige ginge und die ganze Welt sich bald der Macht der Legion beugen müsse.", "Die stolze Aegwynn fühlte sich dem drohenden Gott gewachsen und entfesselte ihre Macht gegen Sargeras' Avatar. Es fiel Aegwynn auffällig leicht, den Dämonenlord mit ihren Kräften anzugreifen und seine materielle Hülle zu töten. Da Aegwynn befürchtete, Sargeras' Geist könnte noch verweilen, schloss sie die zerschundene Hülle seines Körpers in einer der alten Hallen von Kalimdor ein, die nach der Zerstörung des Brunnens der Ewigkeit auf den Meeresgrund gesunken war.", "Aegwynn sollte nie erfahren, dass sie genau nach Sargeras' Plänen gehandelt hatte. Unwissentlich hatte sie das Schicksal der Welt der Sterblichen besiegelt, denn als sein Leib starb, hatte Sargeras seinen Geist in Aegwynns geschwächten Körper transferiert. Sargeras hauste viele Jahre in den dunkelsten Winkeln ihrer Seele, ohne dass die junge Wächterin auch nur die geringste Ahnung davon hatte." } } },
    ["Aftermath of the Second War"] = { { ids = { "o21581" }, first = "thedevastatingsecondwara", pages = { "Nach dem verheerenden Zweiten Krieg gegen die Orc-Horde hatten Schock und Demoralisierung die Allianz von Lordaeron fest im Griff. Die blutrünstigen Orcs hatten sich unter ihrem mächtigen Kriegshäuptling Orgrim Doomhammer nicht nur durch die Zwergenländer von Khaz Modan gekämpft und dabei eine Schneise der Verwüstung hinterlassen, sondern obendrein viele der wichtigsten Provinzen von Lordaeron völlig zerstört. Es gelang den grausam wütenden Orcs sogar, das\nentlegene Elfenkönigreich Quel'Thalas zu verwüsten, bevor ihrem Rasen endlich Einhalt geboten werden konnte.", "Die Armeen der Allianz unter Führung von Sire Anduin Lothar, Uther Lightbringer und Admiral Daelin Proudmoore drängten die Orcs nach Süden in das verwüstete Land Azeroth - das erste Königreich, das dem gnadenlosen Ansturm der Orcs zum Opfer fiel.\n\n Den Streitkräften der Allianz gelang es unter Sire Lothar, Doomhammers Klans aus Lordaeron zu vertreiben und in das von den Orcs beherrschte Land Azeroth zurückzudrängen. Lothars Streitkräfte umzingelten die Blackrockspitze, die vulkanische Zitadelle der Orcs, und belagerten die Verteidiger.", "In einem letzten Aufbäumen befahlen Doomhammer und seine Offiziere einen tollkühnen Ausbruch aus der Zitadelle. Mitten auf der brennenden Steppe entflammte dann die Schlacht, als sie auf Lothars Paladine trafen. Doomhammer und Lothar lieferten sich einen titanischen Zweikampf, nach dem die beiden mächtigen Krieger erschöpft und verwundet darniedersanken. Mit knapper Not gelang es Doomhammer, Lothar zu besiegen, doch der Tod des großen Helden hatte nicht die Wirkung, die sich der Kriegshäuptling erhofft hatte.", "Turalyon, Lothars engster Vertrauter unter den Offizieren, hob Lothars blutbefleckten Schild auf und scharte seine von Trauer geschüttelten Brüder zu einem erbitterten Gegenangriff um sich. Unter den zerfetzten Standarten von Lordaeron und Azeroth schlugen Turalyons Truppen das Gros von Doomhammers verbliebener Streitmacht in einer ruhmreichen, aber schrecklichen Schlacht.", "Den verwundeten, versprengten Überlebenden der Orcs blieb nichts anderes übrig, als zur letzten Bastion der Orc-Macht zu fliehen - dem Dunklen Portal.\n\nTuralyon und seine Krieger jagten die verbliebenen Orcs durch die verpesteten Sümpfe des Elends in die verwüsteten Lande, wo das Dunkle Portal stand. Und dort, am Fuße des kolossalen Portals, trugen die dezimierte Horde und die unerbittliche Allianz die letzte und blutigste Schlacht des Zweiten Krieges aus.", "Die zahlenmäßig unterlegenen und vom Fluch ihres Kampfrauschs geblendeten Orcs fielen zwangsläufig der Wut der Allianz zum Opfer. Doomhammer wurde gefangen genommen und nach Lordaeron gebracht, derweil man seine versprengten Klans zusammentrieb und nach Norden jagte - zurück nach Lordaeron." } } },
    ["Alexston's Reply"] = { { ids = { "i279048" }, first = "iknowhowthisletterwillfi", pages = { "Ich weiß, in welchem Zustand Ihr diesen Brief erhalten werdet und es tut mir wirklich leid, Ältester.\n\nIhr könnt sicher sein, dass ich alle fähigen Abenteurer, die mir begegnen, in Eure schöne Siedlung schicken werde. Ich hoffe, ihre Tatkraft wird als Ausgleich dafür dienen, dass ich Euch derzeit keine andere Unterstützung senden kann.\n\nUnsere Länder werden von einer Vielzahl von Feinden bedroht. Ich bin sicher, Ihr kennt die Lage selbst nur allzu gut. Unsere Ressourcen wurden durch die ständige Bedrohung stark erschöpft.\n\nSollte sich daran etwas ändern, würde ich Euch mit Freuden helfen, aber selbst dann werden viele Projekte nahe der Heimat Priorität haben.\n\nHaltet durch! Wir sitzen alle im gleichen Boot.\n\n- Baros Alexston\nStadtarchitekt, Stormwind" } } },
    ["Alliance Military Ranks"] = { { ids = { "o179735" }, first = "alliancemilitaryranksoff", pages = { "MILITÄRISCHE RÄNGE DER ALLIANZ\n\nOFFIZIERE\n\nGroßmarschall\n\nFeldmarschall\n\nMarschall\n\nRittmeister\n\nFeldkommandant\n\nRitter der Allianz\n\nKürassier\n\nHauptmann\n\nLeutnant\n\nSOLDATEN\n\nFähnrich\n\nFeldwebel\n\nLandsknecht\n\nFußknecht\n\nGefreiter" } } },
    ["Altar of Zanza"] = { { ids = { "o180367" }, first = "wecalluponyouzanzaofzuld", pages = { "Erbarme dich Unser, Zanza von Zuldazar.\n\nSegne all jene, die um Eure Hilfe flehen, Gott Zanza. Segne die, die sich mit den Zandalarianern verbünden.\n\nHilf uns in Zeiten der Not, gib uns die Kraft unsere Feinde niederzuschlagen. Gib uns die Macht noch einmal den Blutgott zu besiegen." } } },
    ["An Exotic Cookbook"] = { { ids = { "i5428" }, first = "getoneoreightmanhitmanha", pages = { "1. Einen oder acht Menschen fangen\n2. Auf Menschen draufhauen\n3. Noch mehr draufhauen\n4. Menschen ins Feuer halten\n5. Menschen essen" } } },
    ["An Undelivered Letter"] = { { ids = { "i910" }, first = "dearnoblesirwordofyourne", pages = { "Edler Sire,\n\nmir ist zu Ohren gekommen, dass Ihr einen Hauslehrer für Eure Kinder sucht. Ich habe mich vorübergehend in Goldhain im Gasthaus Zur Höhle des Löwen einquartiert. Ob der misslichen Lage in dem Gebiet war ich gezwungen, meine Stellung als Direktor der Schule in Moonbrook aufzugeben. Daher möchte ich mich bei Euch als Lehrer für Eure Sprösslinge bewerben. Ihr könnt Euch, falls nötig, bei Direktor Crillian von der Akademie über meine Fähigkeiten erkundigen.", "Ich werde mich bemühen, Euch persönlich zu treffen, sobald die Winterregenfälle aufgehört haben und die Straßen wieder passierbar sind.\n\nBis dahin verbleibe ich\n\nEuer Stalvan Mistmantle aus dem Silberwald" } } },
    ["Ancient Inscription"] = { { ids = { "o19025" }, first = "theshrineofmelthandrisma", pages = { "Der Schrein von Mel'Thandris\n\n\"Möge das Licht von Elune auf ewig dieses Tal bescheinen und beleuchten die Wege des Waldes, wie es dies schon seit Anbeginn der Zeiten getan hat.\"" } } },
    ["Ancient Tablet"] = { { ids = { "i9242" }, first = "themalletofzulfarraktocr", pages = { "Der Schlaghammer von Zul'Farrak\n\nUm den Schlaghammer von Zul'Farrak herzustellen, muss man zuerst zum Altar von Zul reisen und einem Trollbewahrer den hochheiligen Schlaghammer abknöpfen.\n\nDann muss man den hochheiligen Schlaghammer zum Altar auf dem höchsten Punkt der Trollstadt Jintha'Alor bringen.\n\nBenutzt man den hochheiligen Schlaghammer an dem Altar, so erfüllt man ihn mit Macht und verwandelt ihn in den Schlaghammer von Zul'Farrak." } } },
    ["Annals of Darrowshire"] = { { ids = { "i12900" }, first = "theannalsofdarrowshireda", pages = { "Die Annalen von Darrowshire\n\nDarrowshire, benannt nach dem Darrowmeresee im Westen, ist ein Dorf, das sich in das südliche Vorgebirge Lordaerons schmiegt. Bekannt für seine bescheidenden, aber hart arbeitenden Bewohner, führte Darrowshire ein Schattendasein in der Geschichte Lordaerons, bis der Zweite Krieg ausbrach.\n\nIn diesem Krieg wurden Helden geboren. Und viele Helden ließen ihr Leben.", "Die Schlacht um Darrowshire\n\nDie Schlacht um Darrowshire ereignete sich in der Mitte des Zweiten Krieges, als Streitkräfte der Geißel durch Lordaeron tobten. Darrowshire wurde von der Hauptstreitmacht der Allianz abgeschnitten. Doch eine Kompanie Soldaten, ein Kontingent Paladine der Silberhand und eine standhafte Gruppe hiesiger Milizen unter ihrem Anführer Captain Joseph Redpath hielt in der Stadt stand.", "Die ersten Angriffe der Geißel auf Darrowshire waren eher harmlos. Kleine Gruppen plündernder Skelette und Kadaver durchstreiften die Außenbezirke des Dorfes und wurden abgewehrt.\n\nDie Geißel zeigte sich jedoch nur wenig beeindruckt von der Hartnäckigkeit der Verteidiger und zahlte mit gleicher Münze zurück. Schon bald nach der ersten Welle von Angriffen folgte die zweite. Ghulchampions, Gefolgsleute des Ghullords Horgus, strömten mit wildem Geschrei von den Bergen herab und überrannten die belagerten Verteidiger Darrowshires.", "Die Verteidiger waren geschwächt, wurden jedoch durch Paladine abgelöst, Jünger der Silberhand. Ihr Anführer David Crokford stammte aus Darrowshire. Er brachte seine Anhänger ins Dorf, als er von dem bevorstehenden Angriff erfuhr, und zusammen mit den Verteidigern gelang es ihnen, die Diener von Horgus aufzuhalten.\n\nAls Horgus sich höchstpersönlich in die Schlacht stürzte, traf er auf Davil. Viele Minuten lang kämpften sie, und Davil ging am Ende siegreich hervor, erlitt jedoch eine tödliche Verletzung und starb kurz, nachdem er den Ghullord besiegt hatte.", "Die Schlacht ging weiter und Captain Redpath führte seine Milizen mutig an. Der Kampf wäre vielleicht sogar gewonnen worden, wäre der Captain nicht durch den Todesritter Marduk der Schwarze verderbt worden.\n\nMitten im Getümmel ritt Marduk auf Redpath zu, entriss ihm durch schwarze Magie seinen Geist und verwandelte ihn in einen bösen Schatten des tapferen Captains.", "Durch den verderbten Captain Redpath breitete sich danach dessen bösartige Besudelung unter den Verteidigern Darrowshires aus, die prompt ihre Verbündeten verrieten und ermordeten. Dann wandten sie sich der Stadt Darrowshire zu und töteten alle, die sich in ihren Häusern versteckten.\n\nDie verbliebene Armee der Geißel sowie der verderbte Geist Captain Redpaths verließen danach das verheerte Dorf Darrowshire und drangen nach Lordaeron vor, um im Zweiten Krieg noch mehr Schmerz und Tod zu verbreiten." } } },
    ["Another Clue to Sander's Treasure"] = { { ids = { "i1361" }, first = "nowfromthisherebarrelfac", pages = { "Also, von dem Fass dort müsst Ihr Euch nach Norden halten tun. Un' dann geht Ihr immer der Nase nach schnurstracks geradeaus, bis Ihr den leeren Henkelkrug sehen tut, der da irgendwo bei so 'ner einzeln stehenden Windmühle oben auf dem Steilhang über dem Meer liegt Wenn Ihr Euch bei dem Henkelkrug umguckt, dann findet Ihr vielleicht sogar, was Ihr sucht." } } },
    ["Arathor and the Troll Wars"] = { { ids = { "o175734" }, first = "asthehighelvesfoughtfort", pages = { "Während die Hochelfen unter dem brutalen Ansturm der Trolle ums Überleben kämpften, bemühten sich die versprengten nomadischen Menschen von Lordaeron, ihre eigenen Stammesländer zu konsolidieren. Die Stämme der frühen Menschen überfielen gegenseitig ihre Siedlungen und gaben nichts auf Ehre oder Zusammenhalt des Volkes.", "Doch ein Stamm, Arathi genannt, erkannte, dass man die zunehmende Gefahr durch die Trolle nicht mehr ignorieren konnte. Die Arathi wollten alle Stämme unter ihrer Herrschaft vereinen, damit sie sich den Kriegsmeuten der Trolle mit einer Einheitsfront entgegenstellen konnten.", "Im Lauf von sechs Jahren gelang es den Arathi, die rivalisierenden Stämme zu überlisten und zu unterwerfen. Nach jedem Sieg boten die Arathi dem eroberten Volk Frieden und Gleichheit an. Auf diese Weise sicherten sie sich die Loyalität der Besiegten. Schließlich setzten sich die Arathi aus vielen verschiedenen Stämmen zusammen und verfügten über ein riesiges Heer.", "Da die Kriegsherren der Arathi der festen Überzeugung waren, dass sie gegen die Kriegsmeuten der Trolle und, falls erforderlich, sogar gegen die einsiedlerischen Elfen bestehen konnten, beschlossen sie, in der südlichen Region von Lordaeron eine mächtige befestigte Stadt zu errichten. Dieser Stadtstaat namens Strom wurde zur Hauptstadt von Arathor, der Nation der Arathi. Je mehr Arathors Wohlstand wuchs, desto mehr Menschen reisten über den riesigen Kontinent und suchten Schutz und Sicherheit in Strom.", "Die unter einem Banner vereinigten Stämme der Menschen begründeten eine starke, optimistische Kultur. Thoradin, der König von Arathor, wusste wohl, dass die geheimnisvollen Elfen in den Nordlanden unablässig von den Trollen belagert wurden, wollte sein Volk aber keiner Gefahr aussetzen, indem er einsiedlerische Fremde verteidigen half. Viele Monate vergingen, bis Gerüchte über eine angebliche Niederlage der Elfen von Norden eintrafen. Aber erst als erschöpfte Botschafter aus Quel'Thalas in Strom eintrafen, wurde Thoradin klar, wie groß die Gefahr, die von den Trollen ausging, wirklich war.", "Die Elfen ließen Thoradin wissen, dass die Armeen der Trolle riesig waren und die Trolle ganz gewiss die Südländer angreifen würden, wenn sie Quel'Thalas erst einmal zerstört hatten. Die verzweifelten Elfen, die dringend militärischer Unterstützung bedurften, willigten hastig ein, bestimmte auserwählte Menschen den Umgang mit der Magie zu lehren, falls diese ihnen gegen die Kriegsmeuten beistanden.", "Thoradin, der jeder Form von Magie misstrauisch gegenüberstand, sagte den Elfen in Ermangelung von Alternativen seine Hilfe zu. Unmittelbar danach trafen Elfenzauberhexer in Arathor ein und unterwiesen eine Gruppe Menschen im Gebrauch der Magie.", "Die Elfen stellten fest, dass die Menschen im Umgang mit der Magie zwar ungeübt waren, aber eine erstaunliche natürliche Affinität dafür besaßen. Einhundert Menschen wurden in die Grundzüge der magischen Geheimnisse der Elfen eingeführt: nicht mehr, als unbedingt erforderlich waren, um gegen die Trolle zu kämpfen. Als die Elfen überzeugt waren, dass ihre menschlichen Schüler im Kampf nützlich sein konnten, verließen sie Strom und reisten mit den mächtigen Armeen von König Thoradin nach Norden.", "Die vereinigten Armeen von Elfen und Menschen stießen am Fuß des Alteracgebirges auf die überlegenen Kriegsmeuten der Trolle. Die Schlacht währte viele Tage, aber die unerschütterlichen Armeen von Arathor blieben unermüdlich und wichen keinen Schritt vor dem Ansturm der Trolle zurück. Den Elfenlords schien die Zeit reif, die Macht ihrer Magie gegen den Feind zu entfesseln.", "Hundert Menschenmagi und eine Vielzahl von Zauberhexern der Elfen riefen die Wut des Himmels herab und ließen Feuer auf die Armee der Trolle regnen. Die Elementarfeuer verhinderten, dass die Trolle ihre Verletzungen heilen konnten, und verbrannten ihre geschundenen Leiber von innen heraus.", "Dann endlich stoben die Armeen der Trolle auseinander und wollten fliehen, doch Thoradins Soldaten hetzten sie und metzelten sie bis auf den letzten Mann nieder. Von dieser Niederlage erholten sich die Trolle nie mehr, ihre Tage als starke Nation waren endgültig gezählt. In der Gewissheit, dass Quel'Thalas sicher war, schworen die Elfen der Nation Arathor und dem Geschlecht des Königs Thoradin ihre Treue. Menschen und Elfen lebten fortan Jahrhunderte lang in friedlicher Verbundenheit." } } },
    ["Archaic Rune"] = { { ids = { "i282400" }, first = "youalreadyfeltthecallofs", pages = { "Ihr habt bereits den Ruf von etwas Größerem als Euch selbst gespürt, und das ist der Ruf der Elemente. Wir Zwerge haben eine starke Verbindung zur Erde, aber mit der richtigen Ausbildung könnt Ihr lernen, mit allen Elementen zu sprechen. Die Elemente können fordernd und anspruchsvoll sein, aber ich werde Euch dabei helfen zu lernen, wie Ihr mit ihnen kommunizieren könnt. Kommt zu mir in Anvilmar und ich werde Euch lehren, wie man den Elementen zuhört und wie Ihr sie dazu bringen könnt, Euch zuzuhören.\n\n- Teo Hammerstorm, Shamanenlehrer" } } },
    ["Archbishop Alonsus Faol"] = { { ids = { "o177199" }, first = "archbishopalonsusfaolben", pages = { "Erzbischof Alonsus Faol\n\nGütiger Schutzherr der Kirche des Lichts.\n\nObwohl Erzbischof Faol mit seinem guten Werk in Stratholme, Lordaeron begann, so war er doch den Leuten von Stormwind ein guter Freund. In den dunklen Tagen nach dem Zweiten Krieg trug er dazu bei, die Bruderschaft von Nordhain zu reformieren und sammelte Gelder, um die Stadt Stormwind wieder aufzubauen.\n\nDiese Kathedrale steht jetzt nicht nur hier als Bastion des Heiligen Lichts, sondern als das dauerhafte Testament an den edlen Geist und die Großzügigkeit eines ganz besonderen Mannes." } } },
    ["Archimonde's Return and the Flight to Kalimdor"] = { { ids = { "o175758" }, first = "oncekelthuzadwaswholeaga", pages = { "Als Kel'Thuzad wieder geheilt war, führte Arthas die Geißel südwärts nach Dalaran. Dort fiel dem Lich das mächtige Zauberbuch von Medivh in die Hände, mit dessen Hilfe er Archimonde zurück in die Welt holte. Von diesem Moment an begann Archimonde höchstselbst die letzte Invasion der Legion. Nicht einmal die Hexer der Kirin Tor konnten verhindern, dass Arthas' Streitkräfte Medivhs Buch stahlen, und so hatte Kel-Thuzad bald alles, was er brauchte, um seinen Zauber auszuführen.", "Nach zehntausend Jahren erschienen der mächtige Dämon Archimonde und sein Wirtskörper erneut auf der Welt Azeroth. Doch Dalaran war nicht ihr letztes Ziel. Auf persönliches Geheiß von Kil'jaeden folgten Archimonde und seine Dämonen der untoten Geißel nach Kalimdor, um den Weltbaum Nordrassil zu vernichten.", "Inmitten dieses Chaos erschien ein einsamer, mysteriöser Prophet auf der Bildfläche und bot den sterblichen Völkern seine Unterstützung an. Dieser Prophet war kein anderer als Medivh, der letzte Wächter, der auf wundersame Weise aus dem Jenseits zurückgekehrt war, um sich von früheren Sünden reinzuwaschen. Medivh erzählte der Horde und der Allianz von den drohenden Gefahren und beschwor sie zur Zusammenarbeit.", "Nach Generationen voller Hass wollten die Orcs und Menschen davon nichts wissen. Medivh musste sich um jedes Volk einzeln kümmern und es mit Prophezeiungen und Tricks über das Meer ins legendäre Land Kalimdor locken. Bald stießen Orcs und Menschen auf die lange verborgene Zivilisation der Kaldorei.", "Unter Führung von Thrall mussten die Orcs auf der Reise durch das Ödland von Kalimdor eine Reihe von Rückschlägen hinnehmen. Sie schlossen zwar Freundschaft mit Cairne Bloodhoof und seinen mächtigen Taurenkriegern, aber viele Orcs erlagen dem dämonischen Kampfrausch, der sie schon seit Jahren verseuchte. Grom Hellscream, Thralls größter Offizier, verriet die Horde sogar, indem er seinen niederen Instinkten gehorchte.", "Als Hellscream und seine loyalen Warsongkrieger durch die Wälder von Ashenvale schlichen, stießen sie auf die alten Nachtelfen-Schildwachen. In der Überzeugung, dass die Orcs zu ihrer kriegerischen Lebensweise zurückgekehrt waren, kam der Halbgott Cenarius herfür, um Hellscream und seine Orcs zu vertreiben. Doch im Banne von übernatürlichem Hass und Wut konnten Hellscream und seine Orcs Cenarius töten und den alten Wald verderben.", "Zu guter Letzt stellte Hellscream seine Ehre wieder her, indem er Thrall half, Mannoroth zu besiegen, jenen Dämonenlord, der die Orcs ursprünglich mit dem Fluch seines Hasses und seiner Wut belegt hatte. Durch Mannoroths Tod wurde der Blutfluch der Orcs schließlich beendet.", "Während Medivh noch die Orcs und Menschen von der Notwendigkeit einer Allianz zu überzeugen versuchte, kämpften die Nachtelfen auf ihre eigene heimliche Weise gegen die Legion. Tyrande Whisperwind, die unsterbliche Hohepriesterin der Nachtelfen-Schildwachen, kämpfte verzweifelt, um zu verhindern, dass die Dämonen und Untoten die Wälder von Ashenvale überrannten. Tyrande wurde klar, dass sie Hilfe brauchte, daher zog sie aus, die Druiden der Nachtelfen aus ihrem tausendjährigen Schlummer zu wecken.", "Tyrande rief ihren einstigen Geliebten Malfurion Stormrage und schaffte es, ihre Verteidigung zu stärken und die Legion zurückzuschlagen. Mit Malfurions Hilfe erhob sich die Natur selbst und wehrte sich gegen die Legion und die verbündete Geißel.", "Auf der Suche nach weiteren Druiden im Großen Schlaf fand Malfurion das alte Gefängnis im Grabhügel, wo er seinen Bruder Illidan angekettet hatte. Überzeugt, dass Illidan ihnen gegen die Legion beistehen würde, befreite Tyrande den Bruder ihres Geliebten. Tatsächlich unterstützte Illidan sie eine Zeit lang, doch dann floh er, um seine eigenen Pläne zu verfolgen.", "Die Nachtelfen wappneten sich und kämpften voll grimmiger Entschlossenheit gegen die Brennende Legion. Die Legion suchte noch immer nach dem Brunnen der Ewigkeit, seit langem Quell der Stärke des Weltbaums und Herz des Königreichs der Nachtelfen. Sollte ihr geplanter Angriff auf den Weltbaum von Erfolg gekrönt sein, würden die Dämonen die Welt buchstäblich in Stücke reißen." } } },
    ["Archmage Khadgar of the Kirin Tor"] = { { ids = { "o25333" }, first = "archmagekhadgarofthekiri", pages = { "Erzmagier Khadgar von den Kirin Tor\n\nEhemaliger Lehrling von Medivh. Oberkommandeur der Expedition der Allianz, die in Draenor, der Heimat der Orcs, einmarschiert ist. Vermutlich gefallen.\n\nNoch nie hat sich jemand so selbstlos ins finstere Herz von Magie und Krieg begeben. Wir wünschen euch alles Gute, kühner Wanderer. Wo immer Ihr auch seid.\n\n- Antonidas - Erzmagier von Dalaran" } } },
    ["Arellas Fireleaf"] = { { ids = { "o175771" }, first = "arellasfireleafhighwizar", pages = { "Arellas Fireleaf\nHochhexer des Scharlachroten Kreuzzugs\nBürger von Quel'Thalas\nIn ewigem Kampf mit dem Totenbeschwörer Diesalven gefangen" } } },
    ["Baelog's Journal"] = { { ids = { "o123463" }, first = "ihavefoundamethodtoenter", pages = { "Ich habe eine Möglichkeit gefunden, in die Kammer von Khaz'mul zu gelangen!\n\nNehmt das Gni'kiv-Medaillon aus meiner Truhe.\n\nBesiegt den Trogg Revelosh in der Kammer vor dem Kartenraum und holt Euch den Schaft von Tsol.\n\nVereinigt das Medaillon und den Schaft zum Stab der Prähistorie.\n\nBenutzt den Stab im Kartenraum und öffnet die Tür zur Kammer von Khaz'mul.\n\nGelingt Euch das, gehört die Kammer Euch!\nBaelog" } } },
    ["Bath'rah's Parchment"] = { { ids = { "i6929" }, first = "belowyouwillfindthatwhic", pages = { "Folgende Dinge brauche ich für meinen Zauber zur Beschwörung des großen Cyclonian. Möge das Glück mit Euch sein.\n\n- Bath'rah der Windbehüter", "Lebenswurz:\n\nMan findet sie in freier Natur oder bei den Moderrankenbestien aus den Marschen von Dustwallow. Ihr braucht die Wurzel, um damit die Lebensessenz von Cyclonian in unsere Welt zu ziehen.", "Bloodscalphauer:\n\nDie Hauer der Bloodscalptrolle im Schlingendorntal sind von seltener Güte. Die Bosheit der Bloodscalps ist in ihren Hauern konzentriert. Indem man diese zu Pulver zerstößt, kann man ihre widerwärtigen Kräfte befreien.", "Essenz der Verbannung:\n\nDiese Essenz erhält man durch Verschmelzung der drei Glücksbringer der verbannten Elementare in den Bergen des Arathihochlands. Sammelt donnernde Glücksbringer, brennende Glücksbringer und schäumende Glücksbringer von den Elementaren und legt je acht davon in meinen Kessel.\n\nAus den Glücksbringern bildet sich dann die Essenz der Verbannung." } } },
    ["Beginnings of the Undead Threat"] = { { ids = { "i5861" }, first = "theundeadsbeginningsupon", pages = { "Die Untoten in Azeroth entstanden nicht erst mit der Verderbnis von Prinz Arthas. Vielmehr begann alles schon lange vorher. Die Ereignisse, die schließlich zum Fall von Lordaeron führen sollten, wurden lange vorher in Gang gesetzt. Es begann mit der Ankunft der orcischen Klans und der Brennenden Legion.", "Die Orcs von Draenor (der Welt, aus der sie ursprünglich stammten) waren edel und hingen dem Schamanismus an. Es waren mächtige Krieger, stark an Körper und Willen. Aus diesem Grunde hatte die Brennende Legion sie ausgesucht. Kil'jaeden, ein Dämon von großer Macht in der Legion, wollte die Orcklans versklaven und als Armee gegen jene Teile der Welt einsetzen, welche die Brennende Legion noch zu erobern hatte.", "Kil'jaeden ging zum Anführer der Klans, einem mächtigen Schamanen mit Namen Ner'zhul. Er versprach Ner'zhul ungeahnte mystische Kräfte, ginge er einen Pakt mit dem Dämon ein und versklave er die Klans an die Brennende Legion. Mit diesem Pakt war nicht nur das Schicksal der Orcs, sondern auch das der Welt für immer besiegelt.", "Mit der Zeit erkannte Ner'zhul, welches Schicksal den Klans in den Händen der Brennenden Legion drohte, und der Orc-Schamane begann, sich Kil'jaeden zu widersetzen. Der Dämon, erzürnt über Ner'zhul, wandte sich Gul'dan, dem Lehrling des Schamanen zu, der leichter zu verderben war als Ner'zhul.", "Gul'dan war es denn auch, der für den Niedergang des Schamanismus in den Klans verantwortlich war. Die Aussicht auf Macht und Kontrolle über die jeweiligen Gegner machte seine Angebote noch verlockender. Mit Kil'jaedens Hilfe begann Gul'dan mit der Manipulation der Klans. Aus den einst so edlen Orcs wurden verderbte, hirnlose Wilde. Aber erst die Einbringung von Dämonenblut in ihre Adern machte die Orcs zu völlig ruchlosen Barbaren.", "Zwar war es Kil'jaeden nach dem Fehlschlag mit Ner'zhul gelungen, Gul'dan zu verderben, aber Kil'jaeden hasste den Schamanen und schwor, den ursprünglichen Pakt einzufordern. Kil'jaeden fing Ner'zhul und begann, den Schamanen mit einer unglaublichen Langsamkeit grausam zu foltern. Ner'zhul flehte um den Tod, doch Kil'jaeden erinnerte Ner'zhul nur daran, dass ihr Bündnis noch Bestand hatte. Kil'jaeden tötete den Körper des Orcs. Den Geist des Schamanen aber hielt Kil'jaeden fest, ehe der seinen Weg in den wirbelnden Nether antreten konnte.", "Kil'jaeden schloss Ner'zhuls Geist in einem Eisblock aus dem wirbelnden Nether ein. Dann verlieh er ihm noch mehr Macht. Der Verlust seines Körpers und die gleichzeitige Aufnahme von so unglaublicher Macht bewirkten schließlich die Verwandlung Ner'zhuls.", "Kil'jaeden schleuderte den Eisblock durch die Dimensionen zurück nach Azeroth, wo er auf dem Kontinent Northrend landete. So kam das Böse in unsere Welt. Ner'zhul gab es nicht mehr. Es gab nur noch einen Thron aus Eis und Hass. Aus dem einst so respektierten Schamanen und Anführer war der unglaublich mächtige Lichkönig geworden.", "Weil aber Kil'jaeden dem Lichkönig nicht vertraute, schickte er seine Schreckenslords aus, damit sie den Geist überwachten und darauf achteten, dass der Lichkönig seine Befehle befolgte. Die vampirischen Gefolgsleute kamen dabei nur zu gern nach Azeroth, angezogen von der zerstörerischen Macht des Lichkönigs und der Aussicht auf die Vernichtung allen Lebens auf einem Planeten.", "Mehr als ein Jahrzehnt verging. In dieser Zeit nutzte der Lichkönig seine große Macht, um die Seelen der Wesen in Northrend unter Kontrolle zu bekommen. Dann wies er sie an, über seinem Frost-Thron eine große Zitadelle zu errichten. Nun, da ganz Northrend unter seiner Herrschaft stand, wusste der Lichkönig, dass es an der Zeit war, mit der Unterwanderung von Lordaeron zu beginnen. Aus seinem eisigen Gefängnis heraus begann der ehemalige Orc-Schamane mit der Suche nach neuen Seelen, die er unter seinen Einfluss bringen konnte. Und er erreichte damit ganze Kontinente.", "Die Beschwörungen des Lichkönigs verhallten nicht ungehört. Insbesondere eine Hand voll mächtiger Personen wurde darauf aufmerksam. Unter ihnen war auch Erzmagier Kel'Thuzad, ein sehr mächtiges Mitglied der Kirin Tor, des herrschenden Gremiums von Dalaran. Sein Streben nach jeder Art von Magie war ein Verstoß gegen die Gesetze der Kirin Tor, die das Erlernen schwarzer Magie untersagten. Also verließ Kel'Thuzad die Kirin Tor, brach mit allen Konventionen und schwor, so viel wie möglich vom Lichkönig zu lernen.", "Die beiden schmiedeten ein Bündnis. Kel'Thuzad bekam Unsterblichkeit und unglaubliche Macht verliehen. Im Gegenzug musste er dem Lichkönig zu Diensten sein. Kel'Thuzads erste Aufgabe bestand darin, seinen Wohlstand und seinen Einfluss in Lordaeron zur Gründung des Kults der Verdammten zu nutzen. Der Kult versprach seinen Mitgliedern Gleichheit und ewiges Leben, wenn sie einen Eid auf Ner'zhul schworen, den Gott des Kultes der Verdammten.", "Dann erschuf Ner'zhul Artefakte, die in der Lage waren, die Seuche unter den Menschen von Lordaeron zu verbreiten. Diese gab er Kel'Thuzad und wies den Hexer an, die Artefakte im ganzen Land zu verteilen. Die Anhänger des Kults mussten die Artefakte um jeden Preis beschützen.", "Einmal dort, begann die Seuche in das Land einzusickern und die unwissenden Bürger zu beeinflussen. Unter Kel'Thuzads Blicken wuchs die Armee des Lichkönigs beständig an und hatte schon bald weite Teile des Landes unter ihre Knute gebracht. Die Armee wurde als \"die Geißel\" bekannt, denn sie diente nur der Ausrottung der Menschheit in Azeroth." } } },
    ["Bel'dugur's Note"] = { { ids = { "i4650" }, first = "thestarofxilyehanogreina", pages = { "Der Stern von Xil'yeh\n\nEin Oger in Alterac, Grelborg der Horter, ist der letzte bekannte Besitzer dieses Edelsteins, von dem gemunkelt wird, dass er seinen Besitzer befähigt, mit anderen Welten zu kommunizieren. Unseren Quellen zufolge streift Grelborg durch die Ruinen von Alterac im Alteracgebirge, wo er im Geröll und Trümmern nach weiteren alten Relikten sucht.", "Die Hand von Dagun\n\nDagun ist ein Wasserwesen, das von den Murlocs in den Marschen von Dustwallow angebetet wird. Sie locken ihn mit einer speziellen Art Seetang, den ihre Schamanen verzaubert haben, an die Oberfläche. Jagt diese Murlocs, holt mir den verzauberten Seetang und legt ihn auf den Altar der Murlocs! Dagun wird kommen, und Ihr werdet ihn erwarten.\n\nIch will diese Hand.", "Das Herz des Vermächtnisses\n\nIn alten Schriften heißt es, wer das Herz des Vermächtnisses besitzt, fürchtet kein Grab. Das ist vielleicht sogar wahr, denn der Besitzer des Herzens, der Troll Mogh, ist unter dem Namen Mogh der Unsterbliche bekannt. Mogh ist ein Hexendoktor vom Skullsplitterstamm. Er lebt im Schlingendorntal in den Ruinen von Zul'Mamwe.", "Bringt mir diese drei Dinge - den Stern, die Hand und das Herz - und eine Kopie von 'Yagyins Zusammenstellung' ist Euer.\n\n- Der Bewahrer" } } },
    ["Belamoore's Research Journal"] = { { ids = { "i3711" }, first = "kegandarkmarleaderofthes", pages = { "Kegan Darkmar, der Anführer jener kleinen Gruppe von Untoten, die auf der Suche nach Schutz vor ihren \"Brüdern\" zu uns kam, ist so gar nicht wie die anderen von seinem Schlag. Seine Haut mag verfaulen und Blut mag schon lange nicht mehr durch seine Adern fließen, aber seine Handlungen sind edel und er scheint sich mehr um das Wohl seiner Begleiter zu sorgen, als um sein eigenes Wohlergehen.\n\nIn der Tat zeichnet er sich durch eine Menschlichkeit aus, die ich, wie ich gestehe, gelegentlich an den Menschen um mich herum vermisse.", "Aber warum erwähne ich das? Nun, ich möchte dem, was ich nun niederschreiben werde, auf diese Weise Glaubwürdigkeit verleihen, denn dies sind die Worte von Kegan. Ich hoffe, dass meine Kollegen, wenn sie dies Tagebuch lesen, verstehen werden, warum ich ihm Glauben geschenkt habe:\n\n\"Überbleibsel der Alten Götter liegen noch immer in den Tiefen der Welt verborgen. Nun wollen sich neue Kräfte diese uralte Macht zu Nutze machen, und wenn sie Erfolg haben, halten sie eine furchtbare Waffe gegen ihre Feinde in Händen.\"", "Mit diesen Worten hat mir Kegan seinen Blutsteinanhänger übergeben, und in seinen Augen lag dabei ein Ausdruck von Angst und vielleicht sogar so etwas wie Ehrfurcht. Und als er die Steine in meine Hand legte, blieben seine Augen darauf ruhen, als gebe er den Anhänger nur widerwillig ab. Ekel überkam mich, aber ich weiß bis heute nicht, ob das an der Berührung durch Kegans totes Fleisch lag oder am Anhänger selbst.\n\nDenn ich fühlte darin eine Kraft. Eine tiefe, verborgene, hungrige Kraft. Eine Kraft, die sich nach Freiheit sehnte.", "Auch wenn meine Kollegen in Dalaran arge Bedenken hatten, die von Kegan und seinen Begleitern mitgebrachten Blutsteine zu untersuchen, so fühlte ich mich durch Kegans Ehrlichkeit doch gezwungen, seinen Blutsteinanhänger zu untersuchen, statt ihn und die vier anderen einzusperren und die Steine zu lassen, wo sie waren.", "Ich hoffte, meinen Kollegen davon überzeugen zu können, dass diese Steine in der Tat magische Kräfte besäßen und dass, auch wenn wir Hexer von Dalaran die Macht der Blutsteine nicht nutzen wollten, wir wenigstens ihre Eigenschaften studieren sollten, da der Feind sie eines Tages gegen uns verwenden könnte.\n\nUnd so begann ich denn.", "Ich begann meine Prüfungen zunächst in der Annahme, dass es sich bei Blutstein tatsächlich um Gestein wie Quarz oder Obsidian handelt. Also machte ich verschiedene Prüfungen zur Gesteinsbestimmung: welche Mineralien der Blutstein enthielt, wie seine Farbe und sein Härtegrad zustande kamen sowie einige andere für Gestein und Erz übliche Eigenschaften. Aber der Blutsteinanhänger reagierte frustrierenderweise auf keine der Prozeduren wie normales Erz.", "Genau genommen reagierte er sogar genau andersherum als erwartet. Fast schien es, als sabotiere der Anhänger meine Experimente absichtlich,\n\nals besäße er einen Verstand und sei lebendig.\n\nVerärgert, aber nicht entmutigt ging ich nun also davon aus, es handele sich um etwas Lebendiges.\n\nVergeblich.", "Meine Experimente konnten die Herkunft des Blutsteins nicht enthüllen. Das einzige Rätsel, das ich lösen konnte, war, dass der Blutstein weder lebendig noch tot war!\n\nAusgerechnet dann gelang mir aber plötzlich der Durchbruch. Für mein jüngstes Experiment benötigte ich ein Becherglas, dessen Rand an einer Stelle etwas abgesplittert war. Das eigentliche Experiment erbrachte wieder kein Ergebnis, aber als ich danach den Arbeitstisch reinigte, schnitt ich mir mit dem Becherglas in den Finger.", "Die Wunde war nicht tief, blutete aber stark. Bevor ich meinen Finger verarzten konnte, war mein Schreibtisch schon voller Blut.\n\nIch wollte es wegwischen, aber da fiel mir etwas höchst Merkwürdiges auf...", "Das Blut, das neben dem Blutsteinanhänger auf den Tisch getropft war, bewegte sich langsam auf das Schmuckstück zu, als würde es davon angezogen. Die Blutstropfen, die mit dem Anhänger in Berührung kamen, schienen zu verschwinden, und das Rot des Steins wurde umso intensiver, je mehr von meinem Blut er in sich aufnahm.", "Als ich das sah, wurde mein Kopf ganz leicht, was vielleicht weniger an meiner Verletzung lag (denn so viel Blut hatte ich ja nicht verloren) als an der Tatsache, dass ich nach all dem Frust endlich eine der Eigenschaften des Blutsteins gefunden hatte. Ich griff nach einem Hocker hinter mir, setzte mich und dachte nach. Gedanken und Fragen rasten so schnell durch meinen Kopf, dass mir ganz schwindelig davon wurde.\n\nTrinkt der Blutstein Blut? Verlangt er nach Blut? Zieht er Blut an?", "Oder besteht Blutstein gar aus Blut? Und wenn ja, wessen Blut? Mein Blut? Menschenblut? Blut von Tieren?\n\nVielleicht ist der Blutstein aber auch aus dem Blut eines unbekannten Dings - eines Dings, das Kegan sowohl fürchtete als auch verehrte, als er mir seinen Anhänger gab.\n\nDiese Frage gilt es zu beantworten. Sie ist der Schlüssel.", "Mein Ehrgeiz wurde angestachelt und ich stürzte mich wieder in meine Experimente. Dieses Mal hielt ich mich nicht lange mit Vermutungen auf, sondern machte jeden mir nur möglichen Test. Freilich war der Aufwand an Zeit und Mühe beträchtlich, aber es erhöhte auch die Wahrscheinlichkeit neuer Entdeckungen.\n\nUnd obwohl mein Labor sehr klein ist und ich niemanden habe, der mir hilft, ist es mir doch gelungen, eine weitere faszinierende Eigenschaft der Blutsteine zu finden...", "Neben Blut sind auch elementare Kräfte in dem Stein konzentriert. Feuer, Wasser, Donnern und Fels sind mit dem Blut vermischt (aber die Frage bleibt: wessen Blut eigentlich?). Und obwohl diese Mixtur äußerlich eher träge erscheint, scheinen doch all diese Kräfte innerlich miteinander zu ringen. Fragen über Fragen taten sich auf angesichts dieses ebenso faszinierenden wie beunruhigenden Materials.", "Aber um diese Frage beantworten zu können, müssen weitere Studien und Experimente an dem Anhänger durchgeführt werden, und ich befürchte, dass es im Internierungslager von Lordamere weder genug Arbeitskräfte noch die erforderliche Ausrüstung dazu gibt. Also übergab ich den Blutsteinanhänger einem Kurier, der ihn nach Dalaran bringen sollte. Ich gab ihm auch genaue Anweisungen für die Experimente mit, auf dass meinen Kollegen die frustrierenden Erfahrungen erspart blieben, die ich gemacht hatte.", "Während ich auf die Ergebnisse dieser Experimente wartete, sprach ich wieder öfter mit Kegan. Ich drängte ihn immer wieder, mir zu sagen, was er über die Blutsteine wusste. Aber nie verriet er mehr als das, was er mir schon gesagt hatte, als er mir den Anhänger gab, wie er überhaupt nicht oft über \"die Verlassenen\" sprach, wie er seinen Klan der Untoten nennt.", "Aber Kegan war ganz erpicht darauf, über andere Themen zu reden, insbesondere seine Zeit in Lordaeron vor dessen Fall.\n\nEr liebt dieses untergegangene Königreich noch immer, obwohl es doch nicht mehr existiert.\n\nMeine wachsende Sympathie für Kegan verlieh mir Geduld, während ich auf die Untersuchungsergebnisse wartete.", "Nach Wochen ohne Nachricht verlor ich die Geduld, forschte nach und erfuhr, dass der Blutstein nie in Dalaran bei meinen Kollegen angekommen war. Mein Kurier war verschollen und der Blutsteinanhänger mit ihm!\n\nDas sind schlechte Neuigkeiten, denn obschon Kegan und seine Begleiter noch einige andere Blutsteinexemplare haben mit denen wir experimentieren können, befürchte ich, der Anhänger könnte in die falschen Hände geraten.", "Ich habe einen weiteren Boten nach Dalaran geschickt und gehört, dass sie dort immer noch nach dem Anhänger suchen, und zwar inzwischen auch in den Ruinen außerhalb unserer schützenden Sphäre.\n\nIch kann nur hoffen, dass es nicht zu spät ist." } } },
    ["Benedict's Orders"] = { { ids = { "i270151" }, first = "corporaladamoreatfirstli", pages = { "Corporal Adamore!\n\nIm Morgengrauen werdet Ihr eine Streitkraft aus nicht mehr als 10 Marinesoldaten zusammenstellen und Euch bei einem Kopfgeldjäger namens Terry Longdrink melden. Gemeinsam mit ihm werdet Ihr Euch auf die Spur eines gefährlichen Deserteurs setzen, der voraussichtlich bewaffnet und Euch gegenüber feindselig eingestellt sind.\n\nDieser Kopfgeldjäger war vor dessen Tod ein vertrauenswürdiger Verbündeter des Lord Admirals. Ich erwarte also, dass Ihr Longdrink denselben Respekt wie jedem höherrangigen Offizier entgegenbringt.\n\n-Lieutenant Benedict" } } },
    ["Berard's Journal"] = { { ids = { "i3255" }, first = "throughstudyofvariousfos", pages = { "Nach eingehenden Studien diverser Fossilien habe ich nun herausgefunden, dass der Lordameresee vor langer Zeit von einer Seuche befallen gewesen sein muss. Was war die Ursache? Wir werden es vielleicht nie erfahren. Aber angesichts der vielen sterblichen Überreste im See muss das Wasser sehr giftig gewesen sein.", "Um mehr über die Vergangenheit zu erfahren, habe ich begonnen, die Kreaturen der Gegenwart zu untersuchen - immer in der Hoffnung, so das fehlende Glied zur Lösung des Geheimnisses zu entdecken. Bei den Seeschleichern und den Seekrabblern handelt es sich um uralte Wesen, die auf den Inseln im Lordameresee leben. Es wächst ein Moos auf ihnen, das den auf den Fossilien gefundenen Spuren gleicht. Ohne weitere Forschungen ist es jedoch zu früh für Spekulationen, was diese Verbindung zu bedeuten hat.", "Auf meiner Suche nach Moosproben stieß ich auf den Schauplatz eines blutigen Kampfes. Die Finsterflossenmurlocs wurden von einer plündernden Bande Gnolle belagert. Überall lagen tote Gnolle und Murlocs herum. Als ich an einer solchen zerschundenen Murlocleiche vorbeikam, fiel mir ein merkwürdig verhärteter Tumor auf, der aus einer der Wunden wuchs. Ich begann rasch mit der Untersuchung des Tumors und stellte fest, dass er ähnliche Eigenschaften aufwies wie das Moos, das ich sammelte. Leider fand ich keine weiteren Tumore." } } },
    ["Beyond the Dark Portal"] = { { ids = { "o21582" }, first = "onlyafewmonthsafternethe", pages = { "Nur wenige Monate nach der Vollendung von Nethergarde fügten sich die Energien des Dunklen Portals zusammen und öffneten ein neues Tor nach Draenor. Die verbliebenen Orcklans stürmten unter der Führung des großen Schamanenältesten Ner'zhul abermals nach Azeroth. Sie wollten einige magische Artefakte stehlen, die Ner'zhuls Macht noch vergrößern sollten, und schmiedeten den Plan, neue Portale in Draenor zu öffnen, um ihrer todgeweihten roten Welt für immer entfliehen zu können.", "König Terenas von Lordaeron schickte seine Armeen in der Überzeugung, dass Ner'zhul eine neue Offensive gegen die Allianz plante, nach Draenor, um die Bedrohung durch die Orcs ein für alle Mal zu beenden. Unter Führung von Khadgar und General Turalyon kam es überall in der brennenden Landschaft zu schweren Zusammenstößen zwischen den Streitkräften der Allianz und den Orcs. Doch nicht einmal mit Unterstützung der Elfenwaldläuferin Alleria, des Zwergs Kurdran und des Soldatenveteranen Danath konnte Khadgar verhindern, dass Ner'zhul Portale zu anderen Welten öffnete.", "Die ungeheuren, von den konvergierenden Energien der Portale ausgelösten magischen Stürme begannen, die verwüstete Welt auseinander zu reißen. Ner'zhul gelang in Begleitung seiner treuesten Anhänger die Flucht durch eines der Portale, während Khadgar sich verzweifelt bemühte, seine Kameraden nach Azeroth zurückzubringen. Obschon ihnen bewusst war, dass sie dann auf der sterbenden Welt gefangen wären, fassten Khadgar und seine Kameraden den selbstlosen Entschluss, das Dunkle Portal zu zerstören, damit Azeroth durch die brutale Vernichtung von Draenor keinen Schaden nehmen sollte.", "Wie es scheint, konnten die Helden das Portal zerstören und Azeroth retten - doch bleibt abzuwarten, ob sie dem Todeskampf von Draenor zu entkommen vermochten oder nicht." } } },
    ["Blackrat's Note"] = { { ids = { "i208205" }, first = "ivegotthegoodsillbehidin", pages = { "Ich habe die Ware. Ich verstecke mich bei der Nebelfichtenzuflucht, beim alten Boot. Wenn Ihr einen Eurer Leute zur Abholung schickt, sorgt dafür, dass er nicht gesehen wird!\n\n- Schwarzratte" } } },
    ["Blood-Stained Letter"] = { { ids = { "i251522" }, first = "mydearesttabithahowstran", pages = { "My dearest Tabitha,\n\nHow strange it is to foretell my own death. I've written this note as I do not know the hour when fate will claim me and although I know that this is a poor apology for a proper speech, my quill fails in its attempt to convey my pain for departing from you.\n\nEvery day I wake to the sorrow I failed to protect you from. I am sorry I could not protect our dear boy and I am sorry that my grieving has fallen into a trap from which it cannot escape.\n\nYou are my love, and my confidante and my life counted for more than it could alone. Every week when I venture into the ruins of our once proud home, I fear it would be my last, and every time I am thankful I have you to return to.\n\nI pray we are reunited, if even for a moment." } } },
    ["Bloodsail Orders"] = { { ids = { "i3921" }, first = "bloodsailorderspayattent", pages = { "Blutsegelbefehle\n\nBefolgt diese Worte hier genau, ihr Herzchen, denn in Booty Bay haben wir genau einen Schuss und nicht mehr.\n\nIch habe den alten Trunkenbold als Vorhut in den Norden geschickt und ihm gesagt, er soll auf das Signal warten.\n\nDie DAMSEL'S LUCK wird vor dem Südkap vor Anker gehen und Nachschub liefern. Die Mannschaft von Kapitän Stillwasser, unserem zu kurz geratenen Freund, wird die ganze geplünderte Beute an Bord nehmen. Ich bin mir sicher, dass sich der Schwachkopf Brutus der Sache annehmen wird.", "Ich will, dass sich Käpt'n Kielhol mit der RIPTIDE von Südosten her der Küste nähert. Wir schicken seine Mannschaft zu Fuß rein, wenn das Signal ertönt.\n\nSalzhuf, das Riesenbaby, soll mit den Männern entern. Ich will keine Gnade für Revilgaz und Seehorn. Macht Fischfutter aus ihnen, mir ist es gleich.\n\nJedenfalls seid ihr mir dafür verantwortlich, dass alles geplündert wird, was nicht niet- und nagelfest ist und uns bei unserem kleinen Vorhaben mit van Cleef in den Todesminen helfen könnte.", "Ich werde Stahlauge Befehl geben, die Geschütze abzufeuern. Das Geschützfsperrfeuer wird alle Schiffe der Schwarzmeerräuber am Ein- oder Auslaufen hindern.\n\nSobald die CRIMSON VEIL ihre Geschütze abgeladen hat, bringe ich sie längsseits der RIPTIDE, damit sie gegebenenfalls Unterstützung und Reserven zur Verfügung hat.\n\nWenn Salzhuf und seine Jungs die Stadt beschossen haben und alle Mann an Deck sind, setzen wir Segel und schicken der Bay von der Ungezähmten Küste aus noch einmal ein paar deftige Grüße.\n\n- Flottenmeister Firallon" } } },
    ["Bloodstained Journal"] = { { ids = { "i7668" }, first = "onlyportionsofthejournal", pages = { "(Blutflecken haben Teile des Tagebuchs unleserlich gemacht.)\n\nUldaman, Tag 3\n\nIch kann selbst nicht glauben, wie töricht ich war. Dass ich mich von diesen schurkischen Zwergen der Schattenschmiede so habe blenden lassen, war ein Anfängerfehler. Meine Wunden heilen langsam, ich bin ganz sicher vergiftet worden. Ich muss trotzdem weiter...\n\nSchlimmer noch - die Halskette, die der Gnom für mich gemacht hat, wurde zerrissen! Drei der größten Edelsteine aus der Kette sind fort. Ich muss sie finden, denn ohne die Steine ist die Kette machtlos...", "Uldaman, Tag 4\n\nErste Hinweise ergaben sich tief in Uldaman selbst, als einer der wildesten Troggs, die ich je gesehen habe, einen großen Saphir herumzeigte - der wohl perfekt zur Halskette passen würde. Ich hörte, wie einer der Zwerge der Schattenschmiede den Namen der Bestie nannte: Grimlok. Allerdings sind die vielen Wächter, die diese Bestie Grimlok hat,...", "Uldaman, 5. Tag\n\n...der Trogg nahm seinen getöteten \"Brüdern\" den Topas ab und ging in die Nebenhöhle nahe dem Eingang der Halle...\n\n...legte den Topas hastig in eine große, verdächtige Urne im hinteren Teil der Kammer...\n\n...ausgerechnet Zwerge! Drei an der Zahl. Momentan haben sie sich vor den Troggs verbarrikadiert. Sie zu rufen wäre einem Selbstmord gleichgekommen, denn in meinem geschwächten Zustand hätten mich die Troggs niedergemacht. Aber wenn ich den dritten Edelstein kenne, werde ich...", "Uldaman, Tag 6\n\nSo furchtbar hungrig. Mir sind die Vorräte ausgegangen und im Augenblick wäre sogar schimmeliges Brot ein Festmahl für mich...", "Uldaman, Tag 7\n\n...letzte Gelegenheit, meine Fehler wieder gutzumachen. Ich glaube, der Rubin ist in der letzten Bastion der Zwerge, die den Troggs noch nicht in die Hände gefallen ist. Ihr Kampf um die Edelsteine tobt jedoch noch immer. Es sähe diesen miesen Zwergen ähnlich, den Rubin dort versteckt zu halten. So oder so, ich muss etwas tun. Vielleicht wäre es ein probates Mittel, überfallartig zur Oberfläche vorzustoßen..." } } },
    ["Bloody Map"] = { { ids = { "i271745" }, first = "mogodunzkostahinetagolgg", pages = { "<Eine grobe Skizze der Landschaft mit einem klar gekennzeichneten Ort von Interesse.>\n\nMogodun- z kost a-hine\nta golg\ngar thon- kha z'ta gor weard-hald\n\n<Die Karte ist in einem zu schlechten Zustand, um weitere Teile der Schrift zu entziffern.>" } } },
    ["Bloody Missive"] = { { ids = { "i219929" }, first = "ourspiestellusthatsiandt", pages = { "Unsere Spione berichten, dass der SI:7 und die Silberne Hand den Köder geschluckt haben. Euer Ziel dürfte unterwegs zu Euch sein. Findet heraus, was es weiß, und schaltet es anschließend unauffällig aus, am besten draußen vor der Stadt. Wir müssen diese Eindringlinge um jeden Preis beseitigen und unser Eigentum wiedererlangen. Versagt ja nicht!" } } },
    ["Bloody Note"] = { { ids = { "i254871" }, first = "theculthitusbysurprisera", pages = { "The cult hit us by surprise. Raani never saw it coming and Arvensus took a sword to the gut. For my part, I took a lightning bolt to the chest and blacked out. They never bothered to finish me off... I guess they assumed my wounds would do me in. When it's all said and done, I suspect they might.", "Sobald die Kämpfe beendet waren, fingen sie an, riesige Kisten mit Windsteinen ganz nach oben in den Turm zu schleppen. Der Anführer, so eine Art Priester, sagte irgendwas von einem Ritual.\n\nIch schreibe diese Notiz für den Fall, dass ich es nicht zurück nach Shen'dar schaffe, um Aonda zu warnen, aber sie haben hier etwas vor. Etwas Schlimmes.", "If anyone finds this, please, do your best to stop them. There were only a few left at the tower when I scribbled this note and crawled away.\n\nAlso, try and get Raani's lucky feather from his body. He liked to tell tall tales about how he plucked it from some kind of firebird and I think he'd want to make sure that it made its way back home.\n\nIf you are also able to retrieve Arvensus Shadowsong's family signet from his body, please do so. High Elder Shadowsong is his uncle and he would want it to be returned to the family." } } },
    ["Blue Punch Card"] = { { ids = { "i9282" }, first = "donotletthisinformationf", pages = { "Diese Informationen dürfen dem Feind NICHT in die Hände fallen!\n\n01010100 01101000 01100101 00100000 01100111 01101110 01101111 01101101 01100101 00100000 01101011 01101001 01101110 01100111 00100000 01110111 01100101 01100001 01110010 01110011 00100000 01101110 01101001 01100111 01101000 01110100 00100000 01100101 01101100 01100110 00100000 01110101 01101110 01100100 01100101 01110010 01110111 01100101 01100001 01110010" } } },
    ["Bolvar's Decree"] = { { ids = { "i11368" }, first = "solomonthecarrierofthisd", pages = { "Solomon,\n\nder Überbringer dieses Dekrets hat den offiziellen Status eines Deputys von Stormwind erlangt. Ihr könnt ihn benutzen, um einen Beweis dafür zu finden, dass der schwarze Drachenschwarm sich mit den Orcs der Blackrock eingelassen hat. Sollte so ein Beweis gefunden werden, soll dieser Deputy besagten Beweis zu mir nach Stormwind bringen, woraufhin ich den Befehl erteilen werde, hinreichend Militär zur Unterstützung von Seenhain zu entsenden.\n\nHochachtungsvoll\n\nHochlord Bolvar Fordragon" } } },
    ["Bonegrip's Note"] = { { ids = { "i4649" }, first = "thestarofxilyehgrelborgt", pages = { "Der Stern von Xil'yeh\n\nGrelborg der Horter hat den Stern. Er ist ein gieriger Oger, der seine Tage im Alteracgebirge und in den Ruinen von Alterac verbringt und dort nach Schmuckstücken sucht. Die meisten seiner Stücke sind nutzlos, aber dieses eine, der Stern von Xil'yeh, hat wertvolle Eigenschaften.", "Die Hand von Dagun\n\nIn den alten Schriften heißt es, die Krallen von Dagun sonderten ein Gift ab, das die Beute nicht tötet, sondern sie in etwas anderes verwandelt - etwas, das zu den alten Völkern gehört. Der Wert der Hand für uns steht außer Frage.\n\nDagun lebt draußen im offenen Meer, wird aber regelmäßig von den Murlocs des Schlammflossenstamms in den Marschen von Dustwallow an die Oberfläche getrieben. Ihre Orakel beschwören ihn mit verzaubertem Seetang. Wenn Ihr genügend Orakel tötet, findet Ihr auch den Tang. Diesen legt Ihr dann auf den Altar der Murlocs und Dagun wird erscheinen.", "Das Herz des Vermächtnisses\n\nMogh der Unsterbliche ist ein Trollhexendoktor im Schlingendorntal. Er ist im Besitz des Herzens des Vermächtnisses, von dem es heißt, es hielte den Tod von jenen fern, die seine Geheimnisse lüften können. Ihr findet Mogh in den Ruinen von Zul'Mamwe. Besiegt ihn und bringt mir das Herz des Vermächtnisses.", "Bringt mir diese drei Dinge - den Stern, die Hand und das Herz - und 'Yagyins Zusammenstellung' ist Euer.\n\n- G.B." } } },
    ["Book from Sven's Farm"] = { { ids = { "i2161" }, first = "theterrorofthesepastfeww", pages = { "Der Schrecken der vergangenen Wochen würde übersteigen, was ich ertragen kann, könnte ich mir nicht durch das Niederschreiben dessen, was ich gesehen habe, etwas Linderung verschaffen. So schreibe ich denn. Das ist mein einziger Trost in dieser verzweifelten Zeit.", "Alles begann mit dem Fund dieser verfluchten Sense in Rolands Verdammnis. Davor war dies hier ein ebenso friedlicher Ort gewesen wie etwa das Nordhaintal.\n\nAber seit ich den Griff dieser verdammten Sense aus dem Geröll in der Mine ragen sah und es prompt nicht lassen konnte, sie - verflucht sei ich! - auch noch herauszuziehen, ist Rolands Verdammnis ein Ort des Todes!", "Nachdem ich die Sense gefunden hatte, stürzten sie sich von allen Seiten auf uns, kamen aus versteckten Löchern zu unseren Füßen oder ließen sich von oben lautlos auf uns herabfallen. Die Hälfte der Männer fiel schon in diesen ersten panikerfüllten Minuten. Der Rest - darunter auch ich - versuchte zu fliehen. Ich rannte und hörte von allen Seiten, wie meine Brüder von Klauen und Zähnen zerrissen wurden. Ich hörte unzählige Schreie, die abrupt verstummten oder in einem Gurgeln erstarben.", "Ich kann nur raten, warum ich diese Nacht überlebt habe. Ich war immer schon vorsichtig, bin Schlägen ausgewichen und habe einen Bogen um Fallgruben gemacht. Daher kommt auch mein Spitzname. Vielleicht war es also dieser Hang zur Vorsicht, der mich gerettet hat...\n\nOder es war tatsächlich diese Sense, die ich aus dem Geröll gezogen habe. An der Sense selbst kann es indes nicht liegen, denn die habe ich während meiner panischen Flucht verloren. Aber wenn ich es war, der die Worgs in den Dämmerwald führte, so haben sie mir vielleicht einen seltenen Gefallen getan. Verflucht sollen sie sein.", "Nach meiner glücklichen Flucht aus Rolands Verdammnis versteckte ich mich im Heuschober eines Mannes mit Namen Sven. Ich verbrachte dort mehrere Tage und war dabei noch so voller Furcht, dass ich mich Sven und seiner Familie nicht ein einziges Mal zeigte. Aber aus dem, was ich von meinem Versteck aus sah, konnte ich schließen, dass es sich bei diesen einfachen Bauern um anständige Leute handelte. Hätte ich meinen Unterschlupf verlassen, wäre ich von diesen Leuten sicher mit offenen Armen aufgenommen worden. Aber Vertrauen zu fassen, fällt mir schwer - und seit dem Schreck in der Mine umso mehr.\n\nAlso hielt ich mich weiter verborgen.", "<Die restlichen Seiten des Buchs sind leer.>" } } },
    ["Brazier of Invocation: User's Manual"] = { { ids = { "i22344" }, first = "brazierofinvocationusers", pages = { "RÄUCHERGEFÄSS DER ANRUFUNG: HANDBUCH\n\nWo man verfluchte Orte findet\n\nEINFÜHRUNG\n\nAuf diesen Seiten sind die Orte aufgelistet, an denen die gefallenen und korrupten Geister und Seelen derer, die in die Sache mit Lord Valthalak verwickelt waren, angetroffen werden können. Obwohl Ihr meine ehemaligen Kameraden schon errettet habt, würde ich vermuten, dass abscheuliche Echos der Korruption, die sie einst heimsuchte, immer noch an diesen verfluchten Orten verweilen. Über eine solche Kraft verfügte der rachsüchtige Geist von Lord Valthalak.\n\nDas Räuchergefäß kann außerdem dazu benutzt werden, Lord Valthalak selbst herbeizurufen. Dies sollte allerdings, wie zuvor, nur mit äußerster Vorsicht getan werden.", "EINFÜHRUNG, fortgesetzt...\n\nDieses Räuchergefäß funktioniert genau wie das Räuchergefäß der Beschwörung. Platziert es einfach an einem der fünf verfluchten Orte und es wird die Geister der Toten herbeirufen.\n\nNebenbei bemerkt, weil ich weiß, dass Ihr das gerne wissen würdet: Ihr könnt das Banner der Provokation auf ähnliche Weise in der Arena der Blackrocktiefen verwenden. Erteilt Theldren und seinen Handlangern also bitte jedes Mal eine Lektion von mir, wenn Ihr in der Gegend seid.\n\nLest weiter, wenn Ihr an weiteren Einblicken interessiert seid.", "ISALIEN\n\nNachtelfen Priesterin des Mondes\n\nAls Isalien beschloss, den Bund zu verlassen, tat sie dies um eine Pilgerreise nach Düsterbruch, der zerfallenen Heimatstadt der Nachtelfen, zu unternehmen, die einst als Eldre'Thalas bekannt war. Es gibt dort eine Bibliothek, die immenses Wissen beherbergt. Ein Heiligtum, dass eine kleine Anzahl von Elfen für sich sichern konnten. Sie war darauf versessen, Antworten zu finden. Sowohl was ihr Erbe anging, als auch im Bezug auf die Stücke des Amuletts. Es sollte auch angemerkt werden, dass sie eine gute Freundin von Farlin Treeshaper war.", "ISALIEN, fortgesetzt...\n\nUnglücklicherweise wurden sie und ihr Begleiter, ein Hippogryph names Empyrean, von Alzinn dem Wildformer und seinen Untergebenen überfallen, als sie die Stadt betraten. Und so fiel sie, und würde niemals wieder aufstehen. Vielleicht ist es das Beste, dass Isalien die Geheimnisse von Lord Valthalaks dunkler Magie nie zu ergründen vermochte, mittels der er seine Seele an das Amulett band.\n\nDie nach oben offene Kammer, in der Alzinn sich aufhält, ist einer der verfluchten Orte.", "MOR GRAYHOOF\n\nTauren Druide und das erste Opfer\n\nMor Grayhoof war eines der tapfersten und vertrauenswürdigsten Mitglieder des Bundes der verhüllten Klinge. Es ist bedauerlich, dass er der Erste war, der Lord Valthalaks grauenhaften Handlangern zum Opfer fiel.\n\nAls wir aus der Blackrockspitze flohen, wurden wir von einer wahrhaften Armee seiner spektralen Assassine und Pirscher verfolgt. Unsere Flucht aus der Blackrockspitze war chaotisch, um es milde auszudrücken. Unglücklicherweise rutschte Mor auf dem Weg irgendwann aus, obwohl ich vermute, dass er eher gestoßen wurde. Wie dem auch sei, er fiel in die Tiefen der Blackrockspitze hinab.", "MOR GRAYHOOF, fortgesetzt...\n\nSpäter erfuhren wir, dass Mor den Fall überlebt hatte. Allerdings bedeutete dies kein gutes Ende für meinen alten Freund, da er von den Trollen von Tazz'Alaor gefangen genommen wurde. Kurz darauf, während Kriegsmeister Voone ihn folterte, schlich sich eine Gruppe spektraler Assassine in die Blackrockspitze ein und setzte seinem Leben endgültig ein Ende.\n\nSolltet Ihr das Echo von Mors Geist zu erwecken wünschen, so tut dies in Kriegsmeister Voones Kammer, einem der verfluchten Orte.", "JARIEN UND SOTHOS\n\nGeschwister, die sich dem scharlachroten Kreuzzug anschließen wollten\n\nJarien und Sothos waren zwei der intolerantesten Personen, die ich jemals getroffen hatte. Allerdings waren sie formidable Kämpfer und hatten Geld, weswegen Anthion, der Anführer des Bundes der verhüllten Klinge, sie vermutlich weiterhin mit uns ziehen ließ.\n\nIrgendwann entdeckten die Geschwister ihre Liebe für die Lehren und Philosophie des scharlachroten Kreuzzugs. Sie hatten schon immer mit besonderem Eifer die Geißel vernichtet, wenn wir sie irgendwo antrafen, und es wurde vermutet, dass ihre Familie Verbindungen zu der Organisation hatte.", "JARIEN UND SOTHOS, fortgesetzt...\n\nSo geschah es also, dass sie sich den Proben gegenübersahen, die von denen bestanden werden müssen, die sich dem scharlachrotem Kreuzzug anschließen wollen. Sie strebten insbesondere das Rittertum in den Reihen des scharlachroten Kreuzzugs an, was anscheinend besonders schwierige Proben vorraussetzt. Es stellte sich später heraus, dass Sothos seine letzte Probe nicht bestanden hatte. Jarien weigerte sich, dies zu akzeptieren, und verlangte voller Trotz, dass es ihrem Bruder gestattet werden solle, sich den Rittern an ihrer Seite anzuschließen. Wie uns zugetragen wurde, erschlug der oberste Kreuzzügler Dathrohan daraufhin beide auf der Stelle, inmitten seiner Kammer.\n\nSomit ist der Purpurthron, innerhalb der scharlachroten Bastion in Stratholme, einer der verfluchten Orte.", "KORMOK\n\nZweiköpfiger Ogernekromant\n\nWas kann man über Kormok sagen? Er war ein zweiköpfiger Ogermagier, der anfänglich gar kein so übler Kerl war. Er war zuerst unser Gefangener, während eines Auftrags, den wir in der brennenden Steppe angenommen hatten. Er half uns allerdings aus einer sehr vertrackten Situation heraus, in die wir geraten waren, und wurde so zu unserem besten Magier.\n\nDas Seltsame an ihm war, dass seine beiden Köpfe völlig unterschiedliche Persönlichkeiten zu haben schienen. Der eine war immer fröhlich und etwas einfältig, während der andere listig und berechnend war und dessen Augen ein geradezu totes Aussehen hatten. Irgendwie unheimlich.", "KORMOK, fortgesetzt...\n\nKormok entdeckte im Verlauf unserer Reisen die nekromantische Seite der Magie. Bedauerlicherweise entwickelte sein unheimlicher Kopf eine Affinität für das Beschwören von toten Geistern, was ihm ein geradezu perverses Vergnügen bereitete. Er liebte es besonders, die verbannten Geister der Fegefeuer-Insel zu beschwören und sie ihm dienen zu lassen.\n\nNachdem sich unser Bund auflöste, schrieb er sich in Scholomance ein, um sich \"weiterzubilden\". Die spektralen Assassine drangen ohne Probleme dort ein und erschlugen ihn direkt vor den Augen seines neuen Meisters, Ras Frostraunen.\n\nSomit ist Ras Frostraunens Kammer einer der verfluchten Orte, an denen das Räuchergefäß benutzt werden kann.", "LORD VALTHALAK\n\nDrachischer Adliger und ehemaliger General der Blackrockspitze\n\nVor General Drakkisath war Lord Valthalak, ein drachischer Hexenmeister von immenser Macht, der Herrscher der Blackrockspitze. Es ist üblich, dass die Herrschaft der Blackrockspitze von einem General zum anderen übergeht, zu unserem Pech spielten wir allerdings eine maßgebliche Rolle in dieser Verschiebung der Macht.\n\nWir wurden von einem Goblinschmuggler und -magier aus Booty Bay namens Gremnik Rizzlesprang angeheuert, um Lord Valthalaks Zauberbuch zu stehlen. Wir wussten nicht, ob er es studieren oder verkaufen (oder beides) wollte, und dass macht jetzt auch keinen Unterschied mehr. Wichtig ist nur, dass wir in die oberen Bereiche der Blackrockspitze vorstießen und Lord Valthalak in seinem Hort erschlugen. Von da an ging der Spaß so richtig los.", "LORD VALTHALAK, fortgesetzt...\n\nWir hatten keine Ahnung, wie immens Lord Valthalaks magisches Wissen bezüglich Seelenmanipulation war, ansonsten hätten wir den Auftrag vermutlich niemals angenommen. Aber wir nahmen ihn an und es sollte der letzte Auftrag sein, den wir je annehmen würden.\n\nNachdem wir Lord Valthalak besiegt und sein Zauberbuch an uns genommen hatten, muss Kormok wohl irgendetwas von seinem Amulett ausgehen gespürt haben. Er bestand darauf, es als seinen Teil der Beute an sich zu nehmen. Daraufhin brach eine hitzige Diskussion aus, die fast in einem Kampf endete. Zu diesem Zeitpunkt waren wir uns nicht darüber im Klaren, dass das Amulett einen Großteil von Lord Valthalaks Seele enthielt. Das erfuhren wir erst viel später, zu unserem großen Verdruss.", "LORD VALTHALAK, fortgesetzt...\n\nNachdem wir das Amulett in drei Stücke aufgeteilt hatten, flohen wir vor Lord Valthalaks auferstandenem Geist und seiner Armee von spektralen Assassinen aus der Blackrockspitze. Außerdem hatte der Lärm, den wir verursacht hatten, als wir uns um das Amulett stritten, die anderen Verteidiger der Blackrockspitze aufgeschreckt!\n\nFast jeder von uns schaffte es, aus der Blackrockspitze zu fliehen, und wir glaubten uns in Sicherheit. Aber Lord Valthalak hetzte seine Untergebenen selbst aus dem Jenseits auf uns, egal, wo wir uns auch versteckten. Der Bund der verhüllten Klinge brach kurz nach diesem Auftrag endgültig zusammen und so waren wir leichte Opfer.\n\nWie Ihr ja sicherlich bereits wisst, ist die Kammer der Bestie in der Blackrockspitze Lord Valthalaks momentaner Aufenthaltsort und somit der letzte der verfluchten Orte." } } },
    ["Brock's List"] = { { ids = { "i16310" }, first = "belowistheliststudentswh", pages = { "Nachfolgend findet Ihr eine Liste der Schüler, die beim Abschluss an Brocks Bergbau- und Feldmesserschule einen Platinstern erreicht und sich die Ehrenminenarbeiterhacke verdient haben:\n\nMelia Stoneshaker\nBardin Ironband\nUmi Togglevolt\nRumi Togglevolt\nVorel Steelspire" } } },
    ["Call to Arms Announcement"] = { { ids = { "i22595" }, first = "toallablebodiedmenandwom", pages = { "An alle kampftauglichen Männer und Frauen:\n\nDie Geißel ist zurückgekehrt! Wir müssen unsere alltäglichen Zwistigkeiten vergessen und dieser Bedrohung vereint entgegentreten. Die Argentumdämmerung wird niemanden zurückweisen, der gemeinsam mit uns seine Waffe gegen die Geißel erheben will.\n\nJene, die unser Land verteidigen wollen, sammeln sich in den östlichen Pestländern vor den Toren der Kapelle des hoffnungsvollen Lichts. Gemeinsam werden wir siegen.\n\nGezeichnet, der Bewahrer der Schriften\nDie Argentumdämmerung" } } },
    ["Calor's Note"] = { { ids = { "i2113" }, first = "mastercarevinthebearerof", pages = { "Meister Carevin,\n\n $gdieser Bote:diese Botin; hat sich als Wesen des Lichts erwiesen, als tapfer im Kampf gegen die Untoten und Dämonen am Rande des Dämmerwalds und willens, mit Eurer Familie für die große Sache des Lichts zu streiten.\n\nIch würde daher vorschlagen, Ihr gebt dieser Lichtgestalt weitere Aufgaben - vielleicht die Überwachung einiger Verdächtiger in der Stadt, von denen wir vermuten, dass sie mit den Feinden des Lichts paktieren.\n\nDas Licht zum Gruße\nCalor" } } },
    ["Captain's Documents"] = { { ids = { "i5882" }, first = "thebleedingsparrowmanife", pages = { "Die \"Bleeding Sparrow\": Ladeliste\n\n(20) Fässer Rum. Ziel: Theramore\n(50) Säcke Mehl. Ziel: Theramore\n(2) Kisten diverses Gnomenwerkzeug. Ziel: Ratchet\n(30) Ballen Baumwollstoff. Ziel: Theramore\n(4) Kisten Gewürze. Ziel: Theramore\n(3) Passagiere. Ziel: Theramore", "Captain,\n\nich wünsche Euch Glück auf Euren Reisen. Leider war uns das Glück bei unserem ersten Entführungversuch nicht hold.\n\nAls unsere Gruppe in den Gängen unter Stormwind bzw. Ironforge auf die Zielperson traf, fand sie dort nur einen Lockvogel vor. Er ist wohl doch schlauer als wir ihm zugetraut haben.\n\nAber unser zweiter Plan läuft. Agenten der Defias warten darauf, die Zielperson abzufangen, wenn sie sich Theramore nähert. Bald wird Stormwind unseren Zorn zu spüren bekommen!\n\n- M" } } },
    ["Certificate of Thievery"] = { { ids = { "i7907" }, first = "thebearerofthiscertifica", pages = { "Dem Träger dieses Zertifikats gebühren Respekt und Achtung, wie es jeder erstklassige Plünderer und Dieb verdient." } } },
    ["Charge of the Dragonflights"] = { { ids = { "o175726" }, first = "satisfiedthatthesmallwor", pages = { "Damit zufrieden, dass Ordnung auf die kleine Welt gebracht worden und ihre Arbeit getan war, bereiteten sich die Titanen darauf vor, Azeroth zu verlassen. Vor ihrem Aufbruch jedoch wiesen sie noch der größten Spezies dieser Welt die Aufgabe zu, Kalimdor zu behüten, sollte je etwas den perfekten Frieden bedrohen. In jenem Zeitalter existierten viele Drachenschwärme.", "Fünf Drachenschwärme gab es, die Macht über ihre Brüder ausübten. So beschlossen die Titanen, die aufblühende Welt in die Obhut dieser fünf Klans zu geben. Die größten Mitglieder des Pantheons erfüllten jeden Anführer eines Klans mit einem Teil ihrer Macht. Diese majestätischen Großdrachen (nachfolgend aufgeführt) wurden unter der Bezeichnung Große Aspekte oder Großdrachenaspekte bekannt.", "Aman'Zhul, der Hochvater des Pantheons, spendete einen Teil seiner kosmischen Macht dem gewaltigen Bronzegroßdrachen Nozdormu. Der Hochvater ermächtigte Nozdormu, die Zeit selbst zu hüten und die sich ewig kreuzenden Pfade von Vorbestimmung und Schicksal zu bewachen. Der stoische, ehrbare Nozdormu bekam den Beinamen der Zeitlose.", "Eonar, die Schützerin allen Lebens bei den Titanen, gab einen Teil ihrer Macht dem roten Leviathan Alexstrasza. Fortan wurde Alexstrasza Lebensbinderin genannt und sie beschützte unermüdlich alle lebendigen Geschöpfe auf der Welt. Wegen ihrer großen Weisheit und grenzenlosen Liebe zu allen Lebewesen krönte man Alexstrasza zur Drachenkönigin und machte sie zur Herrscherin ihrer Art.", "Eonar segnete auch Alexstraszas jüngere Schwester, den wendigen grünen Großdrachen Ysera, mit einem Teil des Einflusses der Natur. Ysera versank, an den Wachtraum der Schöpfung gebunden, in eine ewige Trance. Unter dem Namen 'die Träumerin' behütete sie aus ihrem grünen Reich, dem Smaragdgrünen Traum, die wachsenden Wildgebiete der Welt.", "Norgannon, der Bewahrer der Lehre und Meistermagicus der Titanen, gewährte Malygos, dem blauen Großdrachen, einen Teil seiner unglaublichen Macht. Fortan hieß Malygos Zauberwirker, Wächter der Magie und des verborgenen Arkanums.", "Khaz'goroth, der Former und Weltenschmied der Titanen, gab einen Teil seiner riesigen Macht dem mächtigen schwarzen Wyrm Neltharion. Der großherzige Neltharion, fortan als Erdwärter bekannt, erhielt die Herrschaft über die Erde und die tiefen Regionen der Welt. Er verkörperte die Kraft der Welt und fungierte als größter Unterstützer von Alexstrasza.", "Solchermaßen ermächtigt erhielten die Fünf Aspekte die Aufgabe, die Welt in Abwesenheit der Titanen zu schützen. Nachdem die Großdrachen bereit waren, ihre Schöpfung zu verteidigen, verließen die Titanen Azeroth für immer. Zu ihrem Unglück dauerte es nicht lange, bis Sargeras von der Existenz der neugeborenen Welt erfuhr..." } } },
    ["Charred Note"] = { { ids = { "i205864" }, first = "adaimpleasedtohearisland", pages = { "<Die Seite ist an mehreren Stellen verbrannt, als hätte jemand hastig versucht, sie zu verbrennen. Teile der Schrift sind noch lesbar.>\n\nAda,\n\nich freue mich, zu hören-------- Insel am dunklen Ufer. ---- Einer unserer Agenten -------- Passwort ----\n\n\"Wird eine Kerze gelöscht, wird eine andere entzündet.\"\n\n- Mitchells" } } },
    ["Civil War in the Plaguelands"] = { { ids = { "o175761" }, first = "nerzhulthelichkingknewth", pages = { "Ner'zhul, der Lichkönig, wusste genau, wie knapp bemessen seine Zeit war. In seinem Gefängnis im Frost-Thron argwöhnte er, dass Kil'jaeden seine Agenten herschicken würde, um ihn zu vernichten. Der Schaden, den Illidans Zauber verursachte, hatte den Frost-Thron entzweigerissen, dadurch verlor der Lichkönig Tag für Tag an Macht. Im verzweifelten Bemühen, sich zu retten, rief er seinen größten sterblichen Diener an seine Seite: den Todesritter Prinz Arthas.", "Arthas war, obwohl ihn die Schwäche des Lichkönigs seiner Macht beraubte, in Lordaeron in einen Bürgerkrieg verstrickt. Die Hälfte der stehenden Streitmacht der Untoten putschte unter Führung der Banshee Sylvanas Windrunner, um die Herrschaft über das Reich der Untoten an sich zu reißen. Arthas, den der Lichkönig gerufen hatte, war gezwungen, die Geißel seinem Offizier Kel'Thuzad zu überlassen, als der Krieg in den Pestländern eskalierte.", "Schließlich und endlich übernahmen Sylvanas und ihre rebellischen Untoten (die \"Verlassene\" genannt wurden) die zerstörte Hauptstadt von Lordaeron. Die Verlassenen errichteten ihre eigene Bastion unter der verwüsteten Stadt und schworen, dass sie die Geißel besiegen und Kel'Thuzad und seine Diener aus dem Land jagen würden.", "Geschwächt, aber fest entschlossen, seinen Meister zu retten, traf Arthas in Northrend ein, wo er bereits von den Naga und Blutelfen erwartet wurde. Er lieferte sich nebst den verbündeten Nerubern einen Wettlauf mit Illidans Truppen zum Eiskrone-Gletscher, um den Frost-Thron zu verteidigen." } } },
    ["Cliffwatcher Longhorn Report"] = { { ids = { "i13507" }, first = "natakaalliswellinthousan", pages = { "Nataka, in Tausend Nadeln steht alles zum Besten. Die Zentauren sind verärgert, aber das sind wir gewöhnt... gelegentliche Angriffe, aber sonst nichts, was man als eine ernsthafte Bedrohung betrachten könnte. Es scheinen jedoch Neuigkeiten im Umlauf zu sein, wonach sich die Zentaurenklans zusammenschließen sollen.\n\nWir haben uns schon immer Gedanken gemacht, welche Gefahr der Zusammenschluss eines solch unbarmherzigen Volkes wie den Zentauren darstellen würde... Ich mag gar nicht näher darüber nachdenken, denn wie Ihr wisst... könnte nichts den tiefen Hass überwinden, den sie in sich tragen... sogar aufeinander.\n\n-Klippenbehüter Longhorn" } } },
    ["Cloth Request"] = { { ids = { "i2724" }, first = "totheschneidersgooddayit", pages = { "An die Schneiders,\n\nguten Tag. Ich hoffe, die Geschäfte im Kanaldistrikt laufen gut. Wir hier am Händlerplatz können uns über mangelnde Arbeit jedenfalls nicht beklagen.\n\nWir brauchen dringend neue Strickstoff-Waren, denn unser Vorrat geht zur Neige. Bitte schickt uns schnellstmöglich die übliche Ladung.\n\nGutes Gelingen! Ich hoffe, die Studien Eures Sohnes Thurman schreiten rasch voran,\n\n- Harlan Bagley" } } },
    ["Compendium of the Fallen"] = { { ids = { "i5535" }, first = "withkelthuzadssuccessinl", pages = { "Nach Kel'Thuzads Erfolg in Lordaeron traf der Lichkönig letzte Vorbereitungen für seinen Großangriff gegen die menschliche Zivilisation. Ner'zhul füllte seine Seuchenenergien in eine Reihe tragbarer Artefakte, die Seuchenkessel genannt wurden, und befahl Kel'Thuzad, die Kessel nach Lordaeron zu bringen, wo sie in den zahlreichen vom Kult beherrschten Dörfern versteckt werden sollten.", "Die von den getreuen Kultisten beschützten Kessel sollten als Seuchengeneratoren fungieren und die Seuche unter den ahnungslosen Bürgern der Landstriche und Städte nördlich von Lordaeron verbreiten.\n\nDer Plan des Lichkönigs ging auf. Viele der nördlichen Dörfer von Lordaeron wurden fast auf der Stelle verseucht. Bürger, die sich mit der Seuche ansteckten, starben, um als willige Sklaven des Lichkönigs wieder aufzuerstehen, genau wie in Northrend.", "Die Kultisten unter Kel'Thuzad waren begierig darauf, zu sterben und in den Diensten ihres dunklen Lords ihre Auferstehung zu erleben. Sie bejubelten die Aussicht auf Unsterblichkeit in einem Dasein als Untote. Und je mehr die Seuche sich ausbreitete, desto mehr wilde Zombies erstanden in den Nordlanden. Kel'Thuzad betrachtete die wachsende Armee des Lichkönigs und nannte sie die Geißel - denn bald schon sollte sie zu den Toren von Lordaeron marschieren... und die Menschheit vom Antlitz der Erde tilgen." } } },
    ["Confidential Message"] = { { ids = { "i210967" }, first = "brotheresolonshouldyoune", pages = { "Bruder Esolon,\n\nFalls Ihr auf das Reliquiar zugreifen müsst, ich habe einen Schlüssel dafür auf dem Friedhof versteckt. Er befindet sich in einer Steintruhe unter dem Boden des nördlichen Mausoleums.\n\nEs gibt einen Mechanismus, der die Truhe anhebt. Um ihn zu aktivieren, müsst Ihr Euch auf die beiden Sitzbänke zwischen den Statuen an den Seiten des Friedhofs setzen.\n\nBitte betrachtet diese Information als streng vertraulich.\n\nViel Glück,\nBruder Seramus" } } },
    ["Consecrated Letter"] = { { ids = { "i9570" }, first = "ihopethisletterfindsyouw", pages = { "Ich hoffe, dieser Brief erreicht Euch bei guter Gesundheit, $C. Ich sage dies mit großem Stolz, da nicht viele so tiefen Glauben zeigen können, wisset jedoch auch, dass sie zu den Besten der Besten der Beschützer von Azeroth zählen.\n\nVergesst niemals, Euer erster und wichtigster Gedanke sollte stets Eurer Pflicht gelten, die zu bekämpfen, die unserer Welt schaden und Verderbnis in unsere Häuser bringen wollen.\n\nIch bin berechtigt, Euch zu unterweisen, zumindest vorläufig. Wenn Ihr bereit seid, findet Ihr mich in der Abtei von Nordhain.\n\n- Bruder Sammuel, Paladinlehrer" } } },
    ["Consecrated Rune"] = { { ids = { "i9563" }, first = "somefearourkindmorethand", pages = { "Einige fürchten unsere Art mehr als die Drachen. Einige beneiden uns mehr als selbst die begnadetsten Schmiede. Einige preisen unsere Stärke im Kampf. Andere freuen sich an unserem Glauben. Einige sind einfach nur neidisch, dass wir sie unter den Tisch trinken können! Aber wisset dies, $C, Ihr seid unter den besten Beschützern von ganz Azeroth. Das Heilige Licht gibt uns so viel Kraft, wie wir es stärken.\n\nIch werde Euch mehr erzählen, wenn Ihr Euch ein wenig mit dem Land vertraut gemacht habt. Ihr findet mich in Anvilmar über dem Tal.\n\n- Bromos Grummner, Paladinlehrer" } } },
    ["Consecrated Scroll"] = { { ids = { "i282423" }, first = "welcomebackiunderstandal", pages = { "Willkommen zurück, $N.\n\nIch kenne den Schock nur zu gut, den man empfindet, wenn man sich in der Situation befindet, in der Ihr Euch gerade befindet. Die Tatsache, dass Ihr es so weit geschafft habt, hebt Euch von den anderen neuen Paladinen ab.\n\nIhr werdet feststellen, dass der schwierigste Teil Eures neuen Lebens darin bestehen wird, wiederzuentdecken, was Ihr im Leben verloren habt... und den Schmerz zu überstehen, den das verursacht hat.\n\nSprecht mit mir in Deathknell und ich werde Euch dabei helfen, die Entschlossenheit zu finden, die Ihr für Eure ersten Schritte braucht.\n\n- Aramis Hammerhand, Paladinlehrer" } } },
    ["Control Console Operating Manual"] = { { ids = { "i5088" }, first = "thesamophlangecontrolcon", pages = { "Die Steuerkonsole des Samophlangs kann zur automatischen Regulierung des Flusses von Treibstoff, Gasen, Schmierstoffen und der dazugehörenden Maschinen verwendet werden. Sobald die primäre Konfiguration abgeschlossen ist, sollte die Konsole mit minimaler Wartung einwandfrei laufen.\n\nKurze Auflistung der Komponenten der Steuerkonsole (von links nach rechts):\n\nI. Hauptenergiehebel\n\nIn eingeschalteter Position aktiviert er das Samophlang. Der Steuermechanismus schaltet sich nicht automatisch ab, wenn der Hebel umgelegt wird. Dadurch wird lediglich", "der Abkühlprozess eingeleitet. Danach dauert es (je nach Situation) etwa ein bis zwei Minuten, bis der Steuermechanismus abgeschaltet ist.\n\nWICHTIGER HINWEIS: Der Hauptenergiehebel kann nur dann bewegt werden, wenn die drei Steuerventile der eigentlichen Maschine ausgeschaltet sind. Diese Ventile können in beliebiger Reihenfolge abgestellt werden.\n\nDas erste Ventil ist das HAUPTSTEUERVENTIL, das sich unten an einem großen, senkrechten Schornstein befindet. Das zweite Ventil ist das TREIBSTOFFZUFUHRVENTIL, das sich an der großen Röhre befindet, die", "von den Treibstofftanks (drei an der Zahl) zum Schornstein führt. Das REGELVENTIL schließlich befindet sich am unteren der beiden zylindrischen Tanks, die in den Schornstein münden.\n\nII. Tankanzeige\n\nZeigt den momentanen Druck im primären, sekundären und tertiären Treibstofftank an.\n\nIII. Fließanzeige\n\nZeigt die momentane Fließrate im System an.", "IV. Fließkontrolle\n\nZum Erhöhen oder Verringern der Fließrate. Wird vom Steuermechanismus des Samophlangs automatisch geregelt.\n\nV. Temperaturanzeige\n\nZeigt die allgemeine Betriebstemperatur des Systems an." } } },
    ["Covert Ops Plans: Alpha & Beta"] = { { ids = { "i5737" }, first = "okayyoushouldhaveyourngc", pages = { "Gut, die NG-5-Ladungen und die Zünder sollten so weit sein. Ich habe sie für Euch markiert. Blau steht für das Sägewerk. Rot steht für die Scherwindmine.\n\nIch habe mich ein wenig umgesehen: Bei der Scherwindklippe gibt es so viel Sprengstoff, dass es Euch keine Mühe machen dürfte, hineinzukommen, die Sprengladungen anzubringen und wieder zu verschwinden.\n\nDenkt daran, dass es sich um ein Ablenkungsmanöver handelt. Entfernt Euch von den Wagen, bevor die Goblins rauskommen, um nachzusehen, was passiert ist. Dann schleicht Euch hinter ihnen rein.", "Im Übrigen seid vorsichtig damit. Das Nitromirglyceronium allein könnte Euch schon pulverisieren. Ich habe etwas von der Flüssigkeit in Kupferröhrchen gefüllt. Darin sollte sie sich sicher aufbewahren lassen.\n\nDie Schriftrolle, die Ihr von Collin bekommen habt, habe ich für die Zündkapseln verwendet. Von ihnen geht ein lautloser Befehl an die NG-5-Ladungen, nachdem Ihr diese scharf gemacht habt. Ich habe einen einfachen Stalthwargon-Mechanismus verwendet, um sicherzustellen, dass die Leitfähigkeit der Drähte optimal und der Fluss des Nitroglyceroniums zwischen der Differentialflüssigkeit überdurchschnittlich ist.", "Bevor ich nun zu den Einzelheiten meines Plans komme, lasst mich noch erklären, wo Ihr die Sprengladungen anbringen sollt.\n\nPlan A - das Sägewerk:\nVor dem Sägewerk steht ein Wagen (nordöstlich der Entwaldungs- und Holzsammelanlage). Ich nehme stark an, die Konstruktionspläne befinden sich im Sägewerk.\n\nBringt die Ladung hinten am Wagen an. Sobald sie scharf ist, solltet Ihr schleunigst das Weite suchen.", "Wenn Ihr so weit seid, drückt den Auslöser.\n\nIch habe für ein starkes Signal gesorgt, indem ich Kupfer- und Silberdrähte in der Ummantelung des Kastens mit einem Antennen-Array nach Melthus gekoppelt habe. Das sollte Euch eine gute Reichweite verschaffen. Achtet bloß auf die Goblins in der Nähe. Sie werden wohl nicht begeistert von meiner kleinen Erfindung sein, wenn sie Euch damit erwischen.\n\nOh, und nur, falls es nicht ohnehin klar sein sollte: Haltet Euch bei der Explosion vom Wagen fern... Ihr könntet Euch sonst wehtun.", "Plan B - Scherwindmine:\n\nIch habe gesehen, wie die Goblins nördlich des Mineneingangs einen weiteren Wagen mit Sprengstoff benutzt haben. Ich denke, an dieser Stelle sollten wir dann auch die rote NG-5-Ladung anbringen. Wenn Ihr die Ladung hinten im Wagen scharf gemacht habt, bringt Euch in Sicherheit und drückt den Auslöser.\n\nWenn die Goblins danach nicht rausgerannt kommen, um zu sehen, was los ist, dann ist wahrscheinlich der Berg über ihren Köpfen zusammengebrochen.", "Der Name \"Venture Co.\" ist draußen vor der Mine deutlich sichtbar... Ich glaube, er steht auch auf ein paar Kisten auf der untersten Ebene.\n\nViel Glück - und denkt daran...\n\nBlaue Ladung: Sägewerk\nRote Ladung: Mine\n\nOh, und vernichtet diesen Brief, wenn der Auftrag ausgeführt ist. Hmm, vielleicht sollte ich etwas erfinden, womit sich diese Dinger nach dem Lesen selbst zerstören... Hm, gar keine so üble Idee!" } } },
    ["Crate of Horseshoes"] = { { ids = { "i1284" }, first = "anoteisattachedtothecrat", pages = { "An der Kiste hängt eine Notiz. Darauf steht:\n\n\"Verner - tut mir Leid zu hören, dass das Rotkammgebirge solchen Ärger hat. Hier sind die angeforderten Hufeisen. Ich möchte dafür umgehend 100 Silbertaler.\"\n\n\"Du kannst mich aber auch in Unterbauchschuppen von schwarzen Großdrachenwelpen bezahlen (Ich habe gehört, Großdrachenwelpen seien in den Rotkammbergen keine Seltenheit.). Und weil wir Freunde sind … bin ich mit 4 Schuppen einverstanden. Danke - Argus\"" } } },
    ["Crude Map"] = { { ids = { "i21037" }, first = "", pages = { "" } } },
    ["Crumpled Note"] = { { ids = { "i4100" }, first = "fleeingfromthezanzilinth", pages = { "In diesem altersschwachen Boot vor den Zanzil zu fliehen, schien mir damals eine gute Entscheidung zu sein, aber inzwischen frage ich mich, ob der Tod nicht doch die bessere Wahl gewesen wäre.\n\nIch hatte geglaubt, meine Vorfahren täten mir einen Gefallen, indem sie mich vor ihrem Zorn schützten. Aber jetzt frage ich mich, was ich aus einem Leben in Gefangenschaft lernen soll." } }, { ids = { "i282419" }, first = "youvegotagoodswordarmand", pages = { "$N, Ihr führt Euer Schwert geschickt, das habe ich zur Kenntnis genommen.\n\nEin schöner Schlamassel ist das auf der Insel Zephras, kein Zweifel. Unsere kämpfenden Shen'dorei müssen in Bestform bleiben, wenn wir das überleben wollen, was uns bevorsteht. Es ist an der Zeit, dass Ihr nicht nur vorgebt, $gein wahrer Krieger:eine wahre Kriegerin; zu sein, sondern diese Rolle nun auch wirklich einnehmt.\n\nFindet mich im Wachturm hier in Thendal. Ich werde dafür sorgen, dass Ihr eine angemessene Ausbildung erhaltet.\n\n- Klingenmeisterin Ren, Kriegerlehrerin" } } },
    ["Crystal Pylon User's Manual"] = { { ids = { "i11482" }, first = "crystalpylonusersmanuala", pages = { "HANDBUCH FÜR KRISTALLPYLONEN\n\n \"Eine Anleitung zum Sammeln und Benutzen von Machtkristallen aus dem Un'Goro Krater.\"\n\nKapitel 1: Der nördliche Pylon\n\nKapitel 2: Der östliche Pylon\n\nKapitel 3: Der westliche Pylon", "Kapitel 1: DER NÖRDLICHE PYLON\n\nDer nördliche\nPylon akzeptiert\ngelbe, rote\nund grüne\nKristalle.\n\nDer Pylon fokussiert auf die Energie, die mit den gelben Kristallen als Hauptenergiequelle erzeugt werden kann.", "Nördliche Kristallkombinationen\n\nEs gibt zwei mögliche Effekte: Einer, der Schaden erzeugt, und einen, der Schaden verhindert.\n\nKRISTALLSPRENGLADUNG: Erfordert rote und gelbe Kristalle.\nDamit wird eine gewaltige Explosion erzeugt, die Eure Feinde lähmt.\n\nKRISTALLFLICKER: Erfordert gelbe und grüne Kristalle.\nDas verleiht Euch eine heilende Aura.", "NORDPYLON-SCHRIFTTAFEL-DIAGRAMM", "Kapitel 2: DER ÖSTLICHE PYLON\n\nDer östliche\nPylon akzeptiert\nblaue, gelbe und\ngrüne\nKristalle.\n\nDer Pylon fokussiert auf die Energie, die mit den blauen Kristallen als Hauptenergiequelle erzeugt werden kann.", "Östliche Kristallkombinationen\n\nEs gibt zwei mögliche Effekte: Einer verleiht der Willenskraft einen Bonus, einer erzeugt einen Schaden zufügenden Schild.\n\nKRISTALLKRAFT: Erfordert blaue und grüne Kristalle.\nDas verleiht Euch eine Erhöhung der Willenskraft.\n\nKRISTALLSPITZE: Erfordert blaue und gelbe Kristalle.\nDamit wird ein Schild erzeugt, der Angreifern Schaden zufügt.", "OSTPYLON-SCHRIFTTAFEL-DIAGRAMM", "Kapitel 3: DER WESTLICHE PYLON\n\nDer westliche\nPylon akzeptiert\nrote, grüne\nund blaue\nKristalle.\n\nDer Pylon fokussiert auf die Energie, die mit den roten Kristallen als Hauptenergiequelle erzeugt werden kann.", "Westliche Kristallkombinationen\n\nEs gibt zwei mögliche Effekte: Einer erhöht Euren Schutz vor Schaden, einer schwächt die Verteidigung des Gegners.\n\nKRISTALLBARRIERE: Erfordert rote und grüne Kristalle.\nDas verleiht Euch eine Erhöhung der Rüstung.\n\nKRISTALLSCHWÄCHER: Erfordert blaue und rote Kristalle.\nDamit kann die Rüstung eines bestimmten Ziels verringert werden.", "WESTPYLON-SCHRIFTTAFEL-DIAGRAMM" } } },
    ["Crystallized Note"] = { { ids = { "i10839" }, first = "towhomitmayconcernifyoua", pages = { "Wen immer es betrifft:\n\nWenn Ihr diese Notiz lest, seid Ihr an einem von zwei Orten:\n\n(1) Auf der Südhalbinsel von Azshara.\n\n(2) Im Bauch eines Klippenriesen.\n\nBeides ist gleichermaßen misslich.\n\nMan sollte beachten, dass ich mich an Ersterem befand, und nun, während ich diesen Brief schreibe, an Letzterem.", "Im Bauch eines Klippenriesen hat man viel Zeit zum Nachdenken.\n\nWährend mein Körper kristallisiert, komme ich zu der Erkenntnis, dass es möglicherweise bereits genügend Helden auf dieser Welt gibt. Sollte ich irgendwie aus dieser misslichen Lage herauskommen, drehe ich diesem Orc den Geisterhals um!\n\n- Windan Shay" } }, { ids = { "i10840" }, first = "whatwasithinkingperhapsa", pages = { "Was habe ich mir nur gedacht?\n\nEine bessere Frage wäre vielleicht: Wie komme ich nur dazu, eine Notiz zu schreiben, während ich im Bauch eines Riesen gefangen bin?\n\nBeides gute Fragen, auf die mir so schnell keine Antworten einfallen...\n\nZugegebenermaßen befand ich mich nicht auf einer uneigennützigen Mission. Ich war auf der Suche nach Azsharit, einem einzigartigen Kristall, der ausschließlich im Süden von Azshara vorkommt. Ach, welche Reichtümer hätten mein sein können!\n\nPah! Und was ist stattdessen aus mir geworden...", "Sollte eine Form von intelligentem Leben diese Notiz finden, so muss sie sich fragen: \"Warum, um alles in der Welt, legt man sich mit brutalen, zehn Meter großen Riesen an?\"\n\n- Mook" } } },
    ["Cutty's Note"] = { { ids = { "i203723" }, first = "ivegotthegoodsillbehidin", pages = { "Ich habe die Ware. Ich werde mich oben am Fluss, der aus dem Kristallsee entspringt, in der Nähe der Mauer verstecken. Wenn Ihr einen Eurer Agenten zur Abholung schickt, soll er außer Sicht bleiben!\n\n- Schnitti" } } },
    ["Damp Diary Page (Day 4)"] = { { ids = { "i6304" }, first = "diarydayihavebeenstrande", pages = { "Tagebuch - Tag 4\n\nIch bin jetzt vor vier Tagen auf dieser Insel gestrandet und habe nichts anderes zu tun, als meinen Gedanken nachzuhängen. Die Bananen sind recht schmackhaft, bloß muss man so viel klettern, um sie zu erreichen. Wenn ich nicht gerade auf Nahrungssuche bin oder mich vor den regelmäßig wiederkehrenden Regengüssen schütze, denke ich nur daran, wie ich von dieser Insel runterkomme.\n\nIch hätte freilich keine Hoffnung, wären da nicht all die Kisten mit Papier und Flaschen, die mit mir an Land gespült worden sind. Heute muss ich lachen, wenn ich daran denke, wie oft ich darüber geflucht habe, dass ich auf einem Schiff voller Alchimisten und Gelehrten festsaß." } } },
    ["Damp Diary Page (Day 512)"] = { { ids = { "i6306" }, first = "diarydaythebananashavest", pages = { "Tagebuch - 512. Tag\n\nDie Bananen haben angefangen, mit mir zu reden, und ich habe eine Menge über ihre Kultur erfahren. Ich habe mit der sinnlosen Zerstörung ihres Zuhauses und dem Verspeisen ihrer Jungen aufgehört. Wie wenig wusste ich doch von der großartigen Zivilisation, die ich da zerstörte!\n\nAnsonsten gehen mir allmählich Flaschen und Papier aus. Als ich zu Anfang auf diesen gewaltigen Haufen Papier blickte, schien er mir unerschöpflich zu sein. Weh mir, mein Tagebuch muss bald ein Ende finden." } } },
    ["Damp Diary Page (Day 87)"] = { { ids = { "i6305" }, first = "thesemonthshavegivenmeti", pages = { "In diesen Monaten hatte ich Zeit nachzudenken und alte Überzeugungen und Fanatismus über Bord zu werfen. Allianz? Horde? Gut? Böse? Der Sinn dieser Worte, einst so klar, wird nun trübe, da ich den Blick über das grenzenlose Meer schweifen lasse.\n\nIch weiß jetzt, was zählt. Die Bananen sind hinter mir her.\n\nHoch droben auf ihren Bäumen beobachten sie mich mit kalter Bösartigkeit. Die Letzte, die ich zu essen versuchte, erwürgte mich fast! Fast konnte ich sie schreien hören, als ich sie halb aufgegessen auf den Meeresklippen zerschmetterte.\n\nEs ist ein Krieg, und ich werde ihn gewinnen." } } },
    ["Danath Trollbane"] = { { ids = { "o25332" }, first = "danathtrollbanemilitiaco", pages = { "Danath Trollbane\n\nMiliz-Kommandant von Stromgarde. Taktischer Berater von General Turalyon, Kommandant der Allianz-Expedition, die in Draenor, der Heimat der Orcs, einmarschierte. Vermutlich gefallen.\n\nWir ehren dein Andenken, Neffe, und dein Opfer. Seit Gründung unseres Imperiums ist der Weg zur Tapferkeit mit dem Blut von Helden getränkt.\n\n- Thoras Trollbane, Lord von Stromgarde" } } },
    ["Dark Iron Script"] = { { ids = { "i6847" }, first = "dirtytroggsaresoeasytofo", pages = { "Die blöden Troggs sind so leicht zu täuschen. Durch ihren Hass auf uns sind sie ganz leicht zu leiten und als Schachfiguren zu benutzen. Es wundert mich, dass überhaupt eine Allianz zustande gekommen ist, aber wir stellen eben im Moment die größere Bedrohung für sie dar.\n\nWenn die Angriffe allerdings erst einmal begonnen haben, werden beide Seiten geschwächt und anfällig sein. Nehmt das Gehöft südlich des Helmsbedsees und wartet auf weitere Anweisungen.\n\nIronforge wird uns gehören." } } },
    ["Dark Keeper Nameplate"] = { { ids = { "o164820" }, first = "vorfalkirongourdvorfalkw", pages = { "Vorfalk Irongourd\n\nVorfalk arbeitet im Lagerraum des 'Grimmigen Säufers'. Sein Opfer für die Dunkelbewahrer ist groß.\n\nMöge sein Geist standhalten." } }, { ids = { "o164821" }, first = "bethekstormbrowbethekswa", pages = { "Bethek Stormbrow\n\nBetheks Wanderungen führen ihn tief hinein nach Blackrock. Die Geheimnisse des Berges locken ihn.\n\nMöge sein Geist niemals schwach werden." } }, { ids = { "o164822" }, first = "uggelhammerhanduggelisas", pages = { "Uggel Hammerhand\n\nUggel ist ein kunstfertiger und gewissenhafter Steinmetz. Wenn er nicht die Bürde des dunklen Schlüssels trägt, entstehen unter seinen Händen in der Halle des Handwerks wahre Meisterwerke." } }, { ids = { "o164823" }, first = "zimreldarktoothwhenthema", pages = { "Zimrel Darktooth\n\nWenn der Wahnsinn des dunklen Schlüssels über Zimrel kommt, können ihn nur die Schreie der Sterbenden besänftigen.\n\nFür sein Opfer wird er stets eine Sitzbank über der Arena haben. Möge unser blutiges Spektakel die Wut seines Herzens beschwichtigen." } }, { ids = { "o164824" }, first = "ofgutstonefistthosefalle", pages = { "Ofgut Stonefist\n\nZahllos sind jene, die Dunkelbewahrer Ofguts Hammer zum Opfer fielen.\n\nDie Soldaten der Westgarnison verneigen sich ehrfürchtig, wenn er vorübergeht. Denn wer von ihnen kann in Ofguts Augen schauen und die Geheimnisse sehen, die der dunkle Schlüssel flüstert?" } }, { ids = { "o164825" }, first = "pelverdeepstompdarkkeepe", pages = { "Pelver Deepstomp\n\nDunkelbewahrer Pelver ist unser am höchsten verehrter Jünger. Er hat den Schlüssel länger getragen als jeder andere, und das unter enormen Opfern. Wenn er zu seiner Bürde gerufen wird, so wird er im Domizil bewacht.\n\nSein Opfer wird gewürdigt und er wird viele Jahre in unseren Herzen weiterleben... nachdem die Dunkelheit ihn geholt hat." } } },
    ["Deathstalker Report"] = { { ids = { "i3252" }, first = "deathstalkermissionrepor", pages = { "Todespirschermissionsbericht\n\nAgenten: Rane Yorick, Quinn Yorick, Erland McKree\n\nPrimärmission: Aufklärung im nördlichen Silberwald und Einschätzung der Bedrohung sowohl durch Wildtiere als auch die Geißel.", "Die Agenten begannen mit der Durchsuchung und stießen auf zahlreiche Worgs. Ich empfehle Jagdtrupps zur Reduzierung der Bedrohung.\n\nUntote Gnolle wurden in der Bauernsiedlung mit Namen \"Das Todesfeld\" gesichtet. Was sie dort tun, ist unklar, aber ihre Bewegungen und ihre ständige Bereitschaft lassen auf etwas Militärisches schließen. Im Beobachtungszeitraum wurden keine bedeutenden Anführer der Gnolle gesichtet. Wir gehen daher davon aus, dass sie auf das Eintreffen ihrer Anführer oder Verstärkung warten.", "Im Zuge der Aktion wurden unsere Agenten auf Ivars Hof eingeschlossen. Ivar, der Großteil seiner Familie und Tagelöhner hatten sich der Geißel unterworfen und waren nun ihre Diener.\n\nUnsere Agenten wurden angegriffen. Zwar konnten sie sich der Attacken erwehren, aber sie erlitten dabei schwere Verletzungen, insbesondere Agent Quinn.", "Wir bezogen Verteidigungsstellung in Ivars altem Haus. Rane hielt Wache wegen möglicher weiterer Angriffe und Erland setzte die Aufklärungsmission fort.\n\nDann wurde Erland von Worgs in einem Obsthain im Norden eingekesselt und konnte nur mit Hilfe eines weiteren Agenten der Verlassenen entkommen. Diesen Agenten habt Ihr gerade vor Euch.", "An dieser Stelle soll vermerkt werden, dass der Überbringer dieses Berichts nicht nur maßgeblichen Anteil am Gelingen unserer Mission hatte, sondern auch am Sieg über Ivar den Verräter und an der Rettung Erlands sowie an der Zustellung dieses Berichts.\n\nWir erbieten unseren Dank und empfehlen, dass das Kommando der besagten Person die Belohnung angedeihen lassen möge, die solch vorbildlichem Verhalten im Einsatz angemessen ist.\n\n- Todespirscher Rane Yorick,\nMissionsleiter" } } },
    ["Decoded Tablet Transcription"] = { { ids = { "i20405" }, first = "dayourpilgrimageisoverwe", pages = { "Tag 1\nUnsere Pilgerreise ist zu Ende. Endlich haben wir Silithus erreicht, wo wir Kontakt aufnehmen sollen. Wir sind von vielerlei Orten gekommen, um bei dem monumentalen Unterfangen zusammenzuarbeiten.\n\nDie Luft knistert vor Aufregung. Morgen gilt es all unsere Energie auf den Aufbau dessen zu konzentrieren, was uns die Kommunikation mit IHNEN ermöglichen soll.\n\nMorgen wird ein Windstein errichtet werden!", "Tag 2\nDie Lage des Windsteins war Grund heftiger Diskussionen. Nicht einmal die Weisesten unter uns können mit bestimmter Sicherheit sagen, wo genau die Stelle, die in der alten Prophezeiung geannnt wurde, ist.\n\nIch verbleibe bei der ursprünglichen, nördlichen Gruppe und die Zeit wird beweisen, dass wir ohne Zweifel richtig liegen. Das Argument, das besagt, dass sich die Energielinien an dieser Stelle in einem schlechten Winkel kreuzen, ist töricht und naiv.\n\nWir tragen bereits sehr schnell die benötigten Aufbaumaterialien zusammen.", "Tag 15\nUnser Einsatz hat sich bezahlt gemacht. Wir sind das erste Lager, das einen Windstein errichtet hat. Wären die anderen Narren an unserer Seite geblieben, dann hätten wir das Ganze sogar in weniger als einer Woche bewältigt!\n\nMorgen werden wir mit den Ritualen beginnen, die zu der Beschwörung von Baron Kazum selbst gehören. Er wollte als Erster das System testen und wir konnten ihm nicht widersprechen, da er sehr schnell erzürnt.\n\nIch denke, dass er mit uns äußerst zufrieden sein wird." } } },
    ["Decoded Twilight Text"] = { { ids = { "i20541" }, first = "forimmediatedisseminationtoalltwilightshammermembersthes", pages = { "Zur umgehenden Verteilung an alle Mitglieder der Twilight-Hammer.\n\nDie Suche nach dem Verräter Ortell macht weiterhin Fortschritte und sollte in Kürze abgeschlossen sein! Unsere Späher konnten seine Spuren bis zu einem Höhlensystem in Westfall zurückverfolgen.\n\nOrtells Verrat ist unverzeihlich und seine Flucht stellt ein enormes Sicherheitsrisiko für unsere Organisation dar.\n\nIndividuen, die Informationen über Ortells Verbleib wissentlich zurückhalten, werden auf das Schärfste bestraft!\n\nLord der Twilight Everun" } }, { ids = { "i20545" }, first = "forimmediatedisseminationtoalltwilighth", pages = { "An alle Mitglieder der Twilight-Hammer.\n\nIn Anbetracht der aktuellen Situation in Silithus, sind ab sofort alle Lieferungen des 'Wahren Glaubens'  von nicht weniger als vier bewaffneten Mitgliedern der Twilight-Hammern zu eskortieren.\n\nAlle Mitglieder, die diesem Erlass nicht nachkommen, werden angemessen bestraft werden.\n\n-Lord der Twilight D'Sak" } }, { ids = { "i20552" }, first = "forimmediatedisseminationtoalltwilightshammermembersthef", pages = { "Zur umgehenden Verteilung an alle Mitglieder der Twilight-Hammer.\n\nDer nachfolgende Text beschreibt die ordnungsgemäße Benutzung eines Windsteins, zur Kontaktaufnahme mit unseren Meistern im abyssischen Rat.\n\nDie leichtfertige und unerlaubte Benutzung eines Windsteins, zieht eine harte und schmerzvolle Bestrafung nach sich!\n\n-Bewahrer der Twilight Havunth", "Abyssische Templer\n\nAls Initiat habt Ihr die Erlaubnis, für Routinerituale, mit den abyssischen Templern in Kontakt zu treten. Vergesst niemals eine angemessene Gewandung zu tragen, bevor Ihr einen Windstein aktiviert. Ansonsten besteht leicht die Gefahr, dass Ihr einen der Verteidigungszauber auslöst.\n\nFür den Fall eines unvorhergesehenen Notfalls habt Ihr die Erlaubnis, einen abyssischen Templer zu beschwören\n\nDetails zum nötigen Beschwörungsritual findet Ihr in der letzten Ausgabe des 'Wahren Glaubens'.", "Abyssische Fürsten\n\nNur Akolythen, die über ein Standesmedaillon verfügen, ist es gestattet, mit den abyssischen Fürsten in Kontakt zu treten. Ein Standesmedaillon darf nur von der Person benutzt werden, die es ursprünglich erhalten hat.\n\nMitglieder der Twilight-Hammer, die ohne eine Genehmigung mit einem abyssischen Fürsten Kontakt aufnehmen oder ohne Berechtigung ein Standesmedaillon bei sich führen, werden von mir persönlich zur Rechenschaft gezogen.", "Fürsten des hohen abyssischen Rats\n\nNur einem Lord der Twilight ist es gestattet, mit Prinz Skaldrenox, Hochmarschall Whirlaxis, Baron Kazum oder Lord Skwol Kontakt aufzunehmen.\n\nUnter keinen Umständen ist es den niederen Rängen erlaubt, den hohen Rat zu kontaktieren. Jeder Außenseiter, der es wagt, einen Windstein zu diesem Zweck zu missbrauchen, wird auf der Stelle zu Asche verbrennen." } }, { ids = { "i20676" }, first = "thestateofthecultvolumei", pages = { "Zur Lage des Kultes, Ausgabe 92\n\nFreudigen Herzens schreibe ich Euch diese Zeilen, meine Brüder und Schwestern, denn nie ging es dem Kult besser, als heute! Die Zahl unserer Anhänger wächst stetig und schon bald werden wir unser Ziele erreichen.\n\nTäglich verstärken neue Rekruten unsere Reihen. In Dunkelküste stimmen sie Lobeslieder auf unsere Meister an, in der sengenden Schlucht feiern sie das Kommende in grenzenloser Begeisterung, und in der Blackfathomtiefe lobpreisen sie den Gesandten unseres Meisters, Aku'mai. Nicht mehr lange, und unsere Anhänger werden ganz Azeroth einnehmen!" } }, { ids = { "i20677" }, first = "stateofthecultvolumeitis", pages = { "Zur Lage des Kultes, Ausgabe 127\n\nEs ist ein wahrhaft gesegneter Tag für uns! Silithus war eine Prüfung für uns und wir haben sie bestanden!\n\nDie Berichte, über die Vernichtung unseres nördlichen Lagers, werden die Herzen der Untreuen auf eine Probe stellen, jedoch sollte dieses Massaker nicht als eine Tragödie gesehen werden! Nein!", "Es ist ein Segen, dass die Mitglieder des hohen Rates unser Blut so zahlreich vergießen! Wir beneiden diese glücklichen Opfer, denn ihre Geister sind nun an einem besseren Ort, ja sie thronen in dem Magen eines rechtschaffenden Wesens! Lobet die Twilight-Hammer!" } }, { ids = { "i20678" }, first = "stateofthecultvolumeoppo", pages = { "Zur Lage des Kultes, Ausgabe 233\n\nWieder einmal hat das Schicksal uns eine Prüfung auferlegt, meine Brüder und Schwestern! Der Zirkel des Cenarius, ein Kult übler Naturliebhaber, entsendet seine Agenten gegen uns. Offensichtlich will man uns daran hindern, weiterhin rote Magiesteine zu beschwören. Dies können und werden wir nicht zulassen!!\n\nDie roten Steine sind von äußerster Wichtigkeit für unsere neuen Verbündeten. Der Zirkel des Cenarius wird mit seinem Vorhaben scheitern. Bewahrt den Glauben, meine Freunde. Bewahrt den Glauben!" } }, { ids = { "i20679" }, first = "howdoweknowtheyloveussom", pages = { "Woher wissen wir, ob sie uns lieben?\n\nEinige von uns fragen sich sicher, wie kann es sein, dass diese alten Götter und ihre Diener uns lieben? Töten sie uns denn nicht? Bringen sie uns denn nichts anderes als Schmerz und Leid? Wie können Wesen, die sich so sehr von der Macht des Bösen einnehmen lassen, so etwas wie Liebe in ihren Herzen empfinden?\n\nDoch auf diese vermeintlich schwere Frage, gibt es eine einfache Antwort. So simpel, das wir sie nicht auszusprechen brauchen!", "Glaube. Der Glaube ist der Brunnen, welcher unsere Freude am Dienen speist. Der Glaube alleine vermag uns in diesen kalten Nächten, im Schoße Silithus', zu wärmen. Am Ende aller Tage, ist es dieser Glaube, welcher uns die Gunst unseres Herrn sichern wird.\n\nDer Glaube wird uns erretten." } } },
    ["Decorated Headstone"] = { { ids = { "o175933" }, first = "inlovingmemoryofjessemor", pages = { "In liebendem Angedenken an Jesse Morales" } } },
    ["Decrypted Letter"] = { { ids = { "i3518" }, first = "greetingsmasterforgiveme", pages = { "Seid gegrüßt, Meister.\n\nVergebt mir, dass ich Euch diese Nachricht auf so ungewöhnliche Weise schicke. Meine Schattenmagier in Alterac sind so mit ihren Aufgaben beschäftigt, dass ich mich gezwungen sehe, für die Übersendung dieses Berichts einen fremden Boten einzusetzen, den wir von unseren neuen \"Verbündeten\" rekrutiert haben. Ich habe diesen Brief jedoch mit einem hochesoterischen Geheimcode verschlüsselt. Von diesen Dummköpfen kann ihn keiner lesen.", "Unsere Pläne schreiten rasch voran. Wie erwähnt sind wir eine Allianz mit einer Gruppe von Menschen eingegangen, die sich selbst das \"Syndikat\" nennen. Die Anführer dieser Gruppe stellten einst den Adel von Alterac und sind ganz erpicht darauf, ihre alte Vormachtstellung zurückzubekommen.\n\nDeshalb sind sie einen Handel mit uns eingegangen. Einen, den sie noch bereuen werden.", "Heute hat das Syndikat in diesem Landstrich nur noch wenig Macht, doch kennt es die Gegend gut und verfügt über genügend Männer für die anstehenden Aufgaben. Ich bin sicher, dass das Syndikat bei entsprechender Führung Alterac bald wieder beherrschen wird.\n\nZudem haben wir das Syndikat gedrängt, auf die Stadt Stromgarde im nahe gelegenen Arathihochland vorzurücken. Die Stadt ist das Schlachtfeld zwischen unseren Truppen, Ogern und den Menschen von Stromgarde, aber mit einer sorgfältig ausgearbeiteten Taktik dürfte diese einst große Stadt bald uns gehören.", "Sobald das erledigt ist, kann die nächste Phase unseres Plans beginnen. Mit einem eigenen Land und einem großen Stützpunkt in diesem Gebiet können wir dann die Ankunft des Dritten Wirtskörpers vorbereiten.\n\nBald schon werden die Lords der Legion uns entlohnen, indem sie wieder Feuer vom Himmel regnen lassen!", "Es war weise vom Rat, Euch zum Vorsteher der Arguswacht und mithin zum Marshal seiner Strategie im Land der Menschen und Zwerge zu machen. Es ist mir eine Ehre, die ausführende Hand Eures Willens in Alterac zu sein.\n\nIm Namen von Sargeras\n\nNagaz,\nHierophant des Argus" } } },
    ["Deepfury's Orders"] = { { ids = { "i4429" }, first = "bumblingfoolsmyplanscall", pages = { "Ihr Stümper!\n\nMeine Pläne sahen die gleichzeitige Zerstörung beider Brücken vor. Und was macht ihr einfältigen Rohlinge? Ihr macht nur halbe Sachen und alarmiert so die Allianz über unser Vorhaben! Ihr Narren!\n\nIhr habt noch eine Chance, euren Fehler wieder auszubügeln. Wir haben noch eine Ladung Sprengkörper für den Notfall im Arathihochland.\n\nWenn euch euer mickriges Leben lieb ist, macht ihr es diesmal richtig!\n\n- Kam Deepfury" } } },
    ["Defias Docket"] = { { ids = { "i5947" }, first = "ourfirstplanhasalreadyfa", pages = { "Unser erster Plan ist schon fehlgeschlagen!\n\nZwar hatte Fist zunächst Erfolg mit der Änderung des Dienstplans für die Wache der Tunnelschicht, aber wegen einiger unvorhergesehener Einmischungen seitens der Bürger Stormwinds konnte unsere Zielperson fliehen. Aber wir haben mit Derartigem gerechnet. Plan 2 wurde in Gang gesetzt und lief bereits gut, bevor unser Hinterhalt in Stormwind griff.", "Plan 2 ist genauso einfach, erfordert aber mehr Geduld unsererseits. Unser Mann in Menethil ist bereits für seine Mühen bezahlt worden. Er hat brillant reüssiert. Es sollte kein Problem sein, die Zielperson zu erreichen und gefangen zu nehmen, sobald wir Segel gesetzt haben.", "Rechnet ein paar Meilen vor ihrem Zielort mit dem Angriff. Dort werden unsere Verbündeten auf der Lauer liegen. Ich bin mir nicht im Klaren darüber, warum wir gezwungen wurden, eine Allianz mit diesen Kreaturen einzugehen, werde aber das Gefühl nicht los, dass auch wir zu etwas gezwungen werden. Aber letztlich ist es einerlei. Mit der Zielperson in unserem Gewahrsam haben wir Stormwind jenen schon so gut wie wieder abgenommen, die es uns gestohlen hatten!" } } },
    ["Defias Script"] = { { ids = { "i6846" }, first = "theplanissetinmotiontake", pages = { "Der Plan ist in Gang gesetzt.\n\nNehmt die Heldenwache, diese einst so große Glaubensbastion, als Stützpunkt und wir schicken Euch Verstärkung aus Westfall, sobald wir Kunde von Euch haben, dass alles vorbereitet ist.\n\nDie Gegend ist für die Bürger und Soldaten von Stormwind alles andere als vergessen und sollte mithin ein guter Ausgangspunkt für unsere Angriffe sein.\n\nDie Defias werden Stormwind zurückerobern!\n\nIch erwarte Eure Antwort." } } },
    ["Diary of Weavil"] = { { ids = { "i21130" }, first = "deardiarytodaymyarchenem", pages = { "Liebes Tagebuch:\n\nHeute hat mein Erzfeind, Narain Soothfancy, versucht mich zu täuschen indem er seine Spießgesellen angewiesen hat, seinen Platz bei der Hinrichtung einzunehmen. SEINER Hinrichtung. Das ist doch unglaublich!\n\nIch hatte mich so angestrengt, mir diesen teuflischen Plan auszudenken, um ihn aus dieser verdammten Hütte zu locken, und der zieht so was ab? Wie auch immer... Ich bin zu sauer, um weiterzuschreiben. Bis später.", "Liebes Tagebuch:\n\nNach meinem letzten Eintrag habe ich mein Versteck wutentbrannt verlassen. Mann, war ich sauer. Ich habe beschlossen, die Uniformen meiner Untergebenen neu zu gestalten, um meine Existenzangst besser wiederzuspiegeln. Jetzt fühle ich mich etwas besser, aber noch nicht so richtig. Bin gleich wieder da...", "Liebes Tagebuch:\n\nOkay, jetzt geht's mir wieder gut. Ich habe einen meiner Untergebenen verprügelt, bis er wie ein kleines Mädchen geheult hat.\n\nHmm… Irgendwie fühle ich mich jetzt mies. Aber Moment mal! Verdammt, ich bin ein BÖSES Genie! Böse, weißt du? Ich bin von mir selbst enttäuscht. Gleich wieder da.", "Liebes Tagebuch:\n\nIch habe ihn einmal kräftig umarmt und ihm gesagt, er soll weiterhin sein Bestes geben. Jetzt geht's mir wieder besser. Aber sag das bloß keinem weiter, Tagebuch.\n\nWo war ich? Ach ja, NARAIN! ARGH!!! Ich hasse den Kerl. Er war es schließlich, der die Durschnittsnoten für jedes einzelne Examen im Gnomeregan Institut der Tüftelei angehoben hat. Die meinten also, sie könnten mich von der Schule schmeißen, wie? Meiner Meinung nach hat Gnomeregan genau das bekommen, was es verdient hat!\n\nDas war's für heute. Schlaf schön, Tagebuch!", "Liebes Tagebuch:\n\nIch werde wohl alt. Ich hatte total vergessen, dass ich ja dabei war dir von Narain und seiner hinterlistigen Täuschung zu erzählen. Ich war so sauer, als ich einen als Narain verkleideten Lockvogel gesehen habe, dass ich Nummer Zwei angewiesen habe den Trottel zu vernichten! Ich habe mich dann in meine Flugmaschine gesetzt und mich damit beschäftigt, die Kapitel aus seinem heißgeliebten, dämlichen, aufgeblasenen Buch über Drachisch rauszureißen. Was für ein Angeber. Wen interessiert denn bitte schon Drachisch? Oooh, wie ich ihn hasse!", "Liebes Tagebuch:\n\n'tschuldigung, bin eingeschlafen. Ich bin also mit so richtig Wut im Bauch rumgeflogen und habe die einzelnen Kapitel aus diesem dämlichen Buch rausgerissen. Dann habe ich in der flüsternden Schlucht unter mir einen Dämonen gesehen und beschlossen, das erste Kapitel in einen magischen Tornado aus Papier zu verwandeln und ihn damit in Millionen kleine Stücke zu zerreißen. Das war sehr befreiend. Magie + Papier = Spaß.\n\nDas hat mir 'ne Menge Spaß gemacht, also habe ich beschlossen, zu den östlichen Königreichen zu fliegen. Zuerst habe ich dem geschmolzenen Kern einen Besuch abgestattet. Narain hat ständig von diesem Ort gefaselt! \"Geschmolzener Kern hier, Ragnaros da...\"", "Weißt du was? Wenn er so daran hängt, kann er ja versuchen in den geschmolzenen Kern zu gehen und die Kapitel seines heißgeliebten Buchs aus kleinen Aschehaufen zusammenzusetzen! Ha!\n\nWo ich einmal in der Gegend war, dachte ich mir, dass die sabernden Techniker im Labor vom guten alten Victor Nefarius vielleicht an diesem Drachischquatsch interessiert wären. Und weg damit!", "KORMOK, continued...", "Dann bin ich müde geworden, also bin ich mit meiner Flugmaschine umgedreht und in Richtung Zuhause geflogen. Allerdings habe ich auf dem Weg noch an zwei anderen Stellen angehalten. Ich habe Lord Kazzak und seinen Dämonen einen Besuch in der faulenden Narbe abgestattet (er hasst es, wenn ich das mache) und habe ein anderes Kapitel in Onyxias Kamin gesteckt.\n\nBin müde, ich geh pennen." } } },
    ["Dillinger's Report"] = { { ids = { "i286200" }, first = "scourgehavecontinuedtosl", pages = { "Der Geißel gelingt es stellenweise weiterhin, sowohl das Bollwerk als auch den östlichen Außenposten zu überwinden, und ihre Zahl wächst mit jedem neuen Tag. Es ist mir schleierhaft, wie wir ein solches Versagen unserer Verteidigung so lange dulden konnten.\n\nWie in meinen vorherigen Berichten geschildert, ist die schmähliche Anzahl an Wachen, die in Brill stationiert sind, völlig unzureichend, um der Bedrohung Herr zu werden. Die Frage ist nicht, ob wir überrannt werden, sondern wann. Und sobald Brill fällt, wird es zum perfekten Aufmarschpunkt für eine Belagerung von Undercity.\n\nIch bitte nicht darum, sondern ich verlange, dass Verstärkungstruppen von ihren gemütlichen Posten in Undercity abgezogen werden, um die Lage zu stabilisieren, solange wir noch die Möglichkeit dazu haben.\n\n--Todeswache Dillinger" } } },
    ["Divined Scroll"] = { { ids = { "i5455" }, first = "anevilforcecreatedtheseh", pages = { "Ein böser Magier hat dies erschaffen,\nUm vom Glutnebelgipfel auf dich zu gaffen,\nEr dich und deinen Freund verlacht,\nIhr müsst zerbrechen seine Macht,\n\nAllein der Tod stoppt seine Wut,\nDrum geht und löschet seine Glut!" } } },
    ["Dorgar Stoenbrow"] = { { ids = { "o175773" }, first = "dorgarstoenbrowwarriorof", pages = { "Dorgar Stoenbrow\n\nKrieger des Scharlachroten Kreuzzugs\n\nHerr der Roten Höhlen\n\nZuletzt im Alteracgebirge gesehen" } } },
    ["Ebonlocke's Response to Solomon"] = { { ids = { "i1410" }, first = "yourhonoriregrettoinform", pages = { "Euer Ehren,\n\nich muss Euch leider mitteilen, dass die Nachtwache zurzeit nicht in der Lage ist, ihren Posten in Dunkelhain zu verlassen. Vielleicht war Euch nicht bewusst, dass Stormwind uns in diesem Gebiet keinerlei militärische Unterstützung mehr zukommen lässt. Die Nachtwache wurde von den Bewohnern des Waldes einzig und allein zu dem Zweck gegründet und ausgebildet, Dunkelhain in Abwesenheit von Stormwind zu verteidigen. Ohne die Wache würde die Stadt fallen. Ich wünsche Euch alles Glück in Eurer Not.\n\n- Lord Ello Ebonlocke" } } },
    ["Eliza's Tombstone"] = { { ids = { "o37" }, first = "elizabelovedwifemaytheea", pages = { "Eliza\n\nMein geliebtes Weib, möge die Erde deinen Hunger stillen." } } },
    ["Empires' Fall"] = { { ids = { "o175855" }, first = "asidefromtheirshadowyori", pages = { "Abgesehen von ihrer nebulösen Herkunft steht jedoch fest, dass die Nachtelfen kurz nach der Entdeckung des Brunnens der Ewigkeit an die Macht gelangten. Obwohl die Trolle versuchten, sie an der Ausweitung ihrer Territorien zu hindern, errichteten die Nachtelfen ein mächtiges Reich, das sich rasch über das urzeitliche Kalimdor ausbreitete. Mit schlagkräftigen Magien, die sich die abergläubischen Trolle nie hätten träumen lassen, schafften die Nachtelfen mühelos, was den bösen Aqir versagt geblieben war: Sie führten den Untergang der beiden größten Weltreiche herbei.", "Die Nachelfen schalteten systematisch Verteidigung und Nachschubwege der Trolle aus. Da die Trolle der zerstörerischen Magie der Nachelfen nichts entgegenzusetzen hatten, erlagen sie dem Ansturm. Die Nachtelfen erwiesen sich in jeder Hinsicht als ebenso gerissen und blutrünstig wie die wilden Trolle... und zogen sich damit auf ewig deren Hass und Verachtung zu. Die Imperien der Gurubashi und Amani zerbrachen binnen weniger Jahre.", "Schließlich fielen die Nachtelfen jedoch den arkanen Feuern zum Opfer, die sie beherrschen wollten. Ihr tollkühner Einsatz der Magie hatte die Brennende Legion auf die Welt gelockt. Die Dämonen zerstörten die Zivilisation der Nachtelfen zu großen Teilen. Es gibt zwar keinerlei Aufzeichnungen, dass die Legion eine der beiden Troll-Zivilisationen angriff, wahrscheinlich ist jedoch, dass auf dem gesamten Kontinent gekämpft wurde.", "Am Ende dieses schrecklichen Konflikts - der als 'Krieg der Urtume' bezeichnet wird - implodierte der Brunnen der Ewigkeit. Die resultierende Druckwelle zerschmetterte die große Landmasse von Kalimdor. Das Zentrum des riesigen Kontinents versank im Meer, zurück blieben nur einige Bruchstücke von Kontinenten.", "Aus diesem Grund existieren noch heute große Teile der Reiche Amani und Gurubashi in Quel'Thalas und im Schlingendorntal. Die Azj'Aqir-Königreiche Azjol-Nerub und Ahn'Qiraj haben ebenfalls bis heute in Northrend und Tanaris überlebt.\n\nBeide Troll-Zivilisationen erholten sich von der ungeheuren Zerstörung, die über ihre urzeitliche Welt gekommen war. Die unermüdlichen Trolle bauten ihre verwüsteten Städte wieder auf und schickten sich an, einen Teil der einstigen Macht zurückzuerobern." } } },
    ["Encrypted Letter"] = { { ids = { "i9555" }, first = "neverbeenmoreproudtobepa", pages = { "Ich war noch nie stolzer auf mein Handwerk als in den letzten paar Jahren. Der Bedarf an Auftragsmördern, Spionen und Spähern war noch nie größer. Man würde denken, dass in Kriegszeiten ein höherer Bedarf herrschen würde, aber überraschenderweise stehen wir in Kriegszeiten nicht so gut da wie jetzt - in einer Zeit, in der der Frieden allmählich ins Wanken gerät.\n\nMir wurde gesagt, Ihr wärt in der Gegend und wolltet einige Dinge lernen. Wenn Ihr Zeit habt, sucht mich auf. Ihr findet mich bei den Ställen auf der Rückseite der Abtei.\n\n- Jorik Kerridan, Schurkenlehrer" } } },
    ["Encrypted Memorandum"] = { { ids = { "i9558" }, first = "youwereexpectingthistobe", pages = { "Ich wette, Ihr habt dies für eine normale Notiz von Eurem König oder so gehalten. Tja, sagen wir, ich kenne mich ein wenig mit dem Fälschen von Briefen aus und wollte sicherstellen, dass Ihr diesen auch wirklich erhaltet. Kann ja schlecht die Aufmerksamkeit auf mich lenken, nicht wahr?\n\nAlso habe ich mich in Anvilmar verkrochen - Ihr findet mich im Gebiet der Feuergrube. Wenn Ihr bereit seid, sucht mich auf. Ich möchte mich gern vorstellen, solange wir noch Zeit dafür haben.\n\n- Solm Hargrin, Schurkenlehrer" } } },
    ["Encrypted Parchment"] = { { ids = { "i9560" }, first = "isendgreetingsiwaslostin", pages = { "Ich grüße Euch, $N. Ich war tief in Gedanken versunken, als es mir einfiel, dass ich Euch schreiben müsste.\n\nViele in unserer Kultur preisen unsere Schamanen als spirituelle Anführer, wie unseren großen Kriegshäuptling. Andere denken, dass die Beherrschung von Schwert und Axt ein noch erhabeneres Streben sei. Aber man sollte nie vergessen, dass Schlachten - ja, ganze Kriege - mit Hilfe derer, die über speziellere Fertigkeiten verfügen, gewonnen wurden. Hierüber möchte ich mit Euch sprechen, $N. Ihr findet mich tief im Höhlenbau im Tal der Prüfungen.\n\n- Rwag, Schurkenlehrer" } } },
    ["Encrypted Rune"] = { { ids = { "i9550" }, first = "brothersisterihopethisru", pages = { "$gBruder:Schwester;, ich hoffe, diese Rune erreicht Euch bei guter Gesundheit. Ich wollte Euch nur kurz wissen lassen, dass Ihr mich in Anvilmar über dem Coldridgetal findet. Ich weiß, wie wichtig es ist, dass wir alle zusammenhalten. In diesen Zeiten des bedrohten Friedens wird es immer wichtiger, von Unseresgleichen umgeben zu sein. Sucht mich auf, wenn Ihr die Zeit findet.\n\n- Solm Hargrin, Schurkenlehrer" } } },
    ["Encrypted Scroll"] = { { ids = { "i9559" }, first = "takecarenottoignoremywor", pages = { "Vergesst meine Worte nicht, $N. Dies ist die Zeit der Unterdrückung und Täuschung... selbst in unserer großartigen Undercity. Jeder, der loyal zu Sylvanas steht, arbeitet an der Schaffung einer neuen, von den Verlassenen bestimmten, Ära. Und obgleich wir über keine magischen Fertigkeiten verfügen und keine Waffen an unseren Grenzen postieren, haben wir unsere eigene Rolle in diesem Spiel.\n\nSucht mich im Gasthaus von Deathknell auf. Dort werden wir weiterreden.\n\n- David Trias, Schurkenlehrer" } } },
    ["Encrypted Sigil"] = { { ids = { "i9551" }, first = "saelahmyfriendihopethiss", pages = { "Sael'ah. Ich hoffe, dieses Siegelzeichen erreicht Euch bei guter Gesundheit. Ich wurde gebeten, Euch meine Dienste anzubieten. Auch ich befinde mich in Shadowglen, in dem großen Baum von Aldrassil, und wollte Euch wissen lassen, dass Ihr, wenn Ihr irgendeine Ausbildung braucht, jederzeit zu mir kommen könnt.\n\nIn diesen unsicheren Zeiten halte ich es für klug, dass sich alle, die sich der Verstohlenheit bedienen, noch enger zusammenschließen. Wie sollten wir sonst Teldrassil und unsere Art des Lebens beschützen können?\n\nSucht mich auf, wenn Ihr könnt.\n\n- Frahun Shadewhisper, Schurkenlehrerin" } } },
    ["Encrypted Tablet"] = { { ids = { "i9554" }, first = "greetingsbrothersisterth", pages = { "Seid gegrüßt, $gBruder:Schwester;. Die Shattered-Hand sendet Grüße und hofft, dass das Tal ein geeigneter Ort für die Ausübung Eures Handwerks sein wird. Dies ist eine Zeit der Prüfung für Euch, denkt also nicht, dass Ihr nicht ständig überwacht würdet.\n\nEs ist meine Pflicht, für die Hand Eure Fertigkeiten zu bewerten und sie darüber zu informieren, wenn Ihr für größere Herausforderungen bereit seid.\n\nWenn Ihr so weit seid, findet Ihr mich tief im Höhlenbau. Ich werde Euch dort erwarten.\n\n- Rwag, Schurkenlehrer" } } },
    ["Etched Note"] = { { ids = { "o174746" }, first = "thisanvilisthepropertyof", pages = { "Dieser Amboss ist Eigentum von Jordan Stilwell. Bitte NICHT benutzen!\n\n- Jordan" } }, { ids = { "i9565" }, first = "mightywarriorsdefendourh", pages = { "Mächtige Krieger verteidigen unser Zuhause. Unsere Schamanen führen unsere Geister und zeigen uns die Vergangenheit unserer Vorfahren. Und unsere Druiden helfen uns, den Willen der Erdenmutter zu verstehen.\n\nIhr jedoch seid einer unserer Jäger, und unsere Jäger lernen viele Aspekte dieser verschiedenen Rollen kennen und vereinen sie in einer Person. Ihr werdet feststellen, dass Ihr das Herz unseres Volkes repräsentiert. Einige unseres Stammes werden Euch um Führung bitten, einige um Schutz ersuchen. Es ist meine Pflicht sicherzustellen, dass Ihr dafür bereit seid. Sucht mich im Camp Narache auf.\n\n- Lanka Farshot, Jägerlehrer" } } },
    ["Etched Parchment"] = { { ids = { "i9553" }, first = "yabeingoodhandsnowmonjen", pages = { "Ihr sein in guten Händen jetzt, Mann. Jen'shan wissen, dass Ihr die Fertigkeiten des Jägers lernen wollen, und sie sein bereit, Euch zu lehren... wenn Ihr sein bereit, zuzuhören.\n\nIhr mich kommen suchen in Tal der Prüfungen. Jen'shan beginnen mit Eurer Unterweisung und zeigen Euch, wie mächtig die Fertigkeiten des Jägers sein.\n\n- Jen'shan, Jägerlehrerin" } } },
    ["Etched Rune"] = { { ids = { "i9566" }, first = "tamerofbeastsmastermarsk", pages = { "Zähmer der Wildtiere, meisterlicher Schütze, erprobter Fährtenleser... was wollt Ihr sonst noch in diesem Leben erreichen? Für all dies zusammen muss man äußerst intelligent und sehr geduldig sein.\n\nDer Weg des Jägers ist kein einfacher, so viel ist sicher. Ihr benötigt viel Übung, um auch nur so gut zu werden wie unser Scharfschütze im niedersten Rang. Aber dafür bin ich ja da.\n\nIhr findet mich in Anvilmar über dem Coldridgetal. Ich werde Euch erwarten.\n\n- Thorgas Grimson, Jägerlehrer" } } },
    ["Etched Sigil"] = { { ids = { "i9567" }, first = "eluneiswithyouthewindwhi", pages = { "Elune ist mit Euch, $N. Der Wind flüstert es mir zu und ich bin erfreut, dass ich bald Anteil daran habe, unsere kommende Generation von Jägern zu formen.\n\nWie mir erzählt wurde, seid Ihr Aldrassil sehr verbunden. Wir treffen uns im Inneren des großen Baumes, wenn Ihr Zeit dafür habt.\n\nUnsere Ältesten haben mich mit der Aufgabe betraut, die neuen Jäger auf die kommenden Prüfungen korrekt vorzubereiten. Da Ihr zu den neuesten Schülern zählt, wäre es angebracht, mich aufzusuchen. Bis dahin, gehabt Euch wohl.\n\n- Ayanna Everstride, Jägerlehrerin" } } },
    ["Etched Tablet"] = { { ids = { "i9564" }, first = "itbegoodtohearthatoneofj", pages = { "Es sein gut zu hören, dass $gein Bruder:eine Schwester; von Jen'shan in das Tal kommen, um $gseine:ihre; Fertigkeiten zu erproben. Jen'shan freuen sich darauf!\n\nIch Euch nicht sagen müssen, welch starker und schlauer Jäger Ihr sein - Ihr das bereits wissen. Es sein Jen'shans Aufgabe, Euch zu lehren, wie stärker und noch schlauer werden.\n\nIhr finden Jen'shan im Tal der Prüfungen. Sie Euch gut lehren. Sie Euch auch lehren, wie großes Wildtier zähmen.\n\n- Jen'shan, Jägerlehrerin" } } },
    ["Exile of the High Elves"] = { { ids = { "o175731" }, first = "asthecenturiespassedthen", pages = { "Im Lauf der Jahrhunderte erlebte die Gesellschaft der Nachtelfen eine Blüte und expandierte über den gesamten neuen Wald, den sie Ashenvale nannten. Viele der Geschöpfe, die es vor der großen Teilung im Übermaß gegeben hatte, wie zum Beispiel Furbolgs und Stacheleber, tauchten wieder auf und breiteten sich im Land aus. Unter der gütigen Führerschaft der Druiden genossen die Nachtelfen eine Ära des beispiellosen Friedens und der Ruhe unter den Sternen.", "Doch viele der ursprünglichen Hochgeborenen wurden unruhig. Genau wie Illidan vor ihnen, verspürten sie Entzugserscheinungen nach dem Verlust ihrer geliebten Magie. Sie waren versucht, die Energien des Brunnens der Ewigkeit anzuzapfen und ihren magischen Ritualen nachzugehen. Dath'Remar, der dreiste Anführer der Hochgeborenen, verspottete die Druiden in aller Öffentlichkeit und nannte sie Feiglinge, weil sie die Magie nicht nutzten, die ihnen rechtmäßig zustünde.", "Malfurion und die Druiden ließen Dath'Remars Argumente unbeachtet und warnten die Hochgeborenen, dass jegliche Anwendung von Magie mit der Todesstrafe geahndet werden würde. In ihrer Unbelehrbarkeit riskierten Dath'Remar und seine Anhänger einen vergeblichen Versuch, die Druiden zur Rücknahme ihres Gesetzes zu veranlassen, und entfesselten einen schrecklichen magischen Sturm über Ashenvale.", "Die Druiden brachten es jedoch nicht fertig, so viele ihrer Art zu töten, daher beschlossen sie, die unverbesserlichen Hochgeborenen aus ihrem Land zu verbannen. Dath'Remar und seine Anhänger waren froh, dass sie ihren konservativen Vettern den Rücken kehren konnten, gingen an Bord einiger eigens angefertigter Schiffe und stachen in See. Keiner von ihnen wusste, was sie jenseits der Gewässer des tosenden Mahlstroms erwarten würde, doch sie brannten darauf, eine neue Heimat zu finden, wo sie ihre geliebte Magie ungehindert ausüben konnten.", "Die Hochgeborenen oder \"Quel'dorei\", wie Azshara sie früher einst genannt hatte, landeten schließlich an der Küste des östlichen Landes, das die Menschen Lordaeron nennen sollten. Sie hatten vor, ein eigenes magisches Königreich zu gründen, Quel'Thalas, und der nächtlichen Lebensweise und Mondanbetung der Nachtelfen abzuschwören. Von nun an wollten sie sich der Sonne zuwenden und nur noch \"Hochelfen\" genannt werden." } } },
    ["Extended Annals of Darrowshire"] = { { ids = { "i13202" }, first = "theannalsofdarrowshireda", pages = { "Die Annalen von Darrowshire\n\nDarrowshire, benannt nach dem Darrowmeresee im Westen, ist ein Dorf, das sich in das südliche Vorgebirge Lordaerons schmiegt. Bekannt für seine bescheidenden, aber hart arbeitenden Bewohner, führte Darrowshire ein Schattendasein in der Geschichte Lordaerons, bis der Zweite Krieg ausbrach.\n\nIn diesem Krieg wurden Helden geboren. Und viele Helden ließen ihr Leben.", "Die Schlacht um Darrowshire\n\nDie Schlacht um Darrowshire ereignete sich in der Mitte des Zweiten Krieges, als Streitkräfte der Geißel durch Lordaeron tobten. Darrowshire wurde von der Hauptstreitmacht der Allianz abgeschnitten. Doch eine Kompanie Soldaten, ein Kontingent Paladine der Silberhand und eine standhafte Gruppe hiesiger Milizen unter ihrem Anführer Captain Joseph Redpath hielt in der Stadt stand.", "Die ersten Angriffe der Geißel auf Darrowshire waren eher harmlos. Kleine Gruppen plündernder Skelette und Kadaver durchstreiften die Außenbezirke des Dorfs und wurden mit Leichtigkeit besiegt.\n\nDie Geißel spürte die Hartnäckigkeit der Verteidiger und zahlte mit gleicher Münze zurück. Schon bald nach der ersten Welle von Angriffen, kündigte sich eine zweite an. Ghulchampions, Gefolgsleute des Ghullords Horgus, strömten mit wildem Geschrei von den Bergen herab und überrannten die belagerten Verteidiger Darrowshires.", "Die Verteidiger waren geschwächt, wurden jedoch durch Paladine abgelöst, Jünger der Silberhand. Ihr Anführer David Crokford stammte aus Darrowshire. Er brachte seine Anhänger ins Dorf, als er von dem bevorstehenden Angriff erfuhr, und zusammen mit den Verteidigern gelang es ihnen, die Diener von Horgus aufzuhalten.\n\nAls Horgus sich höchstpersönlich in die Schlacht stürzte, traf er auf Davil. Viele Minuten lang kämpften sie, und Davil ging am Ende siegreich hervor, erlitt jedoch eine tödliche Verletzung und starb kurz, nachdem er den Ghullord besiegt hatte.", "Die Schlacht ging weiter und Captain Redpath führte seine Milizen mutig an. Der Kampf wäre vielleicht sogar gewonnen worden, wäre der Captain nicht durch den Todesritter Marduk der Schwarze verderbt worden.\n\nMitten im Getümmel ritt Marduk auf Redpath zu, entriss ihm durch schwarze Magie seinen Geist und verwandelte ihn in einen bösen Schatten des tapferen Captains.", "Durch den verderbten Captain Redpath breitete sich danach dessen bösartige Besudelung unter den Verteidigern Darrowshires aus, die prompt ihre Verbündeten verrieten und ermordeten. Dann wandten sie sich der Stadt Darrowshire zu und töteten alle, die sich in ihren Häusern versteckten.\n\nDie verbliebene Armee der Geißel sowie der verderbte Geist Captain Redpaths verließen danach das verheerte Dorf Darrowshire und drangen nach Lordaeron vor, um im Zweiten Krieg noch mehr Schmerz und Tod zu verbreiten.", "Das Schicksal von Horgus dem Verheerer\n\nHorgus der Verheerer fiel in der Schlacht um Darrowshire. Aber das Böse in ihm war noch nicht versiegt. Die siegreichen Streitkräfte der Geißel bargen seinen Schädel vom Schlachtfeld bei Darrowshire und nahmen ihn mit sich, um alles Leben, dem sie begegneten, in Angst und Schrecken zu versetzen.\n\nTage später wurde die Kompanie der Geißel, in deren Händen sich der Kopf befand, von den Paladinen der Silberhand besiegt. Horgus' Kopf wurde im Blackwoodsee versenkt.", "Das Schicksal von Marduk dem Schwarzen\n\nMarduk überlebte den Zweiten Krieg und sorgte durch sein elendes, runenübersätes Schwert für Tod und Leid. Marduk lebt zwar heute noch, sein Schwert jedoch ging während einer Schlacht in der Nähe von Corins Kreuzung verloren. Ein Zwergen-Captain zerschmetterte das Schwert auf seinem verzauberten Schild und vertrieb Marduk vom Schlachtfeld, womit er den Kampf zu Gunsten der Allianz entschied.\n\nMarduks Schwert versank in der Erde und verderbte sie. Es fraß eine Schlucht in das Land, die heute als die 'Infektnarbe' bekannt ist.", "Das Schicksal von Davil Lightforge\n\nDavil Lightforge starb in der Schlacht um Darrowshire, doch sein Mut gereichte der Allianz während des gesamten Krieges zum Vorbild.\n\nSein Buch, genauer gesagt Paladinbuchband, wurde später von Truppen des scharlachroten Kreuzzugs wiedergefunden. Es befindet sich jetzt im Rathaus im vom scharlachroten Kreuzzug kontrollierten Hearthglen, wo es eifrig von Kreuzzüglern studiert wird, die von Davils Kraft profitieren wollen.", "Das Schicksal von Joseph Redpath\n\nJoseph Redpath wurde während der Schlacht um Darrowshire getötet. Sein Geist wurde verderbt und nahm eine neue Gestalt an. Diese neue Kreatur brachte großes Übel über Lordaeron.\n\nAuf Gahrrons Trauerfeld, östlich von Andorhal, wurde der verderbte Redpath schließlich durch Streitkräfte der Allianz besiegt. Sein Schild liegt noch immer in der Nähe der Scheune des verseuchten Bauernhofs und Diener der Geißel werden noch immer von diesem Andenken an seine Bösartigkeit angezogen.", "Das Schicksal von Carlin Redpath\n\nCarlin, der Bruder Captain Joseph Redpaths, gehört zu den Opfern der Schlacht um Darrowshire. Doch obwohl er schreckliche Wunden davongetragen hatte, starb er nicht.\n\nTage nach der Schlacht griffen ihn Agenten der Argentumdämmerung auf, als er, geschwächt von Durst und Fieber, in der Nähe von Corins Kreuzung umherirrte. Sie pflegten seine Wunden und brachten ihn zur Kapelle des hoffnungsvollen Lichts.\n\nDankbar für ihre Barmherzigkeit schloss sich Carlin den Reihen der Argentumdämmerung an und führt jetzt einen Rachefeldzug gegen die Geißel." } } },
    ["Faded Photograph"] = { { ids = { "i11108" }, first = "", pages = { "" } } },
    ["Fel Tracker Owner's Manual"] = { { ids = { "i10832" }, first = "theconjuringofthebeastto", pages = { "Die Herbeizauberung der Bestie:\n\nUm den Teufelshundfährtenleser herbeizuzaubern, müsst Ihr die mitgelieferte Teufelskugel benutzen.\n\nHinweise:\n\nDer herbeigezauberte Teufelshundfährtenleser bleibt als Wesenheit nur dreißig Minuten in dieser Welt erhalten.\n\nDer herbeigezauberte Teufelshundfährtenleser hilft Euch nur, Azsharit-Formationen zu finden.\n\nDer herbeigezauberte Teufelshundfährtenleser macht Folgendes NICHT: Kunststückchen, etwas angreifen, bei etwas mithelfen, tanzen, arkane Wesen vernichten.\n\n...", "Die Kontrolle der Bestie:\n\nTeufelshund-Fährtenleser reagieren nur auf bestialisches Gebrüll. Damit Euer Teufelshund-Fährtenleser Azsharit-Formationen aufspürt, müsst Ihr ihn mit aller Macht anbrüllen! (Visiert den Teufelshund-Fährtenleser an und /roar.)\n\nWenn der Teufelshund-Fährtenleser eine Formation entdeckt, sprintet er ohne Rücksicht auf die Wesenheiten um ihn herum dorthin. Es ist zwar nicht nötig, dass Ihr den Teufelshund beschützt, Ihr solltet aber in seiner Nähe bleiben, damit Ihr ihn nicht verliert.", "Die Entsorgung der Bestie:\n\nNach dreißig Minuten kehrt die Bestie in ihre Heimat ins Nether zurück.\n\nAchtung:\n\nIn ihrem Eifer KANN die Bestie von Klippen oder Berggipfeln abstürzen. Trauert nicht um den verlorenen Teufelshund-Fährtenleser, sondern beschwört stattdessen einen neuen herbei." } } },
    ["Fellari Swiftarrow"] = { { ids = { "o175774" }, first = "fellariswiftarrowrangerc", pages = { "Fellari Swiftarrow\nWaldläuferhauptmann des Scharlachroten Kreuzzugs\nBürgerin von Quel'Thalas\nVerschollen in den Wäldern des Silberwalds" } } },
    ["Ferren Marcus"] = { { ids = { "o175775" }, first = "ferrenmarcushighabbotoft", pages = { "Ferren Marcus\n\nHochabt des Scharlachroten Klosters\n\nBürger von Stratholme\n\nGefallen bei der Verteidigung des Scharlachroten Klosters beim ersten Sommerangriff" } } },
    ["Field Guide"] = { { ids = { "i213563" }, first = "arbortarantulaorderarane", pages = { "Laubengangtarantel\n\nGattung: Araneae\nKlima: Tropisch\n\nBaut Nester in totem und verrottendem Holz. Häufig in der Nähe von Baumfällaktivitäten zu finden, da die Tarantel sich gerne in frisch gefällten Baumstümpfen eingräbt.", "Fleischpflücker\n\nGattung: Scorpiones\nKlima: Arid\n\nWie der Name schon andeutet, pflückt und frisst dieser Skorpid das Fleisch von den Knochen anderer Tiere. Er ist ein Aasfresser und zieht es vor, sich an größeren Kadavern zu laben.", "Heurüsselkäfer\n\nGattung: Coleoptera\nClimate: Gemäßigt\n\nEine riesige Landplage in einem winzigen Panzer. Ein einziger Rüsselkäfer kann sich in weniger als einer Stunde durch einen Ballen Heu fressen. Befall ist recht selten, doch gibt es häufiger Berichte aus den nördlichen Teilen der Östlichen Königreiche." } } },
    ["Final Clue to Sander's Treasure"] = { { ids = { "i1362" }, first = "nowthatyefoundmeolwhiske", pages = { "Jetz', wo Ihr mein' alten Whiskykrug gefunden habt, habt Ihr den Schatz schon so gut wie in der Tasche. Von der Flasche aus müsst Ihr Euch einfach nach Westen halten und runter zum Strand geh'n. Und dann heißt es schwimmen! Schwimmt schnurstracks nach Westen, bis Ihr an der Insel seid, da wo meine Schatztruhe drauf is'!" } } },
    ["Fishing Tournament!"] = { { ids = { "i19978" }, first = "stranglethornfishingtour", pages = { "Angelwettbewerb im Schlingendorntal!\nSonntag Nachmittag, von 14 bis 16 Uhr.\n\nKommt zur Küste des Schlingendorntals (ausgenommen Booty Bay) und haltet Ausschau nach den Schwärmen von Leckerfischen, die in den Gewässern auftauchen werden! Sorgt dafür, dass Euer Schwimmer in dem Fischschwarm landet und Ihr werdet als Belohnung besondere Fischarten, anstelle des üblichen Bestandes des Schlingendorntals fangen. Der Erste, der vierzig Leckerfische gefangen hat, sollte sich schnellstens nach Booty Bay begeben, um sie Fischereimeister Bassbait zu geben und den Preis zu erhalten!\n\nAuch wenn Ihr nicht der schnellste sein solltet, werdet Ihr sicherlich dennoch ein paar Goldstücke für Eure Fische bekommen. Darüber hinaus gibt es noch die besonderen Fische, auf die Ihr ein Augenmerk legen solltet, denn diese werden Euch auch besondere Preise einbringen!" } } },
    ["Fizzle Brassbolts' Letter"] = { { ids = { "i5827" }, first = "goodmartekiminajamandine", pages = { "Mein guter Martek,\n\nich bin in der Bredouille und brauche Eure Hilfe.\n\nMein Bruder und ich bauen einen Rennwagen und benötigen starke Kolben. Die bislang verwendeten Kolben waren nicht gut genug. Sie verkraften einfach nicht das Tempo unseres neuen Wagens, so dass uns regelmäßig der Motor um die Ohren fliegt!\n\nIhr seid Fachmann für Metallverarbeitung. Ihr müsst uns helfen. Ihr seid der Einzige, der etwas für uns tun kann.", "Hier sind die Maße für den Kolben:\n\nLänge: 32 BHB\nBreite: 12 BHB\nGewicht: 23,5 KKG bis 25,5 KKG\nZündung: 70 ZL\nSchubkraft: Mindestens 98\nVerdichtungsrate: Super-Derb oder höher\n\nFalls Euch Gnomenmaße nicht mehr geläufig sind:\nBHB = Barthaaresbreite\nKKG = Klitzekleine Gramm\nZL = Zehenlocken" } } },
    ["Fizzlefuse's Shopping List"] = { { ids = { "i239246" }, first = "dearfuturemedontforgetth", pages = { "Liebes zukünftiges Ich, vergiss dieses Mal bitte nicht das Brot.\n\n- 2 Gallonen eiskalte Milch\n- 20 Stücke feiner alter Cheddar (die Ratten essen alles auf)\n- 1 köstlicher Schokoladenkuchen\n- Machen wir lieber 2 Kuchen draus\n- 4 gefährliche Einheiten Goblinraketentreibstoff\n- 2 Thoriumröhren\n- 1 Echtsilberumwandler\n- <die Schrift ist bis zur Unkenntlichkeit verschmiert>\n- 2 Gyrochronatome" } } },
    ["Folded Parchment"] = { { ids = { "i282420" }, first = "greetingssincetheelement", pages = { "Seid gegrüßt, $N!\n\nSeit die elementaren Windgeister verschwunden sind, steht Zephras vor einem tödlichen Abgrund. Die Vögel, die Wildtiere und sogar die Wurzeln unter unseren Füßen bitten uns um Hilfe.\n\nSucht mich im ersten Stock des großen Baums hier in Thendal auf. Ich werde Euch beraten und in den Druidenkünsten ausbilden.\n\n- Xyton Silverwind, Druidenlehrer" } } },
    ["Fool's Stout Report"] = { { ids = { "i5807" }, first = "mrfizzlebubthebeverageyo", pages = { "Mr. Fizzlebub,\n\ndas Getränk, das Ihr meinem Mitarbeiter gegeben habt, war ein voller Erfolg. Es ist nicht nur stark und benebelt die Sinne, es scheint auch süchtig zu machen. Wer einmal davon gekostet hat, will sicher immer mehr.\n\nWir stehen in Eurer Schuld, Crank.\n\nHiermit seid Ihr herzlich eingeladen, auf die schimmernde Ebenen zu kommen oder einen Vertrauten zu schicken, damit auch Ihr etwas von den neuen Glücksspielgelegenheiten an diesem Ort habt.\n\n- Kravel" } } },
    ["For the Light!"] = { { ids = { "i20009" }, first = "hisnamebroughtlighttodar", pages = { "Sein Name brachte Licht ins dunkelste Azeroth.\n\nSein Mut riss die Mauern des Elends ein.\n\nDie Silberhand hat niemals besser daran getan\n\nals der Welt den Ritter zu geben, der sich selbst aufopfern würde.", "Sein Ruhm war nicht der, den er erwünschte,\n\nauch nicht die Herrschaft über sein Volk wollte er.\n\nStattdessen wählte er für Lordaeron zu kämpfen\n\nhoffend das sein Volk es nie wieder müsste.", "Die tragische Geschichte dieses so heiligen Ritters\n\nwird niemals mit seinem gottlosen Tod enden.\n\nWir verehren ihn und danken ihm!\n\nUther wird für immer Ruhm und Licht erfahren!" } } },
    ["Foreboding Plans"] = { { ids = { "i3718" }, first = "theywouldhavelifeeternal", pages = { "L. F. hat mehr Aggression gegen die Narren der Allianz angeordnet. Es folgt eine Liste mit Materialien, die für eine wichtige Mission gegen Southshore benötigt werden:\n\nReiserationen für 20 Männer und 1 Woche\n20 schwarze Nachtanzüge\n20 Paar neue Schuhe\n25 neue Schwerter\n30 Wurfmesser\n20 schwarze Masken\n10 Phiolen mit brennbarem Öl\n50 Dosen lähmendes Gift\nWenn möglich 5 gestohlene Uniformen der Wachen von Southshore\n100 Silbermünzen\n\n- Baron V.\nRüstmeister" } } },
    ["Forestlord and the first Druids"] = { { ids = { "o177205" }, first = "intimethechildcenariusgr", pages = { "Mit der Zeit wuchs Cenarius heran und seine Statur war so stattlich wie die seines stolzen Vaters. Der große Jäger war den Bäumen und auch den Sternen wie ein Bruder, er streifte durch die weite Welt und sang die harmonischen Lieder der Dämmerung. Alle Kreaturen verneigten sich vor seiner Anmut und Schönheit - niemand war so klug wie der Sohn des Mondes und des weißen Hirschs.", "Irgendwann freundete sich Cenarius mit den Shu'halo an und erzählte ihnen von der Welt, die sich drehte. Die Kinder der Erde erkannten ihn als Bruder und schworen, ihm dabei zu helfen, die Felder des Lebens zu bestellen und für die Lieblingskreaturen ihrer großen Erdenmutter zu sorgen.", "Cenarius brachte den Kindern der Erde die Sprache der Bäume und Pflanzen bei. Die Shu'halo wurden zu Druiden und vollbrachten große magische Taten, um das Land wieder gesund zu pflegen. Über viele Generationen jagten die Shu'halo an Cenarius' Seite und beschützten die Welt vor den Schatten, die sich unter ihnen regten." } } },
    ["Fossilized Egg"] = { { ids = { "o175680" }, first = "foundintheswelteringwast", pages = { "Dieses in der Gluthitze der Tanariswüste gefundene Ei gibt den modernen Ökologen bis auf den heutigen Tag Rätsel auf. Die Datierung ergab, dass das Ei bis zu tausend Jahre alt sein könnte. Gewisse Elemente weisen auf eine insektoide Struktur hin, doch seine wahre Herkunft bleibt ungeklärt. Die Spezies, die so unverwechselbare Eier legt, wurde noch nicht gefunden." } } },
    ["From the Desk of Lord Victor Nefarius"] = { { ids = { "i21142" }, first = "towhomitmayconcernhowilo", pages = { "An alle, die es angeht,\n\nwie sehr ich diese Spielchen liebe, die wir spielen.\n\nWenn Ihr diesen Brief lest, kann ich nur annehmen, dass es Euch irgendwie, durch ein Wunder oder göttliches Eingreifen, gelungen ist, mich zu bezwingen. Absurd, ich weiß, aber in der Geschichte dieser Welt sind schon seltsamere Dinge geschehen.", "Wie alles im Leben hat auch diese traurige Geschichte einen herrlichen Silberstreif aus Tragödie, Chaos und Bosheit. Ihr habt mich zwar getötet, doch so langsam und ungeordnet, dass mir Zeit genug blieb, diesen Brief zu schreiben, NACHDEM ich Eure einzige Hoffnung zerstört hatte, diese Welt zu retten. Das zerstoßene rote Kristallpulver ist alles, was von Eurem Szeptersplitter übrig ist.", "Erfreut Euch an den Rüstungen der Nemesis und des Stormrage, die Ihr in meiner Schatzkammer finden mögt. Glaubt mir, wenn ich Euch sage: Es bereitet mir großes Vergnügen zu wissen, dass ich vollbracht habe, was meinem Vater nicht gelang...\n\nHochachtungsvoll,\n\nLord Victor Nefarius\n\"Nefarian\"" } } },
    ["Furen's Instructions"] = { { ids = { "i6842" }, first = "inthefollowingpagesyoull", pages = { "Auf den folgenden Seiten findet Ihr eine Liste der Materialien, die Ihr für eine feuergehärtete Rüstung benötigt. Viel Glück, Krieger.\n\n- Furen Longbeard", "Versengte Spinnenfangzähne:\n\nDas Pyrophorerz aus den Höhlen in der Nähe des Thelgenfelsens hat die dort lebenden Spinnen versengt.\n\nDas Gift in ihren Fangzähnen kocht und reagiert mit den Fangzähnen und produziert dadurch eine sehr harte Substanz.", "Verkohlte Hörner:\n\nEbenso wie die versengten Spinnenfangzähne haben auch die verkohlten Hörner der im Verbrannten Tal lebenden Schimären aus dem Steinkrallengebirge auf Kalimdor wertvolle Eigenschaften.\n\nFlachgeklopft und in geeigneter Weise behandelt werden sie gegen mechanische Belastungen äußerst robust.", "Galvanisiertes Horn:\n\nDas galvanisierte Horn gibt der gesamten Rüstung, die ich für Euch machen werde, erst ihre Härte. Daher brauchen wir das Horn unbedingt.\n\nIhr bekommt es von der seltenen Schimärenmatriarchin im verbrannten Tal.", "Phiole mit Phlogiston:\n\nIn der letzten Phase brauche ich zur Herstellung der Rüstung eine äußerst heiße Schmiede. Damit die Schmiede heiß genug wird, brauche ich wiederum eine Phiole mit Phlogiston.\n\nDer einzige bekannte Hersteller dieser Substanz ist der berühmte Stacheleber Roogug, und der wird sie nicht kampflos hergeben. Roogug lebt zurückgezogen im Kral von Razorfen im südlichen Brachland." } } },
    ["Furlbrow's Deed"] = { { ids = { "i1971" }, first = "thisisadeedtoanexpanseof", pages = { "Dies ist eine Besitzurkunde für ein Stück Land im Gebiet von Westfall. Mit ihr werden unten stehenden Personen die Eigentumsrechte an dem genannten Gebiet sowie an allen innerhalb der Grundstücksgrenzen hergestellten Gütern und errichteten Gebäuden übertragen.\n\nDas Dokument wurde unterzeichnet von:\n\n    Theodore Furlbrow\n    Verna Furlbrow", "[Die folgenden Worte wurden hastig auf die Rückseite der Besitzurkunde gekritzelt]\n\nWir haben Furlbrow etwas bearbeitet und ihm seine Besitzurkunde abgeluchst. Wäre vielleicht ganz nützlich, wenn Ihr Euch auch so eine fälschen wolltet. Um die Furlbrows müssen wir uns jedenfalls keine Sorgen machen. Zuletzt sah ich sie kurz hinter Westfall in einem Wagen mit gebrochener Achse." } } },
    ["General Turalyon"] = { { ids = { "o25330" }, first = "generalturalyonformerlie", pages = { "General Turalyon\n\nEhemaliger Lieutenant von Lord Anduin Lothar. Ritter der Silberhand, Hochgeneral in der Expedition der Allianz, die in Draenor, der Heimat der Orcs, einmarschiert ist. Vermutlich gefallen.\n\nEsarus thar no'Darador' - durch Blut und Ehre dienen wir.\nDu warst die rechte Hand von Gerechtigkeit und Tugend, alter Freund. Dein Name wird in unseren Hallen auf ewig verehrt werden.\n\n- Lord Uther Lightbringer - Ritter der Silbernen Hand" } } },
    ["Geru Strider"] = { { ids = { "o175682" }, first = "thelargestoftheplainstri", pages = { "Die Geru sind die größten aller Ebenenschreiter. Es gibt nur wenige von ihnen, und man begegnet ihnen selten." } } },
    ["Glowing Recall Crystal"] = { { ids = { "i282416" }, first = "thehighorderhasbeenwatch", pages = { "<As you touch the glowing crystal a draft of wind stirs around you, carrying the faint hint of spoken words.>\n\nThe High Order has been watching you, $N, and we see great promise in your abilities.\n\nThe Wind Spirits have left Zephras Isle, and now more than ever, promising mages like yourself are needed. If our people are to find the self-reliance to survive this crisis, we must use our knowledge of the arcane to uncover the secrets of this realm.\n\nSeek me out in Thendal Village, on the ground floor of the great tree. We will begin your training in earnest.\n\n-Dorii Brightwhisper, Mage Trainer" } } },
    ["Glyphic Letter"] = { { ids = { "i9571" }, first = "therearefourrulestomagic", pages = { "Es gibt vier Regeln für die Magie:\n\n   Magie ist mächtig.\n   Magie führt zu Verderbtheit.\n   Magie macht süchtig.\n   Die Magie derjenigen, die arkane Zauber wirken, zieht die Bewohner des wirbelnden Nethers an.\n\nDiese Regeln gelten immer. Diese Regeln bestimmen Euer Schicksal, wenn Ihr weiterhin auf dem Weg des Magiers voranschreitet.\n\nSeid Ihr jedoch närrisch genug, diese Warnung zu ignorieren, sucht mich im Bibliotheksflügel der Abtei von Nordhain auf. Ich warte oben auf Euch.\n\n-Kheldon Bremen, Magielehrer" } } },
    ["Glyphic Memorandum"] = { { ids = { "i9573" }, first = "tonewstudentsofthearcane", pages = { "An die neuen Studenten der arkanen Künste:\nIhr werdet den Gnom Marryk Nurribit aufsuchen und unter ihm studieren, bis die Zeit gekommen ist und Ihr gerufen werdet, um Eurem Volk in einem neuen Gebiet beim Wiederaufbau zu helfen. Bereitet Euch voller Mut auf harte Prüfungen und einen schwierigen Akklimationsverlauf vor, während Ihr eine Behausung und/oder eine Form von Miteinander unter den lokalen Bewohnern sucht.\n\nFragen zu Euren Pflichten und Fähigkeiten sind direkt an Marryk Nurribit zu richten." } } },
    ["Glyphic Parchment"] = { { ids = { "i282380" }, first = "youseewhatotherorcscanno", pages = { "Ihr sehen, was andere Orcs nicht sehen. Ihr spüren den Puls des Universums um Euch. Ihr die Berührung der Magie besitzen und es Zeit, dass Ihr lernen, sie zu beherrschen.\n\nIhr finden Mai'ah, wenn Ihr bereit sein. Sie Euch lehren viel über Magie und die Zauber, die Ihr brauchen, um jene zu vernichten, die sich Euch in den Weg stellen.\n\nMai'ah sein nahe beim Höhlenbau im Tal der Prüfungen. Ihr kommen und sie finden, dann Ihr werden stark sein. Dann Ihr zeigen anderen Magiern, wie sich Magie Eurem Willen unterwerfen... und nicht anders herum." } } },
    ["Glyphic Scroll"] = { { ids = { "i9574" }, first = "thecorruptionandevilthat", pages = { "Das Verderbnis und das Böse, von dem behauptet wird, es gehe einher mit dem Arkanen, ist nichts im Vergleich zu dem Schmerz, den wir bereits zu spüren bekommen haben. Wir sind nicht länger Opfer, $N. Wir nehmen unser Schicksal selber in die Hand. Sylvanas hat uns den Weg geebnet - sie hat bewiesen, dass wir einen eigenen Willen haben, dass wir nicht länger die Knechte von diesem Bastard Arthas sind.\n\nSucht mich in der Kirche auf, ich werde Euch weiter unterweisen... so Ihr dies wünscht.\n\n- Isabella, Magielehrerin" } } },
    ["Glyphic Tablet"] = { { ids = { "i9575" }, first = "welcometoyourawakeningmo", pages = { "Willkommen zu Eurer Erweckung, Mann. Die Geheimnisse des Arkanen sein in Eurer Reichweite, wenn Ihr stark genug sein, sie zu verstehen.\n\nIhr finden Mai'ah, wenn Ihr bereit sein. Sie Euch lehren viel über Magie und die Zauber, die Ihr brauchen, um jene zu vernichten, die sich Euch in den Weg stellen.\n\nMai'ah sein nahe beim Höhlenbau im Tal der Prüfungen. Ihr kommen und sie finden, dann Ihr werden stark sein. Dann Ihr zeigen anderen Magiern, wie sich Magie Eurem Willen unterwerfen... und nicht anders herum." } } },
    ["Goblin Rumors"] = { { ids = { "i5804" }, first = "thegoblinnazzsteamboilis", pages = { "Der Goblin Nazz Steamboil ist eigentlich der Sohn eines goblinischen Händlerfürsten. (Welcher Fürst? Der Preis für diese Information ist hoch.)\n\nEr bringt seine Zeit wohl viel lieber damit zu, das Vermögen seiner Familie auf den Kopf zu hauen als es zu vermehren. Also hat er ein kleines Vermögen aus dem Familienhort gestohlen und sich damit in die schimmerende Ebene abgesetzt.\n\nWenn sein Vater wüsste, wo sich Sohnemann versteckt hält, würde er ihn sich nach Hause zurückschleifen lassen - abzüglich eines Zehs für seine Frechheiten." } } },
    ["Goodsteel Ledger"] = { { ids = { "i11727" }, first = "greetingsandsalutationsa", pages = { "Seid gegrüßt und willkommen, Abenteurer!\n\nIch, Krinkle Goodsteel, brauche Leute, die bereit sind, ihr Leben für ein äußerst schwieriges Unterfangen zu riskieren. Aufgrund der zahlreichen Pflichten und des damit verbundenen Arbeitspensums versichere ich, dass jeder, der tapfer genug ist, diese Liste von Gegenständen fertig zu stellen und sie mir unversehrt zu bringen, reich belohnt werden soll.\n\nDie Liste befindet sich auf den folgenden Seiten...", "Robuste Kristallbeinschäfte -\n\nDie Glasnetzspinnen der sengenden Schlucht bestehen aus einem unglaublichen, kristallähnlichen Material. Wenn ihre Beine beim Erlegen nicht beschädigt werden, taugen sie als erstklassige Leiter bei einigen Ingenieurskunstexperimenten meiner Gefährten.\n\nIch benötige ein paar davon für Tests. Die Spinnen mit ihren acht Beinen dürften für einen wackeren Krieger oder geübten Magier kein Problem darstellen.", "Ein überfälliges Päckchen.\n\nIch hatte einen Piloten angeheuert, den ich für zuverlässig hielt, damit er mir ein Päckchen aus Theramore bringt. Offenbar habe ich mich geirrt. Der Pilot hat zwar überlebt, ließ aber seinen gesamten Zeppelin und dessen Fracht zurück, um den eigenen Hals zu retten.\n\nAlso, ich brauche dieses Päckchen unbedingt. Wie Beezil mir sagte, musste er westlich der Bucht in den Marschen von Dustwallow notlanden. Er stürzte unmittelbar hinter den Hügeln an der Küste ab.\n\nHmmm... er hat mir nie gesagt, warum er notlanden musste...", "Goodsteels ausbalancierter Flamberg.\n\nZuletzt möchte ich noch mein bis zum heutigen Tag bestes Schmiedestück. Dieser Flamberg war ein unglaubliches Schwert, das ich einem, wie ich glaubte, höchst ehrbaren und großen Krieger überließ. Tja, er wurde von einem Murloc namens Jarquai in die Mangel genommen. So was in der Art jedenfalls.\n\nEs war so: Als er an der Küste der Sümpfe des Elends entlangreiste, kam es ihm in den Sinn, die Kreatur anzugreifen. Er unterlag und floh offenbar, ließ aber seine Waffe zurück, die der Murloc an sich nahm.", "Sucht mir diese Gegenstände und kehrt mit allen sowie mit diesem Geschäftsbuch nach Gadgetzan zurück und ich werde Euch belohnen." } } },
    ["Gordo's Report"] = { { ids = { "i286202" }, first = "appleyumyummepickflowers", pages = { "<Beeindruckenderweise ist auf den Resten der Apfelschale etwas kaum lesbares eingeschnitzt.>\n\nApfel jam jam. Ich jetzt pflücken Blumen." } } },
    ["Gozwin's Mechanic's Log"] = { { ids = { "i277976" }, first = "mechanicslogthiscommissi", pages = { "Mechanikerprotokoll\n\n<Das kleine ledergebundene Tagebuch ist mit Öl- und Fettflecken übersät. Es enthält Skizzen von Schaltplänen und mechanischen Konfigurationen, allesamt mit Anmerkungen und Beschreibungen versehen. Ihr schlagt eine zufällige Seite auf.>\n\nDieser Auftrag wird jahrelang für unseren Lebensunterhalt sorgen. Ich muss nur herausfinden, wie ich verhindern kann, dass sich der Oszillationsneutralisierer überhitzt oder sich selbst zu Metallspänen zermahlt. Ich muss die überschüssige Wärme mithilfe eines Vortextransfers in den Verbrennungskern umleiten. Aber ich habe das bisher aufgeschoben, weil ich dafür den ganzen Rahmen auseinanderbauen und dann den gesamten Motor zerlegen muss.\n\nSeite 17", "<Ihr blättert mit dem Daumen weiter durch das gebundene Papier und landet bei einem beidseitigen Diagramm.>\n\nWaffensystemanpassungen\n\nEisturm - Einsatzbereit\nFlammenwerfer - Einsatzbereit\nElektrischer Puls - Einsatzbereit\nStrahlungsspray - Einsatzbereit\nSturmgewehr - Einsatzbereit\nLaserstrahl - EXPERIMENTELL\nSchallkanone - EXPERIMENTELL\nPhasenstrahl - NUR ENTWURF\n\nSeite 34                                      Seite 35", "AUFGABEN\n\nAusrüstung für Jagdausflug einpacken\nFunktionshaken für Grunds Gürtel anfertigen\nSchweißvisier reparieren\nMama eine Karte schicken\n\nSeite 45" } } },
    ["Gramma Stonefield's Note"] = { { ids = { "i1252" }, first = "hellowilliamitsbeenyears", pages = { "Mein lieber William,\n\nJahre ist es her, seit wir uns das letzte Mal gesprochen haben. Ich hoffe inständig, Euch und Eurem Bruder geht es gut und Eure Apothekerdienste sind gefragt.\n\nNun muss ich Euch um einen Gefallen bitten, William. Ich will keine langen Worte machen. Mein Enkel Tommy Joe hat sein Herz an die junge Maybell Maclure verloren. Und sie könnten sich innig lieben, wenn unsere Familien... tja, unsere Familien leben seit Jahren in Fehde.", "Ich fürchte, die Fehde zwischen den Stonefields und den Maclures wird die zarte Romanze zwischen Tommy Joe und Maybell zerstören. Und gerade in Zeiten wie diesen, da es ständig neue schlechte Nachrichten gibt und Gerüchte über einen bevorstehenden Krieg an der Tagesordnung sind, müssen die Liebe und die Jugend geschützt werden.\n\nDeswegen erbitte ich also Folgendes von Euch: Ich bitte Euch, mit Euren Fertigkeiten einen Trank oder ein Elixier herzustellen, das diesen beiden Liebenden auf der Suche nacheinander hilft.\n\nHabt Dank, William. Und bitte, solltet Ihr neben Eurer Arbeit etwas Zeit erübrigen können, so kommt doch vorbei. Dann können wir ein wenig über vergangene Zeiten plaudern.\n\n- Mildred" } } },
    ["Grand Admiral Daelin Proudmoore"] = { { ids = { "o177201" }, first = "commanderofthealliancefl", pages = { "Kommandant der Allianz-Flotten\n\nFreund von Stormwind" } } },
    ["Grape Manifest"] = { { ids = { "i11125" }, first = "brothernealsmygrapesares", pages = { "Bruder Neals,\n\nmeine Trauben sind gerettet! $N, der Überbringer dieses Manifests, wagte sich in meinen von Rohlingen überrannten Weinberg und holte die Trauben, da ich es nicht konnte. Zwar kommen die Defias immer noch über den Fluss, aber fast meine gesamte Ernte wurde eingebracht.\n\nIhr könnt Euren Vorräten eine volle Ladung Trauben hinzufügen.\n\nMöge das Licht uns beschützen.\n- Milly Osworth" } } },
    ["Green Hills of Stranglethorn - Chapter I"] = { { ids = { "i2756" }, first = "ourfirstdaywentaswellaso", pages = { "Dafür, dass es unser erster Tag war, lief es heute eigentlich erstaunlich gut. Wir verbrachten einen Großteil der Zeit mit den Vorbereitungen für den Bau eines Basislagers. Ich hatte den idealen Ort dafür am Frischwasserzulauf eines Flusses ausgemacht. Den alten verlassenen Docks nach zu urteilen, war dieser Ort sogar einmal bewohnt gewesen. Doch die einstigen Bewohner sind längst Vergangenheit.", "Für diese Expedition habe ich Ajeck Rouack und Sire S. J. Erlgadin um mich geschart. Zudem steht mir mein getreuer Diener Barnil Stonepot zur Seite. Ich habe an der Seite von Ajecks Vater gar manche Schlacht zur Verteidigung der Allianz gefochten. Sie jetzt erwachsen zu sehen, berührt mich eigentümlich. Ihr Vater hat sie gut in der Waffenkunst unterrichtet. Sie geht so geschickt mit dem Bogen um, dass ich mich frage, ob Elfenblut in ihren Adern fließt.", "Sire S. J. Erlgadin entstammt dem menschlichen Adel. Sein Vater war der für seine Großzügigkeit bekannte Graf Erlgadin. Der Graf war es, der sich während des Wiederaufbaus von Stormwind nach dem Zweiten Großen Krieg für bessere Arbeitsbedingungen für die Steinmetzgilde einsetzte.", "In den Jahren nach dem Verrat Stormwinds an der Steinmetzgilde erfüllte die Rolle, die der Adel im Königreich spielte, Sire Erlgadin zunehmend mit Gram. Er wollte die Stellung, die er von seinem Vater im Oberhaus geerbt hatte, nicht länger wahrnehmen. Aber ich schweife ab. Dies hier soll ja keine politische Abhandlung oder Biografie werden. Vielmehr geht es hier um meine Erfahrungen mit der Großwildjagd in den grünen Hügeln des Schlingendorntals.", "Wir standen beim ersten Sonnenstrahl auf. Barnil machte das Frühstück. Mir fiel auf, dass Ajeck irgendwie irritiert wirkte. Wir hatten einen langen Weg vor uns und unsere Jagd versprach, ziemlich gefährlich zu werden. Eine einzige Unachtsamkeit konnte schlimme Folgen haben. Doch Ajeck konnte ihren Blick anscheinend nicht von Barnil wenden, der am Flussufer ein paar Sachen abwusch.", "Gerade als ich fragen wollte, ob Ajeck denn nicht an der heutigen Jagdstrategie interessiert sei, griff sie nach ihrem Köcher, zog einen Pfeil heraus und schoss ihn just auf unseren armen Barnil ab. Aber der Schuss galt gar nicht Barnil. Denn als der offenen Mundes einen Schritt zur Seite machte, trieb ein großer Flusskrokilisk an die Oberfläche. Ajecks Pfeil steckte genau zwischen seinen großen Augen.", "Wir gingen Richtung Westen durch das Dickicht des Urwalds. Langsam und vorsichtig bahnten wir uns auf der Suche nach Beute unseren Weg durch das Unterholz. Der Morgen verging und nichts passierte. Nicht einmal ein Lufthauch regte sich im Tal. Bis zum Nachmittag hatte sich Unruhe in unserer Expedition breit gemacht. Barnil ließ es an der für einen Jäger so wichtigen Vorsicht mangeln. Er stapfte ziemlich ungeschickt vor sich hin und trat oft auf trockenes Laub oder herabgefallene Zweige.", "Nach einem solchen Fehltritt legte Erlgadin Barnil die Hand schwer auf die Schulter. Ajeck und ich schauten beiläufig. Wir dachten, Erlgadin würde Barnil ob seiner Unvorsichtigkeit endlich einmal die Leviten lesen. Aber Erlgadin wies mit einer langsamen Kopfbewegung in Richtung eines umgestürzten Baumes ganz in der Nähe. Zwei stechend schwarze Augen über einem Maul voller rasiermesserscharfer Zähne starrten uns an." } } },
    ["Green Hills of Stranglethorn - Chapter II"] = { { ids = { "i2757" }, first = "thebeastwasamalestrangle", pages = { "Es handelte sich um einen männlichen Schlingendorntiger. Ehe ich auch nur nach meiner Büchse greifen konnte, hatte Erlgadin schon einen Armbrustbolzen abgefeuert. Der Bolzen verfehlte sein Ziel und traf den Tiger nur in der linken Flanke. Er versuchte zu fliehen, aber die Wunde war zu schwer. Das Wildtier taumelte noch einige Sekunden angeschlagen herum, ehe Barnil ihm mit seiner Wurfaxt den Gnadenstoß versetzte.", "Danach waren wir alle in Hochstimmung. Barnin gab eine Runde Met für alle aus. Aber die Freude sollte nicht lange währen. Denn als wir den Kadaver für den Rücktransport zum Stützpunkt fertig machten, hörten wir unvermittelt ein fürchterliches Heulen. In all den Jahren habe ich noch nie etwas so Schreckliches gehört.", "Auf einer felsigen Anhöhe über uns hob sich gegen das Licht der untergehenden Sonne die Silhouette der größten Raubkatze ab, die ich je gesehen habe. Ich gab einen eher unbeholfenen Schuss in Richtung des Tiers ab, das sich davon aber unbeeindruckt zeigte. Die Raubkatze ließ erneut ein Knurren ertönen, lauter noch als beim ersten Mal, und verschwand.\n\nWir packten unsere Sachen und kehrten gut gelaunt ins Lager zurück.", "Ich hatte meinen Begleitern versprochen, dass wir am nächsten Tag Panther jagen würden, da deren Felle in Azeroth sehr gefragt sind. Diese Nachfrage lässt sich nur damit erklären, dass all die fähigen Jäger, Fallensteller und Pelzhändler fort sind und ihr Leben im Namen der Allianz lassen.", "Ajeck und Sire Erlgadin waren ganz erpicht darauf zu lernen, wie man Zwergen-Gewehre einsetzt. Daher hatte ich die beiden Menschen angewiesen, ihre primitiven Distanzwaffen im Stützpunkt zu lassen. Barnil und ich statteten sie also mit den besten Feuerwaffen aus Ironforge aus.", "Wir hielten uns nach Süden und folgten einigen frischen Pantherspuren. Kurz darauf kamen wir an eine Klamm, die von einer phantastischen Hängebrücke überspannt wurde. Ich musste sofort an Branns eindrucksvolle Beschreibungen des Gebiets denken, als ich dieses technische Wunderwerk sah. Es wurde oft behauptet, die einheimischen Trolle seien primitiv und ungebildet, doch als ich auf dieses handwerkliche Meisterwerk blickte, erkannte ich mit einem Mal das außerordentliche Können, mit dem die Erbauer der Trolle das schier unüberwindliche Hindernis überwunden hatten.", "Bald darauf spürte Ajeck im Südwesten den Panther auf. Leise schlichen wir weiter, die Flinten im Anschlag. Das Knacken von Zweigen im Unterholz ließ uns aufhorchen. Da war etwas. Ein Blick genügte, um mich mit Barnil zu verständigen. Er nahm langsam die Flinte herunter. Dieser Abschuss war nicht für uns bestimmt, er sollte unseren menschlichen Freunden gehören. Unzählige Panther waren schon von unseren Flinten zur Strecke gebracht worden. Dieser hier würde von den Menschen erlegt.", "Ajeck und Sire Erlgadin standen unbeweglich und hielten ihre Flinten auf das dichte Buschwerk unter den sanft schwingenden Bäumen gerichtet. Die Mittagssonne brannte auf uns nieder. Ein kleiner Schweißtropfen rann an Erlgadins Schläfe herab, als er den Hahn spannte. In dem Moment, als der Hahn einrastete, teilte sich mit einem Mal das Dickicht und ein großer schwarzer Panther - ein schönes Exemplar - preschte hervor." } } },
    ["Green Hills of Stranglethorn - Chapter III"] = { { ids = { "i2758" }, first = "thehumanstrainedtheirsit", pages = { "Die Menschen nahmen den Panther aufs Korn, während dieser am Waldrand entlanglief. Die Läufe ihrer Flinten bewegten sich absolut synchron. Barnil warf mir einen drängenden Blick zu, aber ich schüttelte verneinend den Kopf. Diese Jagd war für die Menschen und nicht für Barnil und mich. Erlgadin feuerte, doch er verfehlte den Panther. Auf den starken Rückstoß des Gewehrs war er nicht gefasst.", "Die Büchse ruckte heftig zurück. Er verriss den Schuss seitwärts und geriet mit dem Lauf just unter Ajecks Flinte. Ajeck ihrerseits hatte genau diesen Moment abgepasst, um abzudrücken. Der Schuss verirrte sich irgendwo in die Bäume. Ein Schwarm Vögel flog kreischend aus dem Blätterdach auf und flatterte aufgeregt in alle Himmelsrichtungen davon. Eine Wolke Pulverdampf stieg über einem Baum auf. Fassungslos sahen wir mit an, wie ein gewaltiger Ast geradewegs auf den flüchtenden Panther fiel und ihm das Rückgrat brach.", "Im Laufe der Wochen vergrößerte sich unser Bestand an Panther- und Tigerfellen immens. Daher entschied ich, dass wir uns einem neuen Ziel zuwenden sollten: Raptoren.\n\nSo dankbar die Menschen auch für die Schießübungen waren, die Barnil und ich mit ihnen machten, sie wollten doch von der Benutzung der Feuerwaffen Abstand nehmen. Ajeck kam mit ihrem fein gearbeiteten Bogen weit besser zurecht und Sire Erlgadin verließ das Lager ohnehin nie ohne seine stabile Armbrust.", "Wir machten uns beim ersten Tageslicht in Richtung Süden zu den Tkashi-Ruinen auf. Barnil äußerte sich besorgt, dass wir auf Mitglieder des Bloodscalpstamms treffen könnten. Ich erinnerte ihn daran, dass die Bloodscalps mehr mit der Vernichtung des verfeindeten Skullsplitterstamms beschäftigt waren. Ich brauche wohl nicht zu betonen, dass Barnil alles andere als beruhigt war. Ich für mein Teil vertraute jedoch auf meine geladene Flinte, einen Ranzen Schießpulver und die drei versierten Jäger neben mir und machte mir keine Gedanken über einen möglichen Hinterhalt.", "Ich stand vor einer riesigen Höllenbestie auf dem Schlachtfeld und die Armee der Brennenden Legion näherte sich von allen Seiten. Dagegen wirkt eine Bande Trolle so harmlos wie ein Kaninchen in den Hügeln von Dun Morogh.\n\nWir passierten die Tkashi-Ruinen ohne Zwischenfall, worüber insbesondere Barnil sehr erleichtert war. Die Gruppe ging weiter westwärts Richtung Großes Meer und streifte die Ruinen von Zul'Kunda im Süden. Als wir die Steilküste erklommen, sahen wir ihn: unseren ersten Raptor.", "Das Tier nahm uns noch nicht einmal wahr. Das Einzige, was es von der Expedition mitbekam, war eine Kugel zwischen seinen Augen. Sire Erlgadin ließ ein herzliches \"Hurra!\" hören und Ajeck nickte mir anerkennend zu. Ich kramte in meiner Tasche, weil ich mir zur Feier des Tages ein Pfeifchen gönnen wollte. Barnil kletterte die Anhöhe hinauf, um den Kadaver des Raptors zu holen. Äußerst zufrieden betrachtete ich das tote Vieh.", "Die Freude über den Erfolg währte jedoch nicht lange. Denn als ich zum Horizont blickte, sah ich auf dem Hügel genau über dem armen Barnil gleich mehrere Silhouetten.\n\n\"Lauf, Barnil!\", schrie ich. Ajeck, Sire Erlgadin und ich feuerten aus allen Rohren auf die heranstürmenden Raptoren und deckten sie mit Kugeln, Pfeilen und Bolzen ein. Einer der Raptoren ging tödlich getroffen zu Boden.", "Unsere hastig abgefeuerten Schüsse ermöglichten Barnil die Flucht. Barnil stolperte den Hügel wieder hinunter und schloss sich uns erneut an. Wir schlugen uns in den Urwald, wobei das Rudel Schmetterschwanzraptoren jede unserer Bewegungen genau verfolgte.\n\nAus Jägern waren Gejagte geworden." } } },
    ["Green Hills of Stranglethorn - Chapter IV"] = { { ids = { "i2759" }, first = "iledthepartytowardthesea", pages = { "Ich führte die Gruppe in Richtung Meer und hoffte, dass wir an der Küste Schutz vor den Raptoren finden würden. Doch in unserer Hast waren wir zu weit nach Norden abgekommen und befanden uns auf einer gefährlich hohen Erhebung. Das war ein Fehler. Und ich war schuld. Plötzlich standen wir vor steil abfallenden Klippen, die Raptoren nur noch ein paar Schritte hinter uns.", "Ich trat langsam mit erhobener Flinte vor. Ich hatte diese mutigen Jäger ins Verderben geführt. Also wollte ich auch bei ihrer Verteidigung sterben. Schmetterschwanzraptoren sind besonders angriffslustig und bekannt für ihren unstillbaren Blutdurst. Zudem waren sie uns zahlenmäßig weit überlegen. Doch ich wollte verdammt sein, wenn sie mich und meine Kameraden töten könnten, ohne dabei selbst Verluste zu erleiden.", "Ajeck und Sire Erlgadin machten ihre Waffen bereit und gaben mir seitlich Deckung, während wir mit dem Rücken zum Wasser standen. Barnil seufzte ergeben und zog seine Axt. Die Schmetterschwanzraptoren waren schon ganz nah. Sie wurden langsamer. Sie pirschten sich an ihre Beute heran, wussten sie doch, dass wir ihnen nicht mehr entkommen konnten.", "Da geschah das Unglaubliche: Neben uns hörten wir plötzlich das erschreckende Gebrüll des großen weißen Tigers. Augenblicklich drehten die Raptoren ab und stoben in alle Richtungen davon. Wir sahen nur einen weißen Blitz, als der Tiger an uns vorbeischoss und sich auf einen der Raptoren stürzte. Befehle waren unnötig. Wir alle vier wussten, dass es galt, die Beine in die Hand zu nehmen.", "Wir rannten so schnell es ging und ohne Pause zurück zum Stützpunkt. Abends saßen wir noch lange still ums Lagerfeuer herum, wussten wir doch nur zu gut, dass wir unser Leben allein einer merkwürdigen Wendung des Schicksals zu verdanken hatten. Das sind die Risiken eines Großwildjägers. Man spielt mit dem Schicksal, wenn man es herausfordert. Und doch bekommt jeder von uns irgendwann die messerscharfen Zähne seines Schicksals zu spüren. Dieser Zwerg hier ist einfach nur froh, dass dieser Augenblick ihn nicht auf den grünen Hügeln des Schlingendorntals ereilt hat." } } },
    ["Green Hills of Stranglethorn - Page 1"] = { { ids = { "i2725" }, first = "thegreenhillsofstranglet", pages = { "Die Grünen Hügel des Schlingendorntals\n\nDafür, dass es unser erster Tag war, lief es heute eigentlich erstaunlich gut. Wir verbrachten einen Großteil der Zeit mit den Vorbereitungen für den Bau eines Stützpunkts. Ich hatte den idealen Ort dafür am Frischwasserzulauf eines Flusses ausgemacht. Den alten verlassenen Docks nach zu urteilen war dieser Ort sogar einmal bewohnt gewesen. Doch die ursprünglichen Bewohner sind längst Geschichte." } } },
